window.HAIFENG_MANUSCRIPT={"meta":{"title":"海風有名","collection":"王家傳・第一輯・第一代","version":"2026 年 10 月｜第二輪校樣・非出版定稿","pages":148,"editorNote":"本稿改編自家族口述，小說事件、對話及具體衝突含虛構創作；涉及在世人物的敏感情節公開前須匿名化審閱。"},"parts":[{"name":"第一部｜井下之年","page":7,"part":"第一部","label":"井下之年"},{"name":"第二部｜海上與婚前","page":22,"part":"第二部","label":"海上與婚前"},{"name":"第三部｜春潮初上","page":35,"part":"第三部","label":"春潮初上"},{"name":"第四部｜紅燈兩面","page":52,"part":"第四部","label":"紅燈兩面"},{"name":"第五部｜兩種價錢","page":64,"part":"第五部","label":"兩種價錢"},{"name":"第六部｜門裡生變","page":79,"part":"第六部","label":"門裡生變"},{"name":"第七部｜燈熄之後","page":91,"part":"第七部","label":"燈熄之後"},{"name":"第八部｜鞋與人情","page":103,"part":"第八部","label":"鞋與人情"},{"name":"第九部｜市場的路","page":118,"part":"第九部","label":"市場的路"},{"name":"第十部｜海風與後人","page":130,"part":"第十部","label":"海風與後人"}],"chapters":[{"name":"第一回｜社寮的洞口","page":7,"index":1,"part":1,"label":"社寮的洞口"},{"name":"第二回｜女人把孩子藏起來","page":11,"index":2,"part":1,"label":"女人把孩子藏起來"},{"name":"第三回｜不能問的人","page":13,"index":3,"part":1,"label":"不能問的人"},{"name":"第四回｜消失的工牌","page":16,"index":4,"part":1,"label":"消失的工牌"},{"name":"第五回｜軍衣穿過海峽","page":18,"index":5,"part":1,"label":"軍衣穿過海峽"},{"name":"第六回｜海上有兩種命令","page":22,"index":6,"part":2,"label":"海上有兩種命令"},{"name":"第七回｜王先生最會說話","page":24,"index":7,"part":2,"label":"王先生最會說話"},{"name":"第八回｜她不吃這一套","page":27,"index":8,"part":2,"label":"她不吃這一套"},{"name":"第九回｜彩雲把燈關了一半","page":30,"index":9,"part":2,"label":"彩雲把燈關了一半"},{"name":"第十回｜紅紙寫錯的名字","page":32,"index":10,"part":2,"label":"紅紙寫錯的名字"},{"name":"第十一回｜春潮開張","page":35,"index":11,"part":3,"label":"春潮開張"},{"name":"第十二回｜夜裡第一盞燈","page":37,"index":12,"part":3,"label":"夜裡第一盞燈"},{"name":"第十三回｜紅燈底下的女人","page":41,"index":13,"part":3,"label":"紅燈底下的女人"},{"name":"第十四回｜阿綺替自己取名字","page":43,"index":14,"part":3,"label":"阿綺替自己取名字"},{"name":"第十五回｜彩雲的兩本帳","page":47,"index":15,"part":3,"label":"彩雲的兩本帳"},{"name":"第十六回｜一座店兩個掌櫃","page":52,"index":16,"part":4,"label":"一座店兩個掌櫃"},{"name":"第十七回｜客人未走，天已亮","page":54,"index":17,"part":4,"label":"客人未走，天已亮"},{"name":"第十八回｜聽見別人的名字","page":56,"index":18,"part":4,"label":"聽見別人的名字"},{"name":"第十九回｜一封沒有寄出的信","page":59,"index":19,"part":4,"label":"一封沒有寄出的信"},{"name":"第二十回｜麗華的還鄉路","page":61,"index":20,"part":4,"label":"麗華的還鄉路"},{"name":"第二十一回｜衣裳與人","page":64,"index":21,"part":5,"label":"衣裳與人"},{"name":"第二十二回｜一桌不肯散的酒","page":66,"index":22,"part":5,"label":"一桌不肯散的酒"},{"name":"第二十三回｜一席酒的價錢","page":69,"index":23,"part":5,"label":"一席酒的價錢"},{"name":"第二十四回｜孩子也會替大人撒謊","page":72,"index":24,"part":5,"label":"孩子也會替大人撒謊"},{"name":"第二十五回｜三個孩子的屋子","page":76,"index":25,"part":5,"label":"三個孩子的屋子"},{"name":"第二十六回｜一雙小鞋三種脾氣","page":79,"index":26,"part":6,"label":"一雙小鞋三種脾氣"},{"name":"第二十七回｜門裡門外","page":81,"index":27,"part":6,"label":"門裡門外"},{"name":"第二十八回｜門口的陌生鞋","page":84,"index":28,"part":6,"label":"門口的陌生鞋"},{"name":"第二十九回｜有客上門","page":86,"index":29,"part":6,"label":"有客上門"},{"name":"第三十回｜誰記得那聲汽笛","page":88,"index":30,"part":6,"label":"誰記得那聲汽笛"},{"name":"第三十一回｜救護車走後","page":91,"index":31,"part":7,"label":"救護車走後"},{"name":"第三十二回｜一口飯也沒有停","page":93,"index":32,"part":7,"label":"一口飯也沒有停"},{"name":"第三十三回｜春潮落時","page":96,"index":33,"part":7,"label":"春潮落時"},{"name":"第三十四回｜最後一次點燈","page":98,"index":34,"part":7,"label":"最後一次點燈"},{"name":"第三十五回｜和平店早晨","page":100,"index":35,"part":7,"label":"和平店早晨"},{"name":"第三十六回｜和平店的賒帳簿","page":103,"index":36,"part":8,"label":"和平店的賒帳簿"},{"name":"第三十七回｜樹林與眾生","page":105,"index":37,"part":8,"label":"樹林與眾生"},{"name":"第三十八回｜樹林的第一雙鞋","page":110,"index":38,"part":8,"label":"樹林的第一雙鞋"},{"name":"第三十九回｜蘇家的孩子","page":112,"index":39,"part":8,"label":"蘇家的孩子"},{"name":"第四十回｜兩條路上的孩子","page":114,"index":40,"part":8,"label":"兩條路上的孩子"},{"name":"第四十一回｜靜菊的布","page":118,"index":41,"part":9,"label":"靜菊的布"},{"name":"第四十二回｜市場收攤以後","page":120,"index":42,"part":9,"label":"市場收攤以後"},{"name":"第四十三回｜衛國少年","page":123,"index":43,"part":9,"label":"衛國少年"},{"name":"第四十四回｜衛國第一次出遠門","page":125,"index":44,"part":9,"label":"衛國第一次出遠門"},{"name":"第四十五回｜兩個男人，一張桌子","page":127,"index":45,"part":9,"label":"兩個男人，一張桌子"},{"name":"第四十六回｜彩雲見過的年輕人","page":130,"index":46,"part":10,"label":"彩雲見過的年輕人"},{"name":"第四十七回｜長青席上","page":133,"index":47,"part":10,"label":"長青席上"},{"name":"第四十八回｜新年照相館","page":136,"index":48,"part":10,"label":"新年照相館"},{"name":"第四十九回｜海風有名","page":139,"index":49,"part":10,"label":"海風有名"},{"name":"第五十回｜下一個名字","page":142,"index":50,"part":10,"label":"下一個名字"}],"pages":[{"pdf":1,"blocks":[{"type":"cover","text":"王家傳｜海風有名"}],"running":"卷首","section":"第一輯｜第一代"},{"pdf":2,"blocks":[{"type":"p","text":"王家傳第一輯・第一代《海風有名》井下春秋，燈火人間校改版本說明（第二輪）：本稿保留第一輪已修訂之五十回結構，第二輪實際全文重寫第6、8、16、22、35、39、49、50 回，共八回；其他回目的文字尚非第二輪定稿。附錄所述「第一輪」修改數量係保留的舊版修稿紀錄。本稿以家庭口述為起點，但新加入的事件、對話、具體衝突均屬小說虛構；部分在世人士的敏感情節須於公開出版前另做匿名化審閱。主要人物｜人各有其難"},{"type":"p","text":"王居萬：善交際、好面子，曾從軍、經商，晚年參與地方長者社群；慷慨與逃避責任可能在他身上同時存在。"},{"type":"p","text":"王黃彩雲：做事慎密，話不多卻不肯被人擺布。她對愛情仍有期待，也知道自己不能只為丈夫的故事活。"},{"type":"p","text":"王曉芬／王俊明／王美玲：三名子女。同住一屋，各自記住不同的傷與愛；第二輯將由他們承接主線。"},{"type":"p","text":"王樹林（後更名王螢家）／李心為：平行家族線。樹林做鞋生意，從腳底下的買賣逐漸走向更大的市場；與王居萬的具體親屬關係仍待考。"},{"type":"p","text":"林銀叔／林王靜菊／林衞國：林家交錯副線。童年離散、礦坑與市場生活，如何把一個青年推向職場與下一代愛情。"},{"type":"p","text":"麗華／阿綺／月琴：春潮酒店虛構女侍群像。各有想離開的地方，也各有想回去的地方。"},{"type":"p","text":"阿泉／素珍：以社寮島戰後受難者歷史為背景創作的虛構角色，不對應具名受難者。"}],"running":"卷首","section":"第一輯｜第一代"},{"pdf":3,"blocks":[{"type":"toc","text":"目次｜五十回"}],"running":"卷首","section":"第一輯｜第一代"},{"pdf":4,"blocks":[{"type":"chapter","text":"序章｜壽宴上的兩種光"},{"type":"p","text":"王居萬八十歲那日，親友替他排好座位，請他坐在正中。椅背高，靠得太久，肩膀便要往前。有人見他坐得不舒坦，忙把枕墊塞到後頭；他卻說不用，笑著將枕墊拿開，好像當年有誰要替他整一整軍服，他也要說同樣的話。"}],"running":"序章｜壽宴上的兩種光","section":"第一輯｜第一代"},{"pdf":5,"blocks":[{"type":"p","text":"宴席未開，三代人在燈下各自忙碌。有人核對人數，有人拿手機找角度，有人已把「八十」二字說得極響，彷彿把聲音喊大，歲月便會顯得隆重一些。"},{"type":"p","text":"一個年輕晚輩將照片放在他面前。"},{"type":"p","text":"「阿公，這是不是你以前的店？」"},{"type":"p","text":"照片發黃，影像邊緣有一道皺摺。相紙上有一塊招牌，燈泡排成一圈，門前站著兩名衣著整齊的男女；其中一個男人像極了年輕時的王居萬。誰也說不清照片攝於何時，連那塊招牌究竟是不是他的店，也還等著辨認。"},{"type":"p","text":"居萬只看了一眼，便將照片翻過來。"},{"type":"p","text":"「那個時候，很熱鬧。」"},{"type":"p","text":"晚輩想再問，他已轉頭向進門的老朋友招手。老友隔著幾桌大聲說："},{"type":"p","text":"「你還記得以前那一班姑娘嗎？」"},{"type":"p","text":"幾個男人笑了。坐在另一頭的彩雲沒有笑。她正替一個小孩擦嘴，紙巾摺得方方正正。有人以為她沒有聽見，只有她自己知道，那些年的人聲，從來不是一場宴席便能講完的。"},{"type":"p","text":"台上燈光亮起。司儀請大家舉杯，一張張臉在玻璃後頭被折成小小的影子。居萬舉了杯，卻沒立刻喝。"}],"running":"序章｜壽宴上的兩種光","section":"第一輯｜第一代"},{"pdf":6,"blocks":[{"type":"p","text":"他忽然想起另一種光。不是今日這樣亮的，也不是酒店裡紅紅綠綠的。那光很低，從一個窄小的洞口落下來，旁邊有水滴聲。是他自己的記憶，還是別人講了一輩子以後，替他做出的夢，他也辨不清。"},{"type":"p","text":"「來，王先生，看這邊！」"},{"type":"p","text":"快門一閃。"},{"type":"p","text":"八十歲的王居萬抬起頭，終於笑了。"},{"type":"p","text":"笑容給人拍了下來。至於其餘那些不能拍的，且從海那一頭說起。"}],"running":"序章｜壽宴上的兩種光","section":"第一輯｜第一代"},{"pdf":7,"blocks":[{"type":"part","text":"第一部｜井下之年"},{"type":"chapter","text":"第一回｜社寮的洞口"},{"type":"p","text":"社寮島從前不叫和平島。名字是人的事，島卻不管。它見過不同的船、不同的制服，見過漁網晾得如旗，也見過一夜之間整條街收了聲息。"},{"type":"p","text":"一九四七年三月，島上有人聽見槍聲。基隆的街道、港邊與社寮一帶，那些天確實出現了軍事暴力、逮捕與失蹤。那幾日，海仍按時漲退，卻沒有誰敢憑海潮推算明天。"},{"type":"p","text":"後來王家有人說，王居萬曾躲在井蓋下。說的人未必在場，聽的人也未必追問：他那時不過一兩歲，如何知道躲藏，又怎麼記得方向？話傳久了，像把一張照片翻來覆去，紙面磨得薄，影子反倒愈見清楚。"},{"type":"p","text":"那一夜，有一個後人不知其名的婦人。"},{"type":"p","text":"她抱著孩子，穿過一條潮濕的窄巷。後頭有人催：「快些。」又有人說：「別出聲。」孩子不懂什麼是鎮壓，更不懂什麼是政權。他只是餓了，嘴唇在黑暗裡找著熟悉的衣襟。"},{"type":"p","text":"有人掀開一處遮蓋，把他們引到低矮的地方。那地方又窄又黑，後來有人說是井，有人說像排水的暗渠。故事傳了多年，洞口的模樣早已各不相同。婦人將孩子抱得緊，低頭時額頭擦過粗糙的牆。她不哭，因為孩子一聽見她哭，便可能跟著哭。"}],"running":"第一回｜社寮的洞口","section":"第一部｜井下之年"},{"pdf":8,"blocks":[{"type":"p","text":"上頭有腳步，有不知誰的叫喊，有一聲忽然中止的犬吠。她數著滴水聲，一滴，一滴，又一滴。數到後來，忘了自己數的是時間，還是尚能聽見的心跳。"},{"type":"p","text":"孩子終於睡了。"},{"type":"p","text":"多年以後，人們會把這樁事講得驚險：王家的小孩如何逃過一劫，像命裡有人保佑。然而當夜的婦人沒有工夫想命。她只想讓孩子不要受冷，還想著灶裡的火到底熄了沒有。"},{"type":"p","text":"大歷史進屋，最先遭殃的往往是這些小事。"},{"type":"p","text":"那夜之前，婦人本來正要把剛洗好的衣裳收到屋裡。風吹得衣袖一左一右地晃，晃得像有人站在暗處招手。她還記得灶上有一鍋粥，米沒有下足，打算添兩把番薯。這樣的日子既窮又安穩，窮是她自己知道的，安穩卻是直到安穩沒有了，才知道原來曾經有過。"},{"type":"p","text":"隔壁一位老婆婆來拍門，拍得急，卻不敢喊名字。婦人開了一條縫，聽見婆婆說港邊有事，叫她先把孩子抱好。她問是什麼事，婆婆閉著嘴不肯答，只往後望了一眼。那一眼比任何回答都快。婦人回屋，先拿了件小衣服，接著竟走去把鍋蓋蓋緊。人遇到驚慌，最先做的常不是最要緊的事，而是最熟悉的事；她把鍋蓋蓋緊，才相信自己的手還能聽話。"},{"type":"p","text":"孩子被抱到暗處時，她一直怕他打噴嚏。平日孩子打噴嚏，眾人都說長得快，說吉利話；眼下她竟怕那小小一聲，便會把躲藏的地方告訴外頭。她將手掌貼著孩子的背，想起自己曾嫌他夜裡哭個不停，那時恨不得"}],"running":"第一回｜社寮的洞口","section":"第一部｜井下之年"},{"pdf":9,"blocks":[{"type":"p","text":"有人把孩子抱走半個時辰。如今真有人要伸手抱他，她卻連那人的面孔也不敢看清。這樣相反的念頭，她後來一輩子也沒向人說起。"},{"type":"p","text":"那天以前，島上的日子也不是沒有叫人害怕的事。港裡一艘船若晚歸，女人們便沿著岸堤站成一道彎；風浪太大，男人出門時講的最後一句話，也許便是全家在飯桌上反覆講的那一句。然而風浪總有方向，天候總有徵兆，最不濟還能抬頭望雲。那年三月的恐懼不一樣：人們不曉得該向誰問，也不曉得自己的問話會不會害了旁人。巷子裡有戶人家賣醬菜，老闆娘有一雙指甲磨得短短的手。她過去慣常站在門邊招呼客人，哪怕誰只買一小包鹹蘿蔔，她也要多塞一片進紙袋。風聲緊的那些日子，她照樣把醬菜攤出來，卻將寫有各樣價格的木牌一一倒扣。有人問她怎麼不標價，她說：「價錢天天漲，怕算錯了。」其實她怕寫在板上的姓名與筆跡，怕有人拿著一塊不相干的木牌來盤問這家的主人。傍晚阿泉從巷口走過，見她坐在階前，便問今日生意如何。她說好得很，隨手又多裝了一包菜給他，堅持不收錢。阿泉笑道：「這麼好，明日我再來。」女人的臉色忽然變了，像那「明日」兩字有什麼忌諱。他沒看出來，提著醬菜往家走。待身影轉過街角，女人才把剩下的木牌收進籃裡。往後她每年三月都會想起這句話：明日我再來。她並不以為那話是預兆，只覺得人活一輩子，總有許多再平常不過的話，說完竟再沒有機會兌現。後來王家的人替那口井尋過位置，有人說在舊屋後頭，有人堅持該在轉進小巷的地方。兩個老人幾乎為此爭起來，一個說自己親眼看見，另一個說自己問過親戚。年輕人忙著勸，卻突然想起：倘若那天人人只顧著逃，誰會有心思把每個門牌記住？他們於是畫下一張不十分準確的圖，把相異的說法各留一行，沒有把"}],"running":"第一回｜社寮的洞口","section":"第一部｜井下之年"},{"pdf":10,"blocks":[{"type":"p","text":"誰的記憶擦去。這幅圖多年後夾進一冊家族舊簿，成為整部故事第一張沒有答案的證物。"},{"type":"p","text":"多年後，素珍的兒子沿著舊碼頭走過一次。他已是中年，別人說起父親時，仍常叫他「那個沒回來的人」。他忽然很想知道，父親最後一年裡有沒有對誰生過氣，有沒有買過不合用的東西，有沒有偷閒去聽一回戲。母親留下的工牌、購物單都在，偏最尋常的那些瑣事再也無人能答。他繞過一座新砌的牆，發現舊路幾乎認不得，海面卻還那麼寬，船仍一道道出港。"},{"type":"p","text":"那日一位老人坐在門口削水果，見他東張西望，問是不是找人。他說找一個早不在的人。老人聽了，沒有像旁人那樣立刻追問是誰，只給他一張小椅子，叫他先坐。兩個陌生人坐著看船，半晌老人說自己在這裡住了一輩子，街變了幾回，連海味都不大像當年。他問老人，記不記得以前的造船工人。老人答有些記得，有些忘了，還勸他若真要問，明日可帶照片過來。"},{"type":"p","text":"他原以為尋人應當是一件悲痛的大事，到了這裡卻必須先學會把照片裝進紙袋、把老人的地址記清、把「謝謝」講得自然。他回去以後，翻出母親那張泛黃的購物單，突然決定不把它藏起來，而是放進一本簿子，旁邊寫下：父親喜歡吃甜的。這未必比事件年表重要，卻使他第一次覺得，父親沒有只剩下失蹤那一天。"},{"type":"p","text":"地面上傳來人跑過的聲音。有人跌倒，似乎還滾了什麼鐵器。婦人原想祈求平安，張了張嘴，發現連神明的名字也怕叫得太響。她只好在心裡數：一、二、三。數到幾百便錯了，錯了又從頭。許多年後家裡有人談起"}],"running":"第一回｜社寮的洞口","section":"第一部｜井下之年"},{"pdf":11,"blocks":[{"type":"p","text":"「井蓋」兩字，說小孩當年真有福氣。她若能回答，怕是要說，哪裡是福氣，不過有人把一生最害怕的一刻熬過去了。"},{"type":"chapter","text":"第二回｜女人把孩子藏起來"},{"type":"p","text":"人們多年後說起一九四七年的春天，總愛問誰見著了槍，誰聽見了喊聲。其實更難答的，是那一日有多少女人明知外面出了事，仍須照常將水燒開、把飯悶熟。生死大事到了灶間，便成了米少下多少、火該不該熄的問題。"},{"type":"p","text":"有個婦人抱著孩子，從後門閃進潮濕的小巷。巷盡頭是一只鐵蓋，蓋底下通著水道，平日小孩不敢靠近，夏天還有一股悶熱的氣味。有人招手，要她先藏好孩子。婦人停了一瞬，並未立即照做。她不是不怕兵，也不是捨不得衣裳弄髒；她怕的是放手之後，那小小的身軀忽然從自己的世界裡沒有了。"},{"type":"p","text":"她把孩子交給另一雙手，又伸手將孩子的衣領拉平。小孩不懂外面的事，只知道抱著他的人換了，眼前的天被一塊鐵蓋剪成細細的一圈。蓋子合上時，有水滴落在石縫裡，一聲、一聲，彷彿有人在地下數日子。"},{"type":"p","text":"此後究竟過了多久，誰在場，誰伸過手，往後再沒有人能說得周全。有人說孩子不曾哭，有人說哭過；有人說蓋子闔得緊，有人又說留了一道縫。倘若叫那孩子長成老翁後自己回想，他腦海裡或許真有那點灰白的光。然而一個人幼時聽過的故事太多，記憶與傳說有時只隔一張薄紙。"},{"type":"p","text":"那婦人後來最少提及此事。倒不是她忘了。鄰里偶爾提起那年誰家失了兒子，誰家熄燈躲了三日，她便轉身去洗碗。碗上的油總有洗淨的一"}],"running":"第二回｜女人把孩子藏起來","section":"第一部｜井下之年"},{"pdf":12,"blocks":[{"type":"p","text":"刻，人命的去處卻不一定。她不願在孩子面前說得太多，也不願別人以為這樣便算全說了。"},{"type":"p","text":"那晚一同躲進暗處的，還有個替街坊送水的半大女孩，小說裡叫月枝。她進來時抱著空水桶，桶碰到牆，發出一聲脆響。婦人幾乎要斥她，卻見她嘴唇凍得發紫，才把那句話吞了回去。地下並不寬，三個人和一個孩子，四雙膝蓋碰來碰去。孩子醒了一回，手在黑暗裡亂抓；月枝把自己的手指伸給他握。小小的五根手指攥住她的一根，她便不敢動了。"},{"type":"p","text":"「上頭到底怎麼了？」月枝問。"},{"type":"p","text":"婦人搖頭。不是她不信任女孩，是有些消息，知道的人多一個，便多一個人要替它害怕。她們聽見遠處有人用不熟悉的腔調高聲喊話，又有人跑過去，腳步聲很重。月枝說她父親今早去港邊幫人修船，還沒回來。婦人想說天亮就會回，卻突然想起自己也不知道今晚能不能天亮。她只說："},{"type":"p","text":"「等聽不見了再出去。」"},{"type":"p","text":"孩子又餓了。婦人靠著牆試著餵他，衣襟卻被冷汗浸得發涼。月枝默默背過身去，將空桶橫在腿上。許多年後她記不得那夜有多少腳步聲，倒記得自己一生第一次懂得何謂難堪：不是看見別人的窘迫，而是看見了卻不能幫她解圍。她把腰上的小布巾解下來，摺作墊子遞過去，沒說一句安慰。"},{"type":"p","text":"不知過了多久，外頭終於有人輕叩兩下鐵蓋。婦人猛地繃緊身子，月枝也忘記了呼吸。又是兩下，接著一聲壓低的呼喚。原來是巷口賣米的男人。他說街上暫時沒動靜了，可以往後門走。婦人沒有立刻起身，她先"}],"running":"第二回｜女人把孩子藏起來","section":"第一部｜井下之年"},{"pdf":13,"blocks":[{"type":"p","text":"問：「你看見誰了？」對方停了一會兒，只答：「我看見的，不是妳現在該看的。」"},{"type":"p","text":"這話使她往後很多年都記得。她抱著孩子爬出去，膝蓋已麻，站不穩，幾乎又要跌下去。月枝在後頭扶她，空桶留在暗處。兩個女人沿著牆根走，步子那樣慢，慢到一條巷子彷彿能走一輩子。回到家時，粥已冷透，鍋蓋卻仍然蓋得好好的。婦人望著那只鍋，忽然想哭；孩子偏在此時醒來，扯著她的衣領笑了。她只好也笑，笑得嘴角疼。"},{"type":"p","text":"第二日有人傳說，那個藏孩子的地方叫井下；也有人說原是排水溝，沒有井水。有心記錄的人想弄清楚，長輩卻常答非所問，說起那夜的風、米缸剩多少米，說起哪家的雞不見了。後人嫌他們說不清，卻不知道一場劫難在親歷者心中往往碎成無數件小事，沒有一件自稱是歷史。日後王居萬被問起，他說法也有時不同。不是他故意欺瞞；那年的黑暗原就不是他能自己記住的。他借用了大人留下的故事，像借了一件穿了許多年的衣裳，縫補之處，究竟哪一針出自誰手，已無從辨別。"},{"type":"p","text":"海風照樣進屋。十年、二十年以後，有些人記得那口井蓋，有些人只記得那個人曾經活下來。而活下來，在當時竟已是一樁不能輕易拿來炫耀的幸運。"},{"type":"chapter","text":"第三回｜不能問的人"},{"type":"p","text":"島上有一個修船的男人，小說裡叫阿泉。他不是英雄，也不打算做英雄。他做的事，是上工，領薪水，將魚骨頭從飯裡挑出來，偶爾同妻子爭論米價。有人問他天下太平了沒有，他便說：「先把這隻船補好，別的以後再說。」"}],"running":"第三回｜不能問的人","section":"第一部｜井下之年"},{"pdf":14,"blocks":[{"type":"p","text":"那一年，他沒有照常回家。"},{"type":"p","text":"妻子先去問工頭，又去問鄰居。工頭說不知道，鄰居說沒有看見。第三個人將門打開一半，聽她說完，握住門板很久，只回了一句：「妳先回去。」"},{"type":"p","text":"她不明白這句話。回去做什麼？飯早就煮好了。她後來才知道，當一個人沒有辦法救另一個人，最便宜也最殘忍的勸告，就是叫他回家。"},{"type":"p","text":"她的遭遇並不格外壯烈。失去本來不按任何章法，沒有人替她備好告別，甚至連可以哭的時辰，也不是由她自己決定。"},{"type":"p","text":"王居萬長大後，若在街上聽見這類往事，未必知道該把手放在哪裡。有人會談，有人不肯；有人說那是很久以前的事，有人偏說昨天還夢見。"},{"type":"p","text":"他的童年留下一個井蓋，阿泉的妻子留下一張沒有回信的地址。兩段故事隔著不同的人家，卻從此住在同一座島上。"},{"type":"p","text":"海不替人證明，也不替人否認。"},{"type":"p","text":"素珍最初把阿泉的飯碗照舊擺著。桌子不大，多放一只碗，孩子便得縮著手肘吃飯。有人勸她收起來，說飯菜會招螞蟻。她沒有爭辯，只每天洗好，放回原來那處。直到有一天，孩子把那只碗端去盛湯，她才猛地說不可以。孩子被嚇哭了，她自己也嚇了一跳，原來一只空碗竟能把人困得這樣緊。"},{"type":"p","text":"後來有人替她寫過詢問的紙條。寫字的人問阿泉有什麼特徵，她答右手虎口一處舊疤，又說笑時一邊嘴角總會先動。寫字的人說疤痕可以寫，笑起來怎樣恐怕用不上。素珍聽了，便把後半句吞下去。她一直以為只要"}],"running":"第三回｜不能問的人","section":"第一部｜井下之年"},{"pdf":15,"blocks":[{"type":"p","text":"把丈夫記得夠清楚，別人就一定認得出來；那一天才曉得尋一個人所需的證據，原來跟愛一個人所需的證據，全不是一回事。"},{"type":"p","text":"她走過街口，見一個做工的人彎腰繫鞋帶，背影同阿泉有七分像。她站住，心臟跳得極快，直到對方轉過臉，才知不是。她竟因此對那陌生人有了片刻怨氣，彷彿他不該長得那麼相似。回家後她把菜切得很細，刀口碰著木板，一下比一下響。孩子問她生不生氣，她說沒有；孩子說妳明明有。她放下刀，蹲下來抱住孩子，這才承認：「是，我生氣。」至於跟誰生氣，母子兩人都答不出來。"},{"type":"p","text":"素珍等阿泉的第三個晚上，竟夢見他回來責怪米煮得太軟。醒來時她先惱，惱他不體諒自己忙了一天，接著才想起夢裡也見得到他，心頭一陣發麻。她起身去摸灶，水已冷了。窗外有人在巷裡走過，她下意識將門栓拔開一半，又慢慢扣回去。孩子醒來問她做什麼，她說找一只蟑螂。孩子很認真地替她在地上尋，尋到天亮都沒有找到。五日後，原本見面必定與她寒暄的鄰人，在水井旁忽然不肯叫她的名字。素珍看得出來，旁人同她保持距離，並不見得討厭她；更多時候，是怕自己的善意也變成可供指認的證據。她一度恨透這些人，等夜裡隔壁偷偷送來一鍋熱粥，又恨不起來。送粥的婦人站在黑暗裡，說只剩這些，話音急得像在欠債。素珍想請她進屋，對方已走遠。這種無名無姓的幫助，後來她記得比官樣的安慰更清楚。一個愛打抱不平的年輕人來替她寫陳情，寫得慷慨激昂，說阿泉一向秉性剛直，不肯與人同流。素珍讀完卻搖頭，說她丈夫一向怕惹事，見吵架還常常繞路走。年輕人不服，說這樣寫才有力量。她答：「你若為了叫人同情，就替他變成另一個人，那麼我以後找著的究竟是誰？」年輕人臉紅，終究將那幾個豪言壯語劃掉。素珍對他道謝，卻不願說他做得多麼"}],"running":"第三回｜不能問的人","section":"第一部｜井下之年"},{"pdf":16,"blocks":[{"type":"p","text":"好。她不欠任何人一段好看的悲劇。在不確定的年代，人人都想抓住一個肯定的解釋。素珍偏不肯把失蹤的丈夫換成一套完整說辭。這份固執日後也傳到孩子身上。孩子成人後，知道別人問起父親時，往往不是想聽見阿泉如何笑、如何吃飯，而是想藉他證明自己的說法。素珍總說：「他是你爸爸，先是個人，後來才是那些事情。」"},{"type":"p","text":"往後島上的年月不斷往前。曾經不敢問的事，後來有人漸漸敢問，卻未必問得出答案。素珍老了，常被人稱作堅強。她最不喜歡這個詞，因為聽起來像她有得選。她只是在每一個必須做決定的清晨，把門打開，先去把米買回來。"},{"type":"chapter","text":"第四回｜消失的工牌"},{"type":"p","text":"阿泉留下的東西不多。一件洗過多次的短袖，兩只磨平的鞋底，還有一塊工牌。工牌原來是要叫人認出他的，等人不見了，它卻只剩下一串數字，比一個名字還要冷。"},{"type":"p","text":"妻子素珍將它藏在米缸下面。日子久了，她連自己也不曉得為什麼要藏。別家說親，聘禮有清單；阿泉失蹤，連要向誰追問都沒有名目。她問過船廠，問過熟人，旁人不是搖頭，便是壓低聲音叫她回去。她從前嫌丈夫不懂人情，說話總直，如今才明白有些人情最厲害的地方，是人人都懂，卻人人不敢說。"},{"type":"p","text":"孩子坐在門檻上削一根木棍，問父親何時回家。素珍原想說快了，話到嘴邊，忽而記起自己已說過太多回。於是她說：「天黑了就進來。」孩子不滿意，以為母親答非所問。其實她答得並不離題；她能管的，只剩天黑以前這個孩子要到哪裡去。"}],"running":"第四回｜消失的工牌","section":"第一部｜井下之年"},{"pdf":17,"blocks":[{"type":"p","text":"一次鄰家辦喜事，請她去幫忙包菜。桌上人人談笑，她見有人把剩下的魚肉往碗裡撥，便想起阿泉吃魚最怕刺，又忽然生氣：他平日吃飯挑剔，現在卻將一家人的日子挑成這個模樣。她為自己的念頭羞愧，夜裡偷偷哭了一回。愛一個人，不妨同時怨一個人；她那時還不知道，這算不得背叛。"},{"type":"p","text":"素珍終究開始做些小買賣。賣針線、幫人補衣，將零錢收進舊茶罐，銅板碰撞，聲音像落在乾井裡。她並非因此變得剛強，只是人若不吃飯，明日便無從悲傷。街坊讚她能幹，她就點頭；倘若有人說她「總算放下了」，她便抬眼看那人，像看一個把海當成水盆的人。"},{"type":"p","text":"素珍把工牌藏了很久，久到孩子上學，家裡的米缸換過兩回，工牌上的字竟比亡失的人還耐磨。也有人勸她乾脆丟了。她不肯，卻未必全因情深。一次她因搬家整理雜物，發現工牌下面還壓著一張阿泉寫的購物單：煤油、針、半斤糖。字寫得大，最後一項後頭有個小小的圈，像怕她忘記。"},{"type":"p","text":"她看見那半斤糖，忽然動怒。這男人做人一向不精，家裡用錢緊，卻還有心思買糖；失蹤以前，他答應過要替孩子修一只斷腳的小木馬，居然也沒修好。她對著一張紙罵了他半天，罵完卻坐在地上，把那張單子扶平。她以為悲傷會把人的記憶洗得清亮，原來悲傷也會把日常裡不肯原諒的事一同保存。"},{"type":"p","text":"後來修船廠舊址周圍有了新的招牌。有個年輕人替地方採訪，聽說她認得當年工人，便帶著紙筆來。年輕人很有禮貌，問得也仔細，先問阿泉生前工作，再問消失的年月，最後問：「您那時心裡怎樣想？」素珍望著"}],"running":"第四回｜消失的工牌","section":"第一部｜井下之年"},{"pdf":18,"blocks":[{"type":"p","text":"他的筆尖，竟笑了。「我想先去買菜。」她說。年輕人以為她在迴避，又補問有沒有留下特別的最後一句話。素珍想了許久，說沒有；最後一句話不過是他說晚上回來，叫她別把飯煮得太軟。"},{"type":"p","text":"年輕人顯得失望。他本來盼一段足以抄成標題的話，譬如預感、誓言、為誰犧牲。素珍看得出來，忽然有些生氣。「他又不知道自己那天回不了家，為何要講什麼大話？」她問。屋裡靜了一會兒，年輕人才把筆放下，低聲說對不起。素珍轉身去泡茶，茶葉放了兩次，濃得發苦。"},{"type":"p","text":"年輕人走時，她又叫住他，拿出那張皺紙，讓他把購物單也照下來。對方遲疑，問這個有沒有用。她說：「你若寫我丈夫，便不能只寫他怎樣不見。人活著的時候，也要買糖。」那年輕人終於懂得，紀念一個人最容易的方法是把他變成一個事件；最難的方法，是容許他曾經吝嗇、粗心、愛笑，與千萬個沒有留下名字的人一樣平凡。"},{"type":"p","text":"多年後，這塊工牌落到她孩子手中。他把鏽斑慢慢擦去，忽然發現自己已長到父親未必認得出的年紀。要記住一個人的臉，原來也需要有人不斷提醒；而最該提醒他的那個人，早已不在。"},{"type":"chapter","text":"第五回｜軍衣穿過海峽"},{"type":"p","text":"居萬成年後從軍，曾去馬祖。家人記得他做過輔導長，軍階與服役年月尚待考。對年輕人而言，制服有時比一張身分證還先替他向世人介紹自己。"}],"running":"第五回｜軍衣穿過海峽","section":"第一部｜井下之年"},{"pdf":19,"blocks":[{"type":"p","text":"他學會把皮鞋擦亮，把話講得乾淨，也學會在眾人面前不輕易露出疲態。有一回，同袍借了他的梳子不還，他在營房裡追著討，大家笑他比討軍餉還認真。他也笑，說這不是梳子的事，是做人的信用。"},{"type":"p","text":"不料隔天他就忘了自己的水壺放在哪裡。那個借梳子的同袍看見，故意慢吞吞地說：「信用這回事，我先替你保管。」營房裡笑成一團。"},{"type":"p","text":"軍中的海與和平島的海不一樣。馬祖的夜色更冷，岸那頭不是熟識的市街。他有時同人談起故鄉，講魚貨、講橋，講得最多的還是女人。說話的人越起勁，越像要證明自己不曾寂寞。"},{"type":"p","text":"「你回去要做什麼？」同袍問。"},{"type":"p","text":"「做生意。」"},{"type":"p","text":"「做哪行？」"},{"type":"p","text":"「哪一行賺錢做哪一行。」"},{"type":"p","text":"大話說得響，旁人也不戳破。年輕人若連自己將來要做什麼都不敢說，漫長的夜哨便更難熬。"},{"type":"p","text":"他看過軍隊嚴密的秩序，也曉得人群裡有不同的脾氣。只是他當時還不明白，將來最難排定次序的，不是營房裡那幾十個男人，而是一間燈火通明的店、一個不願說破的妻子，以及一群想把自己活好的女人。"},{"type":"p","text":"馬祖的夜哨並非夜夜有故事。大半時候只有風，風之外還是風。站得久了，年輕人會把家鄉的聲音想得很清楚：炒菜的鐵鏟，巷口腳踏車的鈴，母親叫人吃飯時總愛把最後一個字拖長。居萬便在這些聲音裡想起社"}],"running":"第五回｜軍衣穿過海峽","section":"第一部｜井下之年"},{"pdf":20,"blocks":[{"type":"p","text":"寮。可要他說自己想家，他是不肯的；他說的是「回去一定要吃一頓好的」，彷彿胃口比鄉愁更有男子氣概。"},{"type":"p","text":"一次發家信，有個同袍收到母親寄來的毛線背心，顏色俗氣，大家笑得合不攏嘴。居萬笑得最大聲，甚至把背心拿在自己身前比了比。到了夜裡，那同袍躲在被裡摸衣領上的線頭，居萬碰巧看見，嘴邊的玩笑便停住了。他想道歉，又覺得這種事說出口更叫人難堪，只把自己的薄毯往對方那邊推了一些。對方睡醒後發現，什麼也沒問。年輕人的義氣有時不用說話，反倒比那些拍胸脯的誓言真。"},{"type":"p","text":"營裡有人談起從前的事，談到軍隊、談到離散，說法往往不同。居萬喜歡聽各人的版本，卻不喜歡被逼著表態。有時他想，自己如今穿著軍服，究竟是替誰說話？這念頭只一閃，他便把它壓下去。軍務有軍務的規矩，人不能靠疑問站完一夜崗；但疑問並不因被壓下去而消失，它只換了個地方，和他一起回到和平島。"},{"type":"p","text":"居萬穿軍服那天，先在鏡前看了半晌。制服布料未必比常衣舒服，可它使人站直，也使站直這件事忽然有了道理。同行的青年笑他愛照鏡子，他反問：「人既要出門，難道不該叫人看得順眼？」那青年便笑，說日後連同袍都要被他哄得服服貼貼。居萬把帽沿按低一點，心裡確實歡喜。他還年輕，尚相信只要衣服穿得端正，便能將自己也收拾得端正。第一次輪到他替同袍傳遞消息，是一封告知家中長輩過世的電文。紙薄，字也少，竟壓得他走路的腳步比往日沉。他去找那位同袍時，對方正在修靴底，一邊哼歌，一邊抱怨釘子短。居萬站在門外，突然討厭起自己手裡那張紙。他明白消息並非自己造成，卻偏有一種錯覺：只要他不進去，那個人的父親就還活著。隔著一扇門，他第一次知道說話有時不是本事，竟是一件殘"}],"running":"第五回｜軍衣穿過海峽","section":"第一部｜井下之年"},{"pdf":21,"blocks":[{"type":"p","text":"忍的差事。他終究進去了。那位同袍看完，先問：「有沒有寫錯？」居萬說沒有。那人又把電文從頭讀到尾，讀完把靴子放好，慢慢站起來。沒有嚎哭，也沒有戲劇般的跌倒，只問能不能告假。居萬答會去問長官。說這話時他才發現，自己平日最會應付的各種場面，到了人家真正需要幫助時，卻只有幾個含糊的字可用。後來他在馬祖與人論起軍人應有的氣魄，仍然講得響亮。這並非他忘了電文；人原有本領把最不願記起的事折好藏在心底，對外依舊談笑。他常說自己凡事看得開，旁人也當真。唯獨有一次夜裡，值勤回來碰見有人在窗下讀家書，他竟沒有像往常一般湊上去打趣。海風吹著紙角，他站了片刻，轉頭把靴子放得端端正正，像這樣便能把心裡某一樣凌亂也排整齊。"},{"type":"p","text":"退伍或調離的那天，他把箱子收拾得格外仔細。梳子放在最外層，乾淨衣服摺在底下，信件夾進書頁。他以為人生只要肯往前走，便能將經歷理得像行李一般妥當；多少年後一張相片、一句老鄰居的問話，仍能把那些摺平的東西弄亂。"}],"running":"第五回｜軍衣穿過海峽","section":"第一部｜井下之年"},{"pdf":22,"blocks":[{"type":"part","text":"第二部｜海上與婚前"},{"type":"chapter","text":"第六回｜海上有兩種命令"},{"type":"p","text":"早點名的時候，海霧從操場那頭壓過來，王居萬站在隊伍裡，看不清排頭班長的臉。班長點到他的名字，他應了一聲，聲音很響。點到隔壁床姓羅的兵，沒人應。"},{"type":"p","text":"「人呢？」"},{"type":"p","text":"誰也沒答。"},{"type":"p","text":"羅姓士兵昨夜託居萬替他帶一封信出去。他把信封塞進居萬掌心，說妻子快生了，家裡等不得。居萬問他為何不走正規管道，他說上頭退了兩回。「你嘴利，你有辦法。」"},{"type":"p","text":"居萬當時答了「我試試」，其實心裡已經嫌麻煩。信揣在衣袋，到了夜裡忘了。後來同袍說羅兵去找過營門的衛兵，又被趕回寢室；如今不見人，也不知是不是擅離。"},{"type":"p","text":"班長又問了一遍。居萬感到胸前的信封貼著汗濕的襯衣，便說：「他昨晚還在。」"},{"type":"p","text":"「我問你現在。」"},{"type":"p","text":"居萬沒作聲。"},{"type":"p","text":"那天全班被留下來搜山坡。有人罵羅兵害得眾人吃苦，有人暗猜他游海逃了。居萬始終沒有提那封信。傍晚終於找著人，羅兵蹲在一處石牆"}],"running":"第六回｜海上有兩種命令","section":"第二部｜海上與婚前"},{"pdf":23,"blocks":[{"type":"p","text":"後，腳腫得靴子脫不下來。他說昨夜想去通訊處求情，走到一半看見巡邏的，怕受罰便鑽進荒坡，天黑摔傷了腳。"},{"type":"p","text":"「你是有病？」班長一腳踢開石子，「一封家書也值得你去死？」"},{"type":"p","text":"羅兵低著頭。居萬忽然受不了，搶著說：「他不是逃兵！」"},{"type":"p","text":"「誰說他是逃兵？」"},{"type":"p","text":"居萬噎住。四周的人都轉頭看他。他正想補幾句，羅兵卻抬起臉，望著他胸前鼓起來的口袋。"},{"type":"p","text":"那晚居萬把信送出去。寫信的羅兵沒有道謝，收回來時信封被汗浸得起了皺，封口黏得歪歪斜斜。居萬想說郵路慢，說自己也是為他好，最後只問腳還疼不疼。羅兵把被子往肩上一扯，轉身面向牆。"},{"type":"p","text":"半個月後傳來消息，羅兵家裡添了女兒。大夥照例起鬨，羅兵紅著臉拿出照片，挨床給人看。輪到居萬，他看了一眼，說長得像娘。羅兵收起相片，沒叫他再看。"},{"type":"p","text":"入冬時羅兵調到另一處，臨走留下半條用舊的鞋帶。居萬見它在床底，喊了一聲「你的！」羅兵沒有回頭。"},{"type":"p","text":"這些事，居萬後來幾乎不說。提起馬祖，他倒願意講海風如何刮得人走不穩，哪個同袍打呼比炮聲還大，自己怎麼一開口便把眾人逗笑。朋友愛聽這些。偶爾有人問他有沒有做過後悔的事，他便講丟過一隻梳子，講得滿桌都笑。"}],"running":"第六回｜海上有兩種命令","section":"第二部｜海上與婚前"},{"pdf":24,"blocks":[{"type":"p","text":"有一年彩雲翻舊箱，見他留著一條短短的鞋帶，問是不是穿不了還捨不得扔。他正拿著算盤盤帳，說：「扔掉。」"},{"type":"p","text":"彩雲扔進垃圾桶。他算完帳，等她進屋，卻又悄悄把鞋帶撿回來，捲在手心，塞進最底層的抽屜。"},{"type":"chapter","text":"第七回｜王先生最會說話"},{"type":"p","text":"王居萬年輕時，喜歡人家叫他王先生。先生二字不用證件，也不須經過誰核准，一叫出口，便像平白多了半分氣派。"},{"type":"p","text":"他在街上走，逢熟人便招呼，遇不熟的也能講兩句。有人嫌他油嘴，另有人偏喜歡這份熱絡。最叫人沒辦法的是，他對每個人似乎都有不同的笑法；你想抓他一句話的把柄，他轉頭便已將那句話說成玩笑。"},{"type":"p","text":"彩雲頭一回留意他，是在一場親友聚會的門口。她看著他在親友間走動，一時覺得熱鬧，一時又覺得這人太會做戲。"},{"type":"p","text":"居萬正在替一位姑娘拿東西，話說得漂亮：「妳再慢些走，整條街的風都要等妳。」旁邊幾個人笑得前仰後合。他也笑，笑得不覺羞。"},{"type":"p","text":"彩雲站在簷下，待笑聲過去才說：「王先生好忙，一條街的風都讓你管了。」"},{"type":"p","text":"居萬回頭，竟一時答不上話。"},{"type":"p","text":"「黃小姐，妳這是誇我？」"},{"type":"p","text":"「我哪有那麼多工夫。」"}],"running":"第七回｜王先生最會說話","section":"第二部｜海上與婚前"},{"pdf":25,"blocks":[{"type":"p","text":"他上前半步：「那妳現在有沒有工夫，聽我講兩句？」"},{"type":"p","text":"彩雲看他，眼裡沒有厭惡，也沒有鼓勵，倒像在估量一件貨色是否經得起日後使用。"},{"type":"p","text":"「你每天講的話那麼多，怎麼還有新的？」"},{"type":"p","text":"「見的人不同，話自然不同。」"},{"type":"p","text":"「原來你不是誠心，是做生意。」"},{"type":"p","text":"居萬被她說得笑起來，心裡卻暗暗記下一筆。這姑娘不肯照他的劇本走，說起話又把路堵得漂亮。他忽然有些認真，反而不知道下一句該怎麼說。"},{"type":"p","text":"從前的姑娘笑他，他只當趣事；彩雲笑他，他開始怕自己真的可笑。"},{"type":"p","text":"有回聚會，居萬同幾位年輕姑娘笑談，彩雲隔著一張桌子替人斟茶。她沒有刻意看他，只見對方每逢說到精彩處，總習慣先望向四周，要找一個肯替他笑得大聲的人。彩雲想，這人若哪天落魄了，怕是比旁人更難過；沒有人捧場，對他恐怕比沒有錢還難受。"},{"type":"p","text":"散席有人把彩雲攔住，誇居萬有前途，說女人嫁這種男人才不寂寞。彩雲問：「不寂寞，是指他天天在家，還是天天有人找他？」那位長輩被問得一怔，忙說她太會挑字眼。彩雲不是故意刁難，她只是很早便發覺，稱讚一個男人的話，到了女人身上常常要換一種算法。"},{"type":"p","text":"隔日居萬尋了個理由到她家附近，手裡還真拎著一包糖。他本來準備了一套話，說糖是剛好路過看見，說人情總要來往。彩雲接過包裹，發現"}],"running":"第七回｜王先生最會說話","section":"第二部｜海上與婚前"},{"pdf":26,"blocks":[{"type":"p","text":"紙上沾了些水，問他是不是繞了遠路。他說哪有。她說：「你鞋底都是另一條街的泥。」他這才低頭看鞋，兩人忽然一起笑了。那一刻她的笑不是禮貌，也不全是嘲弄；居萬看見了，竟比在任何酒桌得到十句稱讚還高興。"},{"type":"p","text":"回到人群裡的王居萬，比在軍營時更懂得把話說得熱鬧。市集的魚販認得他，開玩笑說他每次買魚都像在閱兵，他便立刻替魚兒排起大小，說今日哪一條是將軍。眾人笑得直不起腰，他反倒神色嚴肅，把最小的一條指給賣魚的孩子：「這個是傳令兵，最會跑。」孩子笑著拿魚尾拍他的手背，滿街的人都覺得他好相處。可他也有不容易相處的一面。街尾一位老人欠了別人錢，居萬見債主當眾奚落，便出言相勸，還代付了一部分。回家後彩雲問錢從哪裡來，他反嫌她計較。她不問老人值不值得幫，只問：「你替人付了多少，怎麼不先讓我知道？」居萬回說人在當下要講義氣。彩雲答：「講義氣若只用你的面子，不用我的米缸，我也敬你是好漢。」他一聽大怒，兩人幾日沒好好說話。等老人登門道謝，居萬先是得意，卻看見彩雲在後頭替老人包了兩個饅頭，心中又酸又愧。她並非不肯救急，她只是比他更明白誰要承擔救急之後的日子。居萬於是想以一頓飯賠禮。酒菜備齊，朋友也叫來，偏忘了事先問彩雲願不願意在那天招待。她在廚房忙到汗流，席上卻有人誇居萬慷慨。彩雲把最後一道菜端上桌，當著眾人說：「王先生最有本事的，是拿我煮的飯做人情。」有人聽懂了，笑聲頓時小了。居萬臉一熱，正要分辯，忽見她眼角也有笑意。他這才明白妻子不是要拆他的臺，而是要他看看臺後頭站著的人。那頓飯散後，彩雲發現廚房多了一只洗好的鍋。居萬沒說是自己洗的，也沒有邀功。次日他照"}],"running":"第七回｜王先生最會說話","section":"第二部｜海上與婚前"},{"pdf":27,"blocks":[{"type":"p","text":"樣在人前神氣，還說男子漢做大事，不必為小事傷神。彩雲聽見，不去拆穿。她知道人有時先學會做，後來才有勇氣承認自己做了。"},{"type":"p","text":"他伸手想替她將風吹亂的頭髮別到耳後，手到半途，又收了回來。彩雲見了，並不立即躲。兩人隔著一點距離站著，街上有人推車經過，車輪碾著碎石發出刺耳的聲音。那短短片刻並不風流，卻叫居萬記了許久。真正有意思的親近，不在有沒有碰到，而在一個向來膽大的人，終於肯為別人的意願稍稍猶豫。"},{"type":"chapter","text":"第八回｜她不吃這一套"},{"type":"p","text":"彩雲第一次把王居萬晾在門外，是在一個下雨的下午。"},{"type":"p","text":"他挑了半條街都看得見的傘來，傘柄雕了花，自己先在鏡前照過。雨點才落下幾顆，他便走到黃家門口。屋裡有人說：「那個當兵回來的又來了。」另有人笑：「早晚要把門檻踩平。」"},{"type":"p","text":"彩雲在廚房剝蒜，剝到第三顆才出去。"},{"type":"p","text":"「出去走走？」居萬問。"},{"type":"p","text":"「去哪裡？」"},{"type":"p","text":"「海邊。」"},{"type":"p","text":"「你昨天帶林小姐去的地方？」"},{"type":"p","text":"居萬的笑停了一下：「妳聽誰說？」"},{"type":"p","text":"「誰說都一樣。地方又不會因為換個人去，海就變成另一片。」"}],"running":"第八回｜她不吃這一套","section":"第二部｜海上與婚前"},{"pdf":28,"blocks":[{"type":"p","text":"她說完便要回屋，居萬伸手擋在門旁，沒有碰著她。"},{"type":"p","text":"「我跟她只是在街上遇到。」"},{"type":"p","text":"「我又沒問你們做了什麼。」"},{"type":"p","text":"「妳這不就是在問？」"},{"type":"p","text":"彩雲望著他，忽然笑了。「你倒聰明。那請你替我回答好了。」"},{"type":"p","text":"居萬站得難堪。屋裡長輩喚他進來喝茶，他連聲說改日，轉身要走。才下階梯，傘便撞在牆角，傘骨啪地折了一支。他罵了一聲，罵得比自己想像的大。彩雲在門裡聽得清楚，唇邊的笑也僵住了。"},{"type":"p","text":"隔了三日，他沒來。"},{"type":"p","text":"彩雲照常買菜、幫家裡收拾，到了傍晚卻會往門口看。她氣自己為一個男人的腳步留心，於是門鈴一響，便故意讓旁人去應。第四日有人送來一包糖，她拆開，發現沒有卡片；第五日又沒有了。她問送貨的孩子是誰叫他來的，孩子說是王先生，付過錢，還交代不用回話。"},{"type":"p","text":"她拿著糖進屋，母親看了問：「怎麼不高興？」"},{"type":"p","text":"「太甜。」彩雲說。"},{"type":"p","text":"母親取了一塊嚐，說哪有，這個很好。彩雲把紙包收起，當晚卻連吃兩塊。"},{"type":"p","text":"第六日居萬來了，手裡什麼也沒有。他先把傘送到修理鋪，再繞來黃家，褲腳沾著泥。彩雲正好出門，看見他便把頭轉向一旁。"}],"running":"第八回｜她不吃這一套","section":"第二部｜海上與婚前"},{"pdf":29,"blocks":[{"type":"p","text":"「今天不帶東西。」他說。"},{"type":"p","text":"「怕被我退回去？」"},{"type":"p","text":"「怕妳把送東西的人也退了。」"},{"type":"p","text":"她原想笑，偏不肯給他看，低頭去撐自己的舊傘。居萬伸手握住傘柄，說雨大，他送。彩雲把手抽開，兩人都沒拿穩，傘落在地上，泥水濺上她新洗的裙角。"},{"type":"p","text":"「你看你！」她的聲音尖了。"},{"type":"p","text":"居萬本能地伸手去擦，又被她打開。他臉色也變了：「我不過想幫忙。」"},{"type":"p","text":"「你哪一次不是想幫忙？」"},{"type":"p","text":"這話說得過了，她自己知道。他愣了一瞬，竟笑出聲，笑得很不好聽。「好，算我犯賤。」"},{"type":"p","text":"彩雲低頭撿傘，沒攔他。等他走到巷口，她忽然喊：「糖太甜了！」"},{"type":"p","text":"居萬沒有回頭，只把手揮了揮。那晚她在房裡想了半天，最後將剩下的糖包用繩子紮好，塞進衣櫃。隔日上午，家裡的小弟打開櫃子偷吃了一顆，她竟動怒，搶過來連聲說誰許你亂翻我的東西。"},{"type":"p","text":"弟弟說：「妳不是嫌甜？」"},{"type":"p","text":"彩雲一時答不出來。她關上櫃門，發現自己的手正在發抖。"}],"running":"第八回｜她不吃這一套","section":"第二部｜海上與婚前"},{"pdf":30,"blocks":[{"type":"chapter","text":"第九回｜彩雲把燈關了一半"},{"type":"p","text":"追求一個人，最容易的事是送花，最難的是在對方不看你的時候，還肯守自己的分寸。"},{"type":"p","text":"居萬前一樣本領好，後一樣本領普通。他能替彩雲尋來好看的點心，能在人多時隔著幾張桌子喊出她的名字，卻不大曉得一個女人要的是不是這些。"},{"type":"p","text":"彩雲沒有當面數落過他，只在一次下雨的傍晚，請他將一盞晃動的油燈移到桌子裡側。居萬說放外頭亮，何必遮起來。"},{"type":"p","text":"「放外頭，風一吹就滅。」"},{"type":"p","text":"「那就再點。」"},{"type":"p","text":"「你有的是火柴，人家不一定有。」"},{"type":"p","text":"她這句話不知道是在講燈，還是在講他。居萬只覺得她說話彎得厲害，自己轉了幾個彎才追上。"},{"type":"p","text":"他後來常在彩雲面前講自己的遠大志向。說店面要開得亮，生意要做得大，熟人走過都要進來坐。他畫的是一張有自己站在中央的圖，彩雲聽得多了，便問：「這樣的店，是你一個人過日子，還是大家一塊兒過？」"},{"type":"p","text":"居萬不答，將杯子裡的茶喝得見底。"},{"type":"p","text":"彩雲也不催。她早明白有些人不能靠說服，得等他親自撞見牆，才曉得房子的大小。"}],"running":"第九回｜彩雲把燈關了一半","section":"第二部｜海上與婚前"},{"pdf":31,"blocks":[{"type":"p","text":"彩雲在尚未出嫁時，便不肯將命運全部交給一張喜帖。她見過一位遠房姑媽，每逢丈夫酒醉歸家，先去廚房把碗碟挪好，再將孩子哄到房裡。姑媽動作利落，嘴上說日子誰不是這樣；直到某晚摔碎了一只盤子，才蹲在灶邊很久不肯起來。彩雲去扶她，姑媽竟先道歉，說讓晚輩看了笑話。"},{"type":"p","text":"「人疼的時候，為何要道歉？」彩雲問。"},{"type":"p","text":"姑媽笑笑，說她小姑娘不懂。那笑有幾分好意，也有幾分看輕，彷彿一個未婚女子所有的聰明都不足以向日子問價。彩雲沒有爭論，後來卻常記得地上那只盤子。盤子破了，還能量出缺口；有人心裡破的地方，偏得自己一片片拾起來，不准弄傷旁人的腳。"},{"type":"p","text":"居萬來探望那晚，偏又講起一樁朋友的趣事。朋友追求一位女子，天天送禮，最後人家仍然不肯點頭，席上男人們都笑那女子不識好歹。彩雲問：「他送東西，人家便欠他婚姻嗎？」居萬說自然不欠，但受了好處總該給些面子。彩雲反問：「那你送我的東西，我現在還給你，往後是不是什麼都不欠？」"},{"type":"p","text":"他一時發急，解釋自己不是那意思。彩雲卻真走到櫃子旁，把先前收的一條絲巾取出。居萬見了，臉色立刻變了。他不是捨不得絲巾，是忽然發現自己的話竟能使原本靠近的人後退那麼遠。他想去拿她的手，又不敢，只說：「妳留著。我送妳，不是為了買什麼。」"},{"type":"p","text":"彩雲停了一下，將絲巾放回去。「那你先記住今天說的話。」她說。此後很多年，他大概都沒記得那條絲巾是何顏色，彩雲卻記得他那晚真正慌張的神色。她懂得，男人講愛時不見得都在說謊；但再真誠的話，倘若說過便不必負責，也同樣叫人不安心。"}],"running":"第九回｜彩雲把燈關了一半","section":"第二部｜海上與婚前"},{"pdf":32,"blocks":[{"type":"p","text":"兩人的婚姻在家譜上是一條橫線；寫成小說，卻像這盞燈。有人忙著把燈點亮，有人忙著護住燈芯。彼此都覺得自己的辛苦不易被看見。"},{"type":"chapter","text":"第十回｜紅紙寫錯的名字"},{"type":"p","text":"兩家談婚事時，一張紅紙把人的名字寫錯了。寫字的親戚滿不在乎，說改一筆便好；居萬也笑，叫大家不必為這點小事壞了興致。彩雲卻將紅紙擱下，問寫錯的是哪一個字。她不是計較吉凶，只是不願自己的名字在一件關乎終身的事情上被隨便帶過。"},{"type":"p","text":"那親戚臉色有些難看，暗說新娘未進門便這樣厲害。居萬忙圓場，說彩雲向來認真，是自己福氣。彩雲聽了也不高興：認真怎麼忽然成了男人拿來討好親戚的福氣？可她沒有當眾拆穿，只伸手將紙轉過來，請人把字改好。"},{"type":"p","text":"晚上她娘家有人勸她，男人年輕時愛玩，成了親自然收心。彩雲問：「若是不能呢？」對方說人哪有十全十美。這話人人會講，卻少有人肯認真想想，不能十全十美的人，究竟要誰替他擔那欠下的部分。"},{"type":"p","text":"居萬自己也在家裡聽勸。朋友說男人娶妻，最要緊是回家有人管飯，外頭應酬仍得照做。居萬跟著笑，笑完卻走到窗邊。那夜他忽然想起彩雲退還糕盒的樣子，想起她不肯替任何人把話說得太圓。倘若娶她，他要的是一位看得懂他的妻子，還是一位能替他遮掩的妻子？他暫時不知。"},{"type":"p","text":"婚禮沒有因此耽擱。街上的人一面夸新郎會做人，一面說新娘有主意。有人以為這是良配，有人等著看笑話。只有兩個當事人明白，此刻人"}],"running":"第十回｜紅紙寫錯的名字","section":"第二部｜海上與婚前"},{"pdf":33,"blocks":[{"type":"p","text":"人說的夫妻，其實還未真正開始過日子。往後要用多久，才曉得彼此能讓多少，誰也不能先替誰作保。"},{"type":"p","text":"婚事商議到某個下午，親戚們算起席數，話題忽然從兩個人的將來變成每桌坐幾個人、誰家該出多少。居萬說不能委屈彩雲，場面該做得好看；彩雲聽了心裡一暖，卻見他一轉身又答應遠房親友添一桌，便不免疑心，他口中的「不能委屈」究竟替誰說的。"},{"type":"p","text":"晚間兩人往家走。居萬談婚宴要請的客人，說到某位舊友如何有義氣，又說哪一桌若能談成生意，將來日子更容易。彩雲一直沒有接話，走到橋邊才問：「我們成親，是給自己過，還是替你那些朋友搭個場子？」居萬被問得不快，說她想得太細。彩雲答：「人生就這麼一回的大事，我不想想細些，留到哪一天再想？」"},{"type":"p","text":"他停下來，竟有些委屈。旁人只見彩雲伶俐，不見她一旦認了理，便能把話一層層問到底。居萬從小愛有人聽他講，今日卻忽然想要她閉嘴。這念頭一冒出來，他自己先怕了。他明明喜歡她有主意，怎能等她真把主意用在自己身上，便覺得受不了？"},{"type":"p","text":"兩家議親那晚，屋裡擺了一盤喜糖。居萬把糖紙攤開看，說這顏色太淡，喜事該用更紅的。彩雲的親戚聽見，趕忙去換；彩雲卻攔住，說顏色淡又不礙婚事。他不服：「人家一見便要知道我們高興。」她問：「我們高興，難道要靠糖紙替我們作證？」兩家大人笑起來，居萬也只好笑，心裡卻覺得自己又失了先機。婚禮前夕，有人私下將他年少在街頭與幾個姑娘談笑的事傳到彩雲耳中，說得有鼻子有眼。彩雲沒有立刻找他算帳，倒是把自己往後的開銷逐筆列在紙上，拿去請他過目。居萬看得心煩，說新"}],"running":"第十回｜紅紙寫錯的名字","section":"第二部｜海上與婚前"},{"pdf":34,"blocks":[{"type":"p","text":"婚之際何必做得像開商行。她答：「開商行只怕賠錢，成家若賠了信任，連帳也沒處查。」居萬終於明白，這女子對他的風流並非全然不知，也並非因為不在意才不聲張。她只是不肯讓別人的閒話替她決定要愛誰。迎親當日，紅紙果然又出了差錯。有人將座次寫錯，有個親戚臉色難看，滿屋子忙著賠笑。居萬本想裝作沒看見，卻想起彩雲曾說過名字是人的臉面，便親自去改，又當著兩家長輩說是自己沒有交代清楚。旁人不以為意，彩雲卻看了他一眼。那目光不算溫柔，卻比任何讚美都使他高興。他以為自己終於摸著了她心裡的門，直到婚後才知道，那門從來不是靠做一次好事便能開上一輩子。夜深時彩雲坐在房裡，聽外頭仍有人鬧酒。居萬推門進來，臉上還帶著被人灌酒的紅，見她安靜，便問是不是累了。她說有一些，隨即問：「若明日沒有這些人替你喝采，你還會這樣高興嗎？」他想笑，卻不知如何回答。她替他倒了杯水，說不必現在答，日子很長。兩人第一次真正單獨坐下來，外頭的笑聲離得遠了，屋裡反而生出一點不易說清的親密。"},{"type":"p","text":"風從海面吹過來。他解下外衣要替她披，彩雲拒了，說不冷。兩個人默默走了一段。他終於改口：「有幾桌是我想請，你不想請，我回去再商量。」她說：「我不是要你什麼都聽我的。我是要你曉得，這門婚事裡還有我。」居萬點頭，嘴上不說，心裡卻像有條繩被人輕輕拉直。往後他仍常把這句話忘了，只是每當真的忘得太遠，彩雲便有法子叫他記起。"}],"running":"第十回｜紅紙寫錯的名字","section":"第二部｜海上與婚前"},{"pdf":35,"blocks":[{"type":"part","text":"第三部｜春潮初上"},{"type":"chapter","text":"第十一回｜春潮開張"},{"type":"p","text":"店還沒開門，牌匾先掛好了。"},{"type":"p","text":"居萬替酒店取名「春潮」。兩個字既有海氣，又有春意，他很得意，說一聽便曉得這地方不會冷清。"},{"type":"p","text":"他說的酒店，不是今日旅客住一晚的客房，而是有女侍陪席、酒水與應酬的夜間營業場所。基隆是港市，船來船往，總有人需要生意、排場，也有人不肯太早回家。"},{"type":"p","text":"春潮開門前三天，最先來討債的不是債主，是木工。那人蹲在門口，把未付的工錢一項項報得分明，說自己也有一家老小，不好再往後拖。居萬見旁邊有人看熱鬧，便故作豪氣，說店還沒開張，怎會欠你錢。木工把手裡的紙往上一舉：「欠的是我的工，不是你的店。」話像一巴掌，拍在兩個男人面上。"},{"type":"p","text":"彩雲聽見，走出來把木工請進屋，先讓他喝水，再請他把工項重算一遍。有人說女人家做這些太精細，開店要靠氣魄；她沒有理會。木工收了約好的款，反而有些不好意思，說以後要修什麼還能再叫他。居萬在旁聽得悶，等人走了才說：「妳何必叫他當著那麼多人算？」"},{"type":"p","text":"「你讓他在那麼多人面前要，總比讓他回家沒飯吃好？」"}],"running":"第十一回｜春潮開張","section":"第三部｜春潮初上"},{"pdf":36,"blocks":[{"type":"p","text":"居萬想回嘴，竟找不到更好聽的理由。那一晚他一直不快，忙著把店裡的燈泡一顆顆試過去。彩雲不勸他，也不道歉。兩人各自做事，誰也不肯先承認，若沒有另一個人，這店大概開不起來。"},{"type":"p","text":"開張當天，門前站著一排看熱鬧的人。有人說裝潢氣派，有人說這年頭做這行要膽子；幾位穿得漂亮的女侍先在裡頭理衣領，待客人進來，才換上笑容。她們不全是出於同樣的理由到這裡，有人要養弟妹，有人只想離開原來的住處，也有人單純覺得夜裡比白天能多賺些錢。居萬對她們說，春潮的規矩是客人要高興、做事要勤快。彩雲補上一句：「不願意的事，也要敢說。」"},{"type":"p","text":"阿綺站在最後頭，聽見彩雲的話，抬頭看了她一眼。那時她還不信一個掌櫃的妻子肯替女侍說話，但她記住了。夜裡有位喝多的客人不肯結帳，借著酒氣拉住阿綺的袖子。阿綺將手抽回來，對方嚷著說不給面子。居萬快步迎上，講了幾句好話，先替客人把場面遮過；彩雲卻從旁將帳單放下，說：「先生，歡迎來吃酒，不歡迎拿人為難。」"},{"type":"p","text":"那男人原要發作，見她說話不急不慢，倒不好再鬧。居萬陪笑送他出去，回來怪妻子把話說硬了，萬一得罪大客怎麼辦。彩雲把找回的錢攤開，說今日的帳並沒有因此少。阿綺在一旁低頭抹桌子，指頭卻不自覺握緊了抹布。她第一次覺得這店不只有好看的燈，還可能有一扇真能從裡頭關上的門。"},{"type":"p","text":"散場以後，居萬親自熄了外頭的燈。彩雲在櫃上留著一盞，替幾個女侍算工錢。那夜的笑聲早散了，地板卻濕，鞋底走過黏黏的，像熱鬧本身也會留下要人清理的痕跡。居萬倚著門問她，今天算不算成功。彩雲望著"}],"running":"第十一回｜春潮開張","section":"第三部｜春潮初上"},{"pdf":37,"blocks":[{"type":"p","text":"最後一個離開的姑娘說：「今日開得成，不表示明日守得住。」他笑她不吉利，卻仍替她把椅子搬近燈下。兩個人誰也不曾想到，日後最難清算的，不是酒水的價錢。"},{"type":"p","text":"後來他常說，做生意就是這樣，開門要敢，收錢要清楚，認人要快。"},{"type":"p","text":"彩雲聽了，只問他：「那關門呢？」"},{"type":"p","text":"他沒答。"},{"type":"chapter","text":"第十二回｜夜裡第一盞燈"},{"type":"p","text":"春潮開張前一晚，燈泡試亮，整條街像忽然多了一排橘紅色的月亮。居萬站在門口，說還是暗了些；看招牌的工人說再亮就要把隔壁阿婆照得睡不著。他聽了大笑，說阿婆若睡不著，請她來喝茶。"},{"type":"p","text":"彩雲坐在內室核對最後一筆支出。油漆、酒杯、椅子、音響、布幔，項項花得有名堂，卻也項項像有人臨時想起才寫上去的。她問居萬還有沒有未付的錢。居萬說差不多。她把筆擱下，問差不多是多少。居萬答得含糊，說開店初期總是要有些膽量。"},{"type":"p","text":"她不反對膽量；她反對的是他每逢算不明白便拿膽量遮臉。夜裡回家時，兩人為一張酒桌的價格爭了幾句，最後他說：「妳是不是盼我做不成？」彩雲停下腳步，許久才答：「我若盼你做不成，何必替你記到這麼晚？」"}],"running":"第十二回｜夜裡第一盞燈","section":"第三部｜春潮初上"},{"pdf":38,"blocks":[{"type":"p","text":"那一夜他沒再說笑。第二天人群湧進來，彩雲站在廚房門邊，聽見杯盤響、歌聲響、居萬的笑聲也響。她忽然覺得這店像一只正在離港的船，船頭站的是他，船尾那些不肯讓別人看見的繩結，卻握在自己手裡。"},{"type":"p","text":"有位女侍進門試工，自稱月琴。她衣裳不華麗，眼神卻鎮定，聽過店裡規矩後只問一件事：「工錢準時發嗎？」居萬愣了一下，像沒料到有人在滿屋新燈前先問最樸素的事情。他忙說自然。月琴便說，那她明晚來。"},{"type":"p","text":"多年以後，人人只記得春潮開張有多風光，沒人記得第一個認真問薪水的女子。可一間店真正的故事，從來不只始於開張的鞭炮，也始於有人問一句：這些燈亮起來，究竟誰的日子會因此好過？"},{"type":"p","text":"正式開張的前一個鐘頭，麗華去查看酒杯，發現其中幾只杯口有細小缺痕。她把杯子挑了出來，居萬嫌她挑剔，說客人哪會留意。麗華將一只杯子倒扣在桌上，指著那一點缺口：「喝酒的人不留意，嘴唇可會留意。」居萬聽了，故作大方，叫她全換新的，轉身卻又心疼買杯子的錢。麗華假裝不見，他那副又想有氣派又捨不得花錢的神情，實在同其他小老闆沒有兩樣。"},{"type":"p","text":"音響試到第三遍，從裡頭傳出刺耳的雜音。修理的人說線路要重接，居萬的額頭便出汗。彩雲帶了幾份飯來，將菜擺在後桌，叫大家先吃。居萬說沒工夫，彩雲不催，只留一份在旁。半個時辰後，他為了尋一隻螺絲釘翻遍抽屜，瞧見飯盒，菜已涼了。他還是坐下來吃，吃到一半才想起今天自己一句正經的謝謝也沒同她說。"},{"type":"p","text":"第一桌客人進門時，彩雲站在樓梯口，看見他忽然挺直了身子，一隻手將衣襟拉平，彷彿推開的不是店門，是他自己心目中另一種人生。她有"}],"running":"第十二回｜夜裡第一盞燈","section":"第三部｜春潮初上"},{"pdf":39,"blocks":[{"type":"p","text":"一瞬間也替他高興。她原知道他愛逞強、愛說大話，卻不能否認，這人確實敢在旁人只肯張望的地方先踏出去。可她又想到帳簿上那幾筆未付的貨款，喜悅便立刻有了重量。"},{"type":"p","text":"第一個深夜客人姓方，穿著乾淨的白襯衫，說自己在碼頭有門路。他一進門便點了最貴的酒，問能不能先記帳。居萬看他談吐豪爽，又帶來幾個朋友，便說好。彩雲從櫃後看見那人鞋邊沾著泥，手上的戒指卻亮得刺眼，便順手將他的名字與住處記在一張單子上。居萬低聲嫌她多疑，她答只是記帳。他便不再說話，心裡卻認定她把一位可能帶來生意的朋友看成賊。兩週後方先生又來，這回帶的人更多，講的海運生意也更大。居萬興高采烈，當眾說方先生是義氣人。席到半途，一個送貨的青年來催欠款，指著方先生說上回訂的貨仍未結清。席上頓時沒人接話。方先生將杯子一摔，責問青年懂不懂規矩，說哪有客人正在吃酒，外人來討錢的。居萬第一念頭竟是替方先生維持面子，忙把青年拉到旁邊。青年紅著眼說自己也只領工錢，若討不回，老闆便扣他的薪水。彩雲走來，將幾筆賒欠攤在桌邊，沒有指名罵人，只道：「做買賣最怕不清不楚。大家都是討生活，事情說清楚，明日才有得見。」方先生笑著說她真會算，卻始終沒拿出錢。那夜散席後，居萬追出去要帳，才發現對方留下的地址並不真實。他站在路燈下，聽海風把招牌吹得輕響，心頭第一次升起一種不願承認的寒意：原來自己最自得的識人本領，也可能只是一場被安排好的奉承。次日有人送來一個信封，裡頭只有一張便條，說欠的錢日後必還。居萬攥著便條，竟替那人說了好幾句好話。彩雲沒同他吵，只把信封夾進帳簿。她知道丈夫暫時不是要護那個客人，而是要護自己曾經信任人的判斷。往後每逢他把一句承諾說得太響，彩雲就會想起這張沒有日期的紙。"}],"running":"第十二回｜夜裡第一盞燈","section":"第三部｜春潮初上"},{"pdf":40,"blocks":[{"type":"p","text":"開張不久，麗華便替店裡訂下一條小規矩：姑娘們下工若要走暗巷，至少結伴到燈亮的路口。居萬說她們都不是孩子，何必這樣麻煩；麗華說不是每個危險都會先向人報名。阿綺起初嫌她管得寬，某夜卻因為鞋跟斷了，獨自落在後頭。她扶著牆想把鞋脫下，聽見遠處有人喊她的工作名字，腳步忽然急了起來。"},{"type":"p","text":"還沒走出巷，麗華已拿著一盞小燈折回來。她不問有沒有出事，只蹲下替阿綺把斷掉的鞋帶打個結，說先走到亮處再看。阿綺臉上發燙，一半因害怕，一半因自己早先還笑這女人多事。兩人回到店口時，居萬正要關門，見她們一身狼狽，忙問出了什麼。麗華說鞋壞了，請他明日讓夥計把後巷的燈修好。"},{"type":"p","text":"居萬聽了，才知道店裡最亮的地方總留給客人，後頭替生意出力的人卻得摸黑回去。他答應，隔天果然請人裝燈。修燈的錢不多，可他付錢時仍有幾分不甘，覺得做生意處處要花，哪裡還剩利潤。彩雲拿著收據說：「你若算這筆不值得，那些姑娘每天多走的一段暗路，是要算在誰頭上？」"},{"type":"p","text":"後來阿綺仍會與麗華頂嘴，為了化妝鏡擺哪裡、誰先借髮夾吵得厲害；下工時卻總在後門等對方。她們不把這叫姐妹情深，夜裡肯替另一個人留步，本就是十分尋常、也十分難得的事。很久以後春潮熄燈，阿綺偶爾走到一條燈光昏暗的街，仍會想起那夜有人折回來，手裡舉著一盞不算明亮的小燈。"},{"type":"p","text":"半夜有客人嫌酒不夠冷，居萬走過去賠笑，另換一瓶；廚房有人抱怨工錢算法，麗華出面說明；阿綺的鞋帶斷了，月琴蹲下來替她打結。看似"}],"running":"第十二回｜夜裡第一盞燈","section":"第三部｜春潮初上"},{"pdf":41,"blocks":[{"type":"p","text":"一整屋都圍著居萬的歡迎詞轉，其實每個角落都有一個人把別人的日子扶住。很多年後王先生談起春潮，總說自己年輕時一手打下來的。彩雲聽慣了，也不急著糾正，只在有人問起那晚有多少客人時，準確地說出一個他早忘記的數目。"},{"type":"chapter","text":"第十三回｜紅燈底下的女人"},{"type":"p","text":"阿綺把那張借據撕了。"},{"type":"p","text":"月琴撲過來搶，已晚了一步。紙斷成三截，像一條白魚被人從中掐開。化妝間裡的鏡子裂了一角，映出兩個女人半張臉，兩邊都很難看。"},{"type":"p","text":"「我又沒說不還！」月琴嚷。"},{"type":"p","text":"「妳去跟麗華說啊。」"},{"type":"p","text":"「我跟妳借的，關她什麼事？」"},{"type":"p","text":"阿綺笑了一聲。她早上替月琴挨了客人一個耳光，晚上又聽說那人其實已經還了半筆錢，月琴沒告訴她。帳不大，只有幾十塊，偏偏就是那幾十塊，使她想起自己在洗衣場替人搓破過的手指。"},{"type":"p","text":"月琴紅著眼睛，一把推開椅子。「妳就缺這點錢？」"},{"type":"p","text":"「對。」阿綺說，「我缺。」"},{"type":"p","text":"門外有人敲門，嚷著要再添兩瓶酒。麗華隔著門問到底好沒有。阿綺把裙子拉平，走出去時還狠狠瞪了月琴一眼。"}],"running":"第十三回｜紅燈底下的女人","section":"第三部｜春潮初上"},{"pdf":42,"blocks":[{"type":"p","text":"那夜七號桌有位戴金錶的常客，嘴裡一口一個阿綺，伸手卻只認得她的手腕。她抽了一次，男人又攥住。她忽然把酒朝他身上潑過去。"},{"type":"p","text":"音樂還在唱。隔了一下，桌邊的人才紛紛站起來。"},{"type":"p","text":"王居萬跑來，第一句問的是：「怎麼回事？」"},{"type":"p","text":"男人已經把外套脫了，指著上面的酒漬叫他賠。阿綺說他先動手。居萬看向男人，男人反問：「你店裡的人說什麼你就信什麼？」"},{"type":"p","text":"居萬本來伸手去扶阿綺，聽到這話，手停在半空。"},{"type":"p","text":"「今天這筆算我請。」他說。"},{"type":"p","text":"阿綺把笑容收得乾乾淨淨。「你請他的？」"},{"type":"p","text":"居萬使眼色叫她進去，她不肯。隔壁桌一個女客人慢慢站起來，也不說話，只把椅子挪得更遠。麗華趁著空隙將阿綺拉到後頭，反手把門關上。"},{"type":"p","text":"「妳想把這份工丟了？」麗華罵。"},{"type":"p","text":"「他摸我。」"},{"type":"p","text":"「我又不是瞎子！」麗華忽然提高嗓門。她停了停，聲音放低，「我已經叫他放手了。妳倒好，半瓶酒潑出去，明天他來找誰？」"},{"type":"p","text":"阿綺正想回嘴，看見麗華的指甲縫裡一小片血色。方才拉人時不知在哪兒刮破了。她忽然想哭，卻偏偏先笑出聲，笑得麗華直看她。"}],"running":"第十三回｜紅燈底下的女人","section":"第三部｜春潮初上"},{"pdf":43,"blocks":[{"type":"p","text":"午夜居萬來敲門，說可以先給她一點錢，若明天那客人還來鬧，也好有退路。他把鈔票放在桌上，沒說是借是賞。"},{"type":"p","text":"阿綺問：「那你讓他明天再來嗎？」"},{"type":"p","text":"居萬不答，望向麗華。麗華正在替阿綺擦掉裙上的酒，頭也不抬。"},{"type":"p","text":"阿綺拿走了錢。"},{"type":"p","text":"她本來想把那幾張鈔票扔回居萬臉上。翌日母親的信到了，信裡只有兩句話，說家裡的瓦漏雨，弟弟的鞋又小了。她便把錢折好，塞進信封。寄出前還數了兩遍。數到最後一遍，她把昨夜居萬的話學給自己聽，學得惟妙惟肖，忽然覺得他也沒有那麼可笑。"},{"type":"p","text":"只是七號桌那張椅子，第二天仍留著。"},{"type":"chapter","text":"第十四回｜阿綺替自己取名字"},{"type":"p","text":"阿綺原來不叫阿綺。她初到店裡時，麗華問要不要用本名，她說不要，又怕人追問，補了一句名字不好聽。麗華不笑她，只在登記紙上空出一格，說想好了再填。月琴在一旁打趣，叫她趕快想，名字若太好聽，客人會記住，若太難聽，又怕客人故意拿來取笑。"},{"type":"p","text":"她選「綺」，因為看見一件舊衣料上繡著這個字。麗華說字好，不過筆畫多，她笑說反正也輪不到自己常寫。說著說著，卻在空白紙背練了許多遍。她的手指因洗衣洗得粗，寫字不穩，頭兩個「綺」歪歪斜斜，第三個才稍像樣。那一天她頭一次覺得，自己好像能替自己決定點什麼。"}],"running":"第十四回｜阿綺替自己取名字","section":"第三部｜春潮初上"},{"pdf":44,"blocks":[{"type":"p","text":"客人問她從哪裡來，她照教好的話答，笑的時候露出牙齒，轉身進後房卻立刻收起笑容。月琴見了說別把臉繃得那麼緊，容易老。阿綺反問：「我若不笑呢？」月琴替她把散下的一縷頭髮夾住：「那就想法子存錢。存到能不笑的那一天。」"},{"type":"p","text":"夜裡有一位客人硬要她唱歌，她說不會。居萬過來替她打圓場，幾句玩笑總算使對方轉了念頭。阿綺感謝老闆，卻也看見同一句話若由男人說出口，便能被當作趣味；若由女人說出口，就容易被當作不識抬舉。"},{"type":"p","text":"她把這樁小事記在心裡，沒有記恨居萬，也不因他替自己解圍便把一生的感謝交出去。夜散了，她把當日工錢攤平，用針線盒壓住，像壓住一張慢慢寫成的通行證。她要去的地方還沒有名字，但她知道，總有一天自己要帶著真正的名字走出去。"},{"type":"p","text":"阿綺替自己取了新名字以後，還試著改掉走路的姿勢。她從前步子太大，老闆娘說夜裡穿長裙容易絆住；她便在空房裡學著把腳步收短。可一出店門，她又走得很快，像怕誰從背後追上來。她忽然明白，人的姿態也分工作時與下工後兩種，連自己都容易把它們弄混。"},{"type":"p","text":"有晚新來的客人說她這名字像小說裡的人，又問她真正的名字。她笑著把問題推回去，問先生平日做什麼。對方說做船。她便問一艘船該不該有兩個名字。客人說船當然只有一個船名。她答：「那是因為船不必同人解釋，為什麼非得離港。」那人一時聽不懂，只當她會講漂亮話，拿起酒杯又笑了一回。"},{"type":"p","text":"她把收入分成三份，一份寄家，一份存起，一份供自己添置衣物。存錢的信封藏在箱底，每次數過又封回去，像在一個不肯開門的地方天天敲"}],"running":"第十四回｜阿綺替自己取名字","section":"第三部｜春潮初上"},{"pdf":45,"blocks":[{"type":"p","text":"門。她聽麗華說外頭有人找女工，工時長，賺得不如夜裡多，卻可以在日落以前回家。阿綺想了一陣，不知道該不該去。她真正怕的不是收入變少，而是若離開這裡，旁人還肯不肯相信她能做別的事。"},{"type":"p","text":"阿綺在休息間替另一名女侍縫裙邊時，麗華忽然問她，若有朝一日離開這裡，想做什麼。她手上的針停住，說沒想過。麗華不信，逼她說實話。她才慢慢說，想開一間店，店裡不必太亮，客人要買就買，不買也不必陪笑到半夜。麗華說這願望倒小。阿綺搖頭：「想一整日不用看別人的臉色，怎會小？」隔日有位客人誇阿綺會說話，拿錢要她改一個更合自己喜好的名字。她笑說不行。客人又加了一張鈔票，旁人便替她起鬨，說這點事何必固執。阿綺仍然不肯。那男人惱羞成怒，說一個名字有什麼了不起。阿綺答：「既然沒什麼了不起，先生何必花錢買？」桌旁竟有人拍手叫好。居萬聽見吵鬧趕過來，先替客人賠笑，轉頭卻見阿綺的指尖在袖口裡發抖，知道事情並非一句笑話能抹平。後來麗華勸她，做這行不必句句認真。阿綺承認自己怕，怕有一天連名字也不是自己的，連不想笑時也得笑得比誰都大聲。麗華聽了，沒有說她年輕不懂，而是把自己的手指攤給她看。那雙手因常年整理衣物，指腹磨得粗，她說：「旁人看見我們，常只看見粉和衣裳。手在這裡，日子也在這裡。若連自己也不看見，就真沒人替我們看了。」阿綺自此養成記錄每筆工錢的習慣。她寫字不快，常把數字擠在一起，有一回竟少算了自己一日薪水。彩雲看見，教她留出空格，註明日期。阿綺說掌櫃夫人不怕自己以後討起帳來更厲害？彩雲答：「妳若算得明白，我才好睡。」這話阿綺聽過很久，日後離開春潮時，帶走的除了積蓄，還有一本字寫得愈來愈整齊的小帳簿。"}],"running":"第十四回｜阿綺替自己取名字","section":"第三部｜春潮初上"},{"pdf":46,"blocks":[{"type":"p","text":"月琴原先不願意叫月琴。她說這名字太像一首別人點來聽的歌，唱完便沒了。店裡有人勸她好記就行，客人哪會細想。她卻認真在紙上寫過幾個名字，最後仍用回月琴，說自己至少要先弄明白：別人叫這兩個字時，究竟是在叫她，還是在叫桌旁那個必須陪笑的人。"},{"type":"p","text":"她有一回得罪了客人。那男人要她把一段家裡的往事講來助興，她說那是自己的事，不肯講。對方說做這行哪有秘密，掏出鈔票往桌上一放，像用錢便能替人取下一層皮。麗華看不過去，過來解圍，說不如聽歌。客人不依，聲音越發高。居萬急忙迎上，照舊想用笑話把事帶過。月琴卻忽然站起來，問他：「王先生，若有人付錢，要你把彩雲的私事說給大家笑，你肯嗎？」"},{"type":"p","text":"整桌人靜了。居萬臉上的笑掛不住，這回沒有人替他圓場。他把客人的錢推回去，說今夜的酒照喝，不必談人家的家事。男人罵罵咧咧走了，店裡一時冷清。月琴回後房後仍在發抖，怕明日起沒了工作。彩雲卻叫人拿一杯熱水給她，還說：「她今天沒有做錯。」"},{"type":"p","text":"月琴沒立刻道謝。她只是把鏡子轉過來，看著自己花了一個時辰才畫好的眉眼，忽而覺得這張臉雖然借給店裡的燈用過，卻仍是她自己的。後來她照樣接客、照樣笑，也照樣偶爾說不。不是每個人都喜歡這樣的她，但她第一次不再把所有不喜歡都算成自己的損失。"},{"type":"p","text":"某次彩雲見她在後房縫衣角，替她找了塊布墊在膝上，問要不要拿一只線軸。兩人談的全是針腳與布邊，誰也沒問誰的私事。阿綺忽然有些感動，竟又怕顯得太容易感動。到了夜裡，她對鏡梳頭，默默把假名和真名"}],"running":"第十四回｜阿綺替自己取名字","section":"第三部｜春潮初上"},{"pdf":47,"blocks":[{"type":"p","text":"各念一遍。兩個名字都像自己，又都不全是自己；要成為完整的人，原來遠比替自己挑個好聽的字難。"},{"type":"chapter","text":"第十五回｜彩雲的兩本帳"},{"type":"p","text":"彩雲第一次真正看清酒店的夜，是來替丈夫送一本遺落的帳簿。"},{"type":"p","text":"一進門，她先聞到酒，再聽見音樂，最後才看見人。燈光把每個女人的面孔描得比日常鮮明，也把每個男人的年紀藏得比白天妥當。居萬正與一桌客人談笑，見她來了，臉上那副做生意的笑容短了一寸。"},{"type":"p","text":"「妳怎麼來？」"},{"type":"p","text":"「帳本忘了。」"},{"type":"p","text":"他伸手接過，又怕她立刻走，說：「坐一下。」"},{"type":"p","text":"彩雲不坐，只見麗華從櫃臺後頭走出，替她端一杯熱茶。那女人說話不快，眉眼很穩，杯底還墊了一張乾淨紙巾。彩雲道謝，並沒有旁人想像中的敵意。"},{"type":"p","text":"她早知道靠這地方領薪水的女人也是討生活的人。她在意的是居萬在這裡究竟將多少承諾說得太輕。"},{"type":"p","text":"回家以後，她拿出另一本帳。米錢、孩子日後的學費、屋裡要修的地方，樣樣都有數目。居萬看了笑她：「小事也要記？」"},{"type":"p","text":"「在你那裡是小事，到我這裡便是下個月。」"},{"type":"p","text":"「我會賺。」"}],"running":"第十五回｜彩雲的兩本帳","section":"第三部｜春潮初上"},{"pdf":48,"blocks":[{"type":"p","text":"「賺得到，不等於守得住。」"},{"type":"p","text":"他不喜歡這話，卻又不能說她錯。酒店的帳有時是一夜結清，家庭的帳卻要幾十年慢慢還。兩本帳同出一戶人家，竟像彼此不認識。"},{"type":"p","text":"那晚他們沒有吵架。居萬出門前，彩雲只問：「你今天幾時回來？」"},{"type":"p","text":"他說：「不會太晚。」"},{"type":"p","text":"她抬起頭，緩緩道：「以後少拿這句話當時間。」"},{"type":"p","text":"彩雲帶回家的那本帳，封面被酒漬沾出一個印子。居萬說這印子有損體面，應當換本新的。她卻說不用，哪怕封面難看，帳裡的數字也比一張乾淨紙更可靠。他認為這是女人故意頂嘴，她心裡明白，丈夫嫌棄的其實不是那個印，而是那本帳記下了許多不能靠人情抹掉的錢。有一晚居萬答應一位老友，替人墊付半月房租。老友說周轉一下便能還，並提起過去一起挨過的辛苦，講到動情處幾乎掉淚。居萬不好拒絕，回家才告訴彩雲。她問老友的姓名住處，居萬說相交多年還需要這些？她便道：「你們交情深，是你們的事；我的帳只會問錢到哪裡去。」兩人僵持到夜深，居萬終於說她冷血。她聽見這句話，反而平靜下來，說自己若真的冷血，早不會替他把一年裡欠出去的款一筆一筆追回。過了一月，老友果然還了錢，還特意拎果子來道謝。居萬勝利般地把錢放在桌上，說妳看人不能只看壞處。彩雲把帳勾掉，點頭說是。隔天又有另一位熟客來借，理由竟和前一位幾乎一模一樣。居萬忽然不答應了，轉頭看了看妻子。她沒笑他，只問客人何時需要、還款打算如何。那人見他們問得仔細，推說再想想，轉身走了。居萬回頭道：「也不見得是騙人。」彩雲說：「我知道。可是我們沒有義務用一家人的明天，去證明每個人今日都值得相信。」這句話後來"}],"running":"第十五回｜彩雲的兩本帳","section":"第三部｜春潮初上"},{"pdf":49,"blocks":[{"type":"p","text":"被年幼的曉芬在門邊聽見，只記得一半。她長大後遇見肯說好話的人，總以為自己比母親大膽，比父親清醒，不至於把愛與欠帳混在一起。誰料聰明的人也會在自己最想相信的事情上，把證據看得最輕。那是很久以後的事，先且留待下一輯再說。"},{"type":"p","text":"話輕，卻比責罵難接。"},{"type":"p","text":"那年年底，春潮結工錢時少了二十塊。月琴拿著薪袋來問，說上一個月多值兩夜的班，怎麼比平常還少。彩雲翻帳，發現原來是居萬替一桌熟客免了酒錢，帳上卻將那兩夜的開支照算在女侍頭上。"},{"type":"p","text":"她拿筆在紙上點了點，叫月琴明早再來。"},{"type":"p","text":"居萬聽見，說不就二十塊，補給她便是。彩雲回道：「補給她容易，你去向客人討？」"},{"type":"p","text":"「朋友面前討什麼！」"},{"type":"p","text":"「朋友在桌上喝了酒，我倒叫姑娘沒了工錢。」"},{"type":"p","text":"居萬不耐煩：「妳算得這樣清，往後誰敢來捧場？」"},{"type":"p","text":"彩雲原想把錢從自己的口袋拿出來，聽他這樣講，偏將帳冊一合，說那就按你當初記的走。居萬愣住，見她臉色不對，也不敢再說。"},{"type":"p","text":"月琴隔天來時，彩雲把薪袋放在桌上，說這次核算沒錯。月琴不敢相信，翻了幾遍，小聲問是不是她哪一晚做得不夠好。彩雲說照帳如此。月琴眼圈紅了，仍低聲道謝，把錢收進袋裡便走。"}],"running":"第十五回｜彩雲的兩本帳","section":"第三部｜春潮初上"},{"pdf":50,"blocks":[{"type":"p","text":"那聲謝謝在屋裡留得很久。彩雲端起茶想喝，手抖得碰到杯沿。她這才驚覺自己方才分明知道錯在誰，卻拿一個姑娘的工錢去堵丈夫的嘴。"},{"type":"p","text":"晚上她找月琴，說前天漏算了一筆，這才拿出二十塊。月琴先高興，接著問：「怎麼會漏算？」"},{"type":"p","text":"彩雲原本有一句現成話，說做生意帳目繁雜，誰都可能疏忽。她看著月琴伸來接錢的手，忽然厭倦。她說：「我昨天不想給妳。」"},{"type":"p","text":"月琴的手停在半空。「為什麼？」"},{"type":"p","text":"「我在跟人賭氣。」"},{"type":"p","text":"月琴慢慢把錢接過去，數了一遍，收進袋裡。她臨走前問：「那妳現在氣消了？」"},{"type":"p","text":"彩雲無法回答。月琴倒笑了，說她沒有生氣，只怕下回再少，自己連問都不敢問。她笑得很客氣，眼睛卻紅著。彩雲說以後不會了。月琴沒點頭，只請她往後若帳有問題，先寫清楚。"},{"type":"p","text":"居萬回家時，彩雲沒向他提這事。他提起月琴，說那姑娘今日見他竟不打招呼，真不懂事。彩雲把燈芯剪短一截，火苗跳了兩下。她想把方才自己做過的事說出來，卻怕丈夫知道她也曾拿人出氣，便只說女孩子上了一天班累了。"},{"type":"p","text":"那夜月琴回宿舍，拿起信紙給家裡寫信，開頭還是「錢已寄，勿念」。她寫完又塗掉，末了只剩兩個字：「安好。」"}],"running":"第十五回｜彩雲的兩本帳","section":"第三部｜春潮初上"},{"pdf":51,"blocks":[{"type":"p","text":"隔週，居萬要月琴陪一位外地來的客人喝酒。月琴說身子不舒服，換個人去可不可以。居萬笑著說她難得學會挑客人了，桌邊的人一齊笑。月琴把托盤握緊，轉身進了後房。阿綺幫她解圍，說自己可以替班，卻向居萬多討半夜工錢。"},{"type":"p","text":"「妳當我開善堂？」居萬半開玩笑。"},{"type":"p","text":"「你開什麼我不知道。」阿綺說，「今夜要人做事，就給人錢。」"},{"type":"p","text":"彩雲坐在角落聽著，覺得一陣熱氣沿著脖子往上竄。她明明想替阿綺說話，又覺得這姑娘偏要當眾頂撞居萬，將一點還能轉圜的體面也撕了。她叫阿綺先去換衣服，口氣硬得自己都陌生。阿綺答「知道了」，拉開門時回頭望她一眼。那目光沒有怨，也沒有親近；彩雲卻一直記著。"},{"type":"p","text":"那晚回家，居萬說店裡的人如今一個比一個會算。彩雲沒有應聲。她在算盤上撥了兩下，忽然把算珠全推回去。居萬問她做什麼，她說沒事。他以為她累了，還替她將椅子推到燈下。彩雲看著丈夫殷勤的手，半晌才把帳冊打開，從頭重新算了一次。"}],"running":"第十五回｜彩雲的兩本帳","section":"第三部｜春潮初上"},{"pdf":52,"blocks":[{"type":"part","text":"第四部｜紅燈兩面"},{"type":"chapter","text":"第十六回｜一座店兩個掌櫃"},{"type":"p","text":"春潮開張第三個月，有位熟客太太來店裡找一副耳環。"},{"type":"p","text":"那女人穿一套湖水綠的裙，出門前顯然仔細燙過，到了店裡卻把皮包抓得像要扭壞。她說丈夫昨夜來喝酒，回家時襯衫口袋多了一張紙條；紙條上寫著一個姑娘的名字。如今家裡少了一副金耳環，她疑心丈夫送了人。"},{"type":"p","text":"居萬把人請到最靠裡的桌子，笑著倒茶。「嫂子，妳先喝口水。這裡做生意，姑娘們有規矩。」"},{"type":"p","text":"「你替誰擔保？」女人盯著他，「替我丈夫，還是替你的姑娘？」"},{"type":"p","text":"麗華站在櫃台後，一聲不吭。紙條上的名字正是她，昨夜她替那客人找過遺失的帽子，客人說改日要送水果答謝，她便記下自己的名字給他。如今彩雲也在場，女人要麗華打開皮包。"},{"type":"p","text":"「打開看看，沒有就沒事。」居萬輕輕說。"},{"type":"p","text":"麗華抬起眼：「老闆，你也要我打開？」"},{"type":"p","text":"他咳了一聲，仍帶著笑：「總要讓人安心。」"},{"type":"p","text":"麗華把皮包放到桌上，倒出粉盒、梳子、零錢，最後落出一張皺了的車票。女人一件一件看，沒找到耳環，卻仍不肯走。「房間呢？」"},{"type":"p","text":"「妳到此為止。」彩雲忽然開口。"}],"running":"第十六回｜一座店兩個掌櫃","section":"第四部｜紅燈兩面"},{"pdf":53,"blocks":[{"type":"p","text":"居萬一愣。她向那位太太說：「要搜房，叫警察來。要問妳丈夫，回去問他。妳在這裡把人衣裳脫了也找不到他的嘴。」"},{"type":"p","text":"女人臉上青一陣白一陣，猛地站起，茶杯被撞翻，水順桌沿淌到麗華的鞋面。居萬忙著追到門外，說了許多好話，送得遠遠的。"},{"type":"p","text":"人走後，他回來第一句便怪彩雲：「妳這樣把客人趕出去，明日誰敢來？」"},{"type":"p","text":"彩雲指著櫃台。「她敢來嗎？」"},{"type":"p","text":"麗華已在收拾包內的東西，像兩個人談的是另一樁買賣。居萬轉向她，聲音軟了些：「妳先休息兩天。店裡照給妳算。」"},{"type":"p","text":"「我明天上班。」麗華說。"},{"type":"p","text":"「我讓妳休息，是怕外頭不好聽。」"},{"type":"p","text":"麗華把空粉盒扣緊。「我不上班，房租你替我給？」"},{"type":"p","text":"居萬的笑終於全沒了。他拿起算盤，劈哩啪啦地撥了幾下，又推回去，最後說隨妳。"},{"type":"p","text":"事情過了兩晚，那熟客自己跑來，從西裝口袋取出一隻金耳環。他太太原來把一副拆開分放，忘了另一隻收在哪；他怕挨罵，硬說什麼也不曉得。這會兒知道錯了，來請老闆做東，替夫妻兩人和解。"},{"type":"p","text":"居萬聽得直笑：「你家這筆糊塗帳，差點害我折了一個人。」"},{"type":"p","text":"熟客說改天帶太太來道歉，又說酒算他的。兩人談得熱絡，麗華端茶時把杯子重重放下，聲音很響。熟客抬頭，說姑娘脾氣見長。"}],"running":"第十六回｜一座店兩個掌櫃","section":"第四部｜紅燈兩面"},{"pdf":54,"blocks":[{"type":"p","text":"居萬想打圓場，麗華已說：「今天的酒請先付現。」"},{"type":"p","text":"彩雲在帳房聽見，忍不住笑了一聲。接著她發覺自己笑得太快。居萬聞聲望來，她低頭翻帳，翻得滿頁都是空白。"},{"type":"p","text":"夜裡盤點，麗華發現少了一枚銅板，彎腰找了很久。居萬看不過去，說一枚銅板算什麼。麗華直起腰，望著他：「你那杯酒可以請人，我這枚銅板還得算清。」"},{"type":"p","text":"她找不到，最後自己從薪袋裡補了一枚。居萬看著她把銅板壓進抽屜，嘴動了一下，還是轉身去招呼外頭的新客。"},{"type":"chapter","text":"第十七回｜客人未走，天已亮"},{"type":"p","text":"春潮生意最好的一段日子，居萬幾乎天天把夜過成白天。"},{"type":"p","text":"有客人談貨運，有人談船，有人來慶功，有人只是不敢太早回家。男人喝上幾杯，便把自己說得無所不能；女人聽上幾遍，便知道哪句話該點頭，哪句話該當沒聽見。"},{"type":"p","text":"某晚客人走得遲，阿綺靠在門邊，鞋跟磨得腳痛。她問居萬能不能先領一部分工錢，母親有急用。居萬正算帳，隨口說：「明日再來。」"},{"type":"p","text":"「明日醫生不肯等。」"},{"type":"p","text":"他抬起頭，才見她原來並不是撒嬌。"},{"type":"p","text":"他在帳本裡壓下一張鈔票，說了句重話：「拿去，也不早點講。」"}],"running":"第十七回｜客人未走，天已亮","section":"第四部｜紅燈兩面"},{"pdf":55,"blocks":[{"type":"p","text":"阿綺沒謝他，只將錢摺好，放進手袋。出了門，才讓雨打在臉上。居萬以為她生氣，麗華卻說：「人到難處，謝不謝你，沒那麼要緊。」"},{"type":"p","text":"他不喜歡被教訓，尤其不喜歡在自己店裡被教訓。然而第二天有人問起阿綺，他到底沒有提那筆錢。"},{"type":"p","text":"其實春潮也沒他想的那麼賺錢。酒水有損耗，客人有賒帳，燈壞了要修，店員有家要養。最難算的是面子：熟客說過兩天給，他竟也不好意思催。彩雲看見月尾的帳，問：「你做的是生意，還是替人開會？」"},{"type":"p","text":"居萬回：「認識的人多，路才走得開。」"},{"type":"p","text":"彩雲冷冷說：「路是走得開了，門怎麼都關不起來？」"},{"type":"p","text":"居萬最怕的不是沒客人，而是客人散得太早。有人酒量不濟，才坐一會便說要回家，他便拉著人再談兩句，說難得來一趟，不如再聽一首歌。看似熱情，心底卻存著一點不肯承認的虛榮：一張桌若因他而延長，便像有人替他的本領作證。彩雲見過他招呼熟客，目光總在眾人的笑臉上巡過，像戲臺上的演員等最後那一下喝采。有一夜碼頭忽然下起大雨，幾個準備離去的人被留在店裡。電路一時出了毛病，整間店暗了一半。姑娘們摸黑尋蠟燭，居萬卻拍著手說，正好來一段沒有燈的舊歌。麗華唱了一首故鄉的小調，第一句出來，原本吵鬧的人便靜了。有人聽得出了神，拿著空杯也忘了添酒。歌聲飄到門口，彩雲站在那裡，忽覺這個男人平日那麼愛耀武揚威，難得也有一刻知道退到別人身後。唱完有人要麗華再唱，還拿錢敲桌，像只要銀錢夠響，人的嗓子便不會疲倦。麗華搖頭說今日就到這裡。居萬正要替客人勸，見彩雲向他看來，話忽然止住。他改口說好歌要留待下回，惹得幾人抱怨，卻總算讓姑娘回休息間。待客人走後，麗華"}],"running":"第十七回｜客人未走，天已亮","section":"第四部｜紅燈兩面"},{"pdf":56,"blocks":[{"type":"p","text":"把一只杯子洗得格外久。居萬過去說她今晚唱得好，她回道：「唱得好，未必便該唱到不能再唱。」他沒回嘴，只問她明日可要晚些上工。彩雲聽見，原想誇丈夫一句，卻怕那句話又替他換來一筆自得。她把帳本合起來，提醒他電線須趁天亮找人檢查。居萬說知道了，語氣竟與先前對麗華時一樣溫和。那夜兩人回家，路上沒有談生意，也沒有談朋友，只談孩子近來喜歡什麼。夜色裡居萬忽而說：「有時候真想把這店關了，好好睡一覺。」彩雲問既這樣，為何不關？他停住腳：「關了，人就不來找我了。」這句老實話比他講過的一百句豪言，更叫她心酸。"},{"type":"p","text":"這句話日後變成兩人之間一樁長久的笑話。當時卻誰也笑不出來。"},{"type":"chapter","text":"第十八回｜聽見別人的名字"},{"type":"p","text":"彩雲發現絲巾不對，是因為上面還有一點香水味。"},{"type":"p","text":"那是一條正紅的絲巾，居萬拎回來時得意，說百貨公司的櫃姐挑的，準不會錯。彩雲先嫌顏色招搖，後來還是在鏡前試了試。鏡中的女人被紅色一襯，嘴唇也紅了。她正要笑，忽然聞見一絲甜膩的香。"},{"type":"p","text":"「誰試過？」"},{"type":"p","text":"居萬正解領帶。「什麼誰試過？」"},{"type":"p","text":"「這條。」"},{"type":"p","text":"「店裡新的，怎麼會有人試過？」"},{"type":"p","text":"「你過來聞。」"}],"running":"第十八回｜聽見別人的名字","section":"第四部｜紅燈兩面"},{"pdf":57,"blocks":[{"type":"p","text":"他不過來，說她鼻子一天比一天靈，末了竟笑起來。彩雲最恨他這個笑，仿佛只要嘴角一彎，別人便不必問下去。"},{"type":"p","text":"「拿走。」"},{"type":"p","text":"「不喜歡就算了，明天換一條。」"},{"type":"p","text":"「我叫你拿走！」"},{"type":"p","text":"居萬也惱了，把絲巾往床上一丟：「好端端的買東西回來，妳到底要怎樣？」"},{"type":"p","text":"彩雲一把抓起絲巾，走到廚房，掀開正在燒水的壺蓋，差一點就要把它扔進去。水汽撲在她臉上，她反而定住。屋裡孩子在笑，電視唱著不成調的廣告。她把絲巾塞進最底下的櫃子，塞得太急，扯掉了一截流蘇。"},{"type":"p","text":"隔日她去酒店送帳冊，聽見阿綺叫出一個名字。叫的是來店裡找居萬的女子，聲音稀鬆平常。彩雲也沒聽清她姓什麼，只聽見居萬答了一句「妳又來了」，那語氣同他對普通客人的不同，帶一點嫌，又帶一點熟。"},{"type":"p","text":"彩雲走進去，從居萬手裡抽過帳冊。紙邊刮了他手背一下，他皺眉，她竟有一瞬間痛快。"},{"type":"p","text":"「黃小姐。」女人起身，笑得很客氣。"},{"type":"p","text":"「我姓王。」"},{"type":"p","text":"三人都不動。阿綺在旁邊裝忙，把空杯摞成一疊。"},{"type":"p","text":"女人說：「不好意思，我沒想到王太太會來。」"}],"running":"第十八回｜聽見別人的名字","section":"第四部｜紅燈兩面"},{"pdf":58,"blocks":[{"type":"p","text":"「妳想到誰會來？」彩雲問。"},{"type":"p","text":"居萬喝止她：「彩雲。」"},{"type":"p","text":"她本來可以到此為止。偏偏這一聲叫她聽出他是在替那女人解圍，火又上來：「你倒很會替人說話。回家怎麼一句都問不出來？」"},{"type":"p","text":"女人的臉先白後紅，抓起手袋往外走，走到門邊掉了一隻扣環。居萬彎腰替她撿，彩雲看著那隻伸出去的手，猛地把帳冊摔在桌上。封皮裂開，紙散了一地。店裡有人轉頭。她這才知道自己鬧得很大。"},{"type":"p","text":"居萬沒追出去，蹲著撿紙。彩雲也蹲下，撿到一頁時發現上面有孩子的學費數目。她恨不得一把撕了，手卻停著。"},{"type":"p","text":"晚上居萬不回房睡。彩雲在孩子睡後拿出那條紅絲巾，對著暗掉的鏡子又試了一次。她想把流蘇縫好，穿針穿了三回才成功。第四回她把線一扯，索性不縫了。"},{"type":"p","text":"第三天，居萬開口問她晚上要不要一起出去吃飯。"},{"type":"p","text":"「你請誰？」她說。"},{"type":"p","text":"「妳。」"},{"type":"p","text":"「那倒不必，」彩雲把鍋蓋扣回去，「我怕人看見，說你又帶別人家的女人出門。」"},{"type":"p","text":"居萬聽了，先想笑，旋即沉下臉。他們誰也沒有提酒店那一幕；彩雲卻把飯燒焦了。她明明聞到焦味，還故意不掀鍋。"}],"running":"第十八回｜聽見別人的名字","section":"第四部｜紅燈兩面"},{"pdf":59,"blocks":[{"type":"chapter","text":"第十九回｜一封沒有寄出的信"},{"type":"p","text":"麗華有個小鐵盒，裡頭放著幾張信紙。她不寫給情人，只寫給多年沒有回去的故鄉。有的寫到一半便停，因為她不知道怎樣向家裡解釋自己現在的日子。"},{"type":"p","text":"春潮裡的客人總說外頭世界很大。當真叫他們說出這些女人能往哪裡去，答案卻少得可憐。"},{"type":"p","text":"有一位常客曾向她保證，要帶她到別的城市開店。說的那夜，男人坐得端正，連酒也喝得節制。過兩個月，他再來時身旁坐了新婚妻子，介紹麗華只說：「這裡很會招待客人。」"},{"type":"p","text":"麗華點頭，將菜單推到那位妻子面前，問她要喝什麼。她笑得周到，連自己都幾乎相信沒有任何事發生。"},{"type":"p","text":"居萬在後頭看得不忍，等人走了，說：「男人的話，不必每句都當真。」"},{"type":"p","text":"麗華把椅子推回桌下：「王老闆，這話你最好回家也講一遍。」"},{"type":"p","text":"他臉上熱了一下，裝作沒聽見。"},{"type":"p","text":"那夜回到家，他見彩雲睡了，便不敢把燈全開。她在黑暗裡忽然問："},{"type":"p","text":"「你站在那裡做什麼？」"},{"type":"p","text":"「怕吵醒妳。」"},{"type":"p","text":"「你回來，便已經醒了。」"}],"running":"第十九回｜一封沒有寄出的信","section":"第四部｜紅燈兩面"},{"pdf":60,"blocks":[{"type":"p","text":"居萬坐在床沿，頭一次覺得白日那一套伶俐話，放到這間屋裡竟沒有地方擱。"},{"type":"p","text":"他沒說自己聽見麗華那句話，也沒說酒桌上人們又怎樣誇他本事。彩雲聽著窗外的雨，忽然伸手把床邊的燈關了。"},{"type":"p","text":"「睡吧。明天還要過日子。」"},{"type":"p","text":"麗華寫信時，總把最要緊的事留在最後。開頭是天氣、工作、路上的樹，寫到第二頁才說自己也有累的時候。她怕故鄉的人擔心，也怕他們誤會，以為她在繁華地帶做事便有大把鈔票。寫好的信她一封封摺起來，裝進小鐵盒。有幾封明明貼了郵票，又被她撕下，留下薄薄的紙毛。有一回阿綺替她送東西，無意瞧見信封上同一個地址寫過三次，便問寄不寄。麗華說等有空。阿綺偏不懂：「寄信還要挑日子嗎？」麗華答：「有些話寄出去，別人就要替妳操心；不寄，又像妳根本沒說過。」她把信抽出，劃掉一句「我過得很好」，另寫「我還過得去」。兩句只差幾字，她卻看了好久，最後仍裝回鐵盒。彩雲偶爾到店裡，看見她們為一張信紙愁眉，便說信若寫不完，可以先寄短的。麗華笑著問掌櫃夫人可寫過不能寄的信。彩雲沒有回答。她想起年少時寫給居萬的一張便條，原想問對方究竟有幾分真心，後來撕掉，改成提醒他明日天氣冷，出門加衣。自己明明想問感情，最後卻只敢問衣裳。她忽然懂了麗華的難處，便陪她把紙整理好，沒有勸她立刻作決定。數月後一個陌生男人到店裡問麗華的去處，自稱是她鄉親，說家中有急事。居萬本想直接叫人出來，彩雲先問他帶了什麼信物。男人言語閃爍，終究丟下一封信走了。麗華讀完，臉上一點血色都沒有。她沒有哭，只說明天想請假。阿綺問出了什麼事，麗華搖頭。許多人的命運就在那一瞬間改變了方向，旁人卻還當她只是要回家一趟。"}],"running":"第十九回｜一封沒有寄出的信","section":"第四部｜紅燈兩面"},{"pdf":61,"blocks":[{"type":"p","text":"他在黑暗裡伸手找她的手，碰到了，卻沒敢立刻握緊。"},{"type":"chapter","text":"第二十回｜麗華的還鄉路"},{"type":"p","text":"麗華曾買過一張返鄉的車票，買完又退。售票的人以為她改了行程，隨手把錢找回來；她捏著鈔票站在櫃檯前，竟像從遠方走了很久，終於又被送回原地。"},{"type":"p","text":"她不是沒有家可回。母親在鄉下，弟妹各有難處，逢年過節總有人託她帶點東西。若真回去，大家自然歡迎，只是歡迎過後，誰也不會替她回答街坊那些過分熱心的問題。她最怕的不是有人嫌她，而是有人假裝全然不嫌，講話卻比誰都小心。"},{"type":"p","text":"阿綺勸她回，說人總不能一輩子替別人的目光打算。麗華笑她年紀輕，話講得漂亮。其實她心裡也羨慕這份漂亮：年輕人還能把不公平叫做不公平，年長些的人太熟悉其中的規矩，連反抗都要先估量花費。"},{"type":"p","text":"一天夜裡，春潮來了位客人，酒後竟說自己多年未敢回家。眾人聽了笑，說有錢在外頭還不好？麗華替他倒水，忽然問：「若家裡一直有人等你呢？」客人怔住，將杯子推開。她自己也怔住，彷彿那句話不是問別人，而是有人隔了幾年終於肯來問她。"},{"type":"p","text":"店後那盆九重葛開得鮮明。麗華在它旁邊蹲下，將抽屜中的信重新抄了一封。這回不說自己很好，也不說自己受了多少苦，只寫天氣漸涼，母親出門記得添衣。信紙的最後，她寫：「我今年或許回去。」寫完沒有劃掉「或許」二字，因為那是她當時能給出的最誠實的承諾。"}],"running":"第二十回｜麗華的還鄉路","section":"第四部｜紅燈兩面"},{"pdf":62,"blocks":[{"type":"p","text":"月琴替她貼郵票，故意說她寫字漂亮，將來可替春潮做帳房。麗華答，帳房不是沒做過，這一回只想替自己做一件事。兩人相視而笑。人生一到轉彎處，常常沒有多少氣勢，只是有人終於肯把一封信寄出去。"},{"type":"p","text":"麗華終於決定回一趟故鄉。她把行李收得極輕，一件換洗的衣服，兩包替長輩買的茶，還有那封寫寫停停的信。上車前她在站口踟躕，想起多年以前離開家時也是這樣的清晨，只是當時身上錢少，心裡願望多，總以為到基隆以後一切都會自然而然地變好。"},{"type":"p","text":"在車上她遇見一個帶小孩的婦人。孩子睡不住，整路扭動，婦人只好拿糖哄他。麗華原想閉眼，見婦人忙亂，便替她扶住滑下的包袱。對方道謝，問她要回家嗎。這麼尋常的一句話，她竟答不上來。她說：「回去看看。」婦人點頭，沒有追問。麗華忽然覺得，世上也許還有許多善意不需要先知道一個人的過去。"},{"type":"p","text":"到了老家門口，她發現門框被漆成另一種顏色。弟弟已成家，孩子們在院裡追逐，見有陌生女人來，停下來打量她。母親從屋內出來，頭髮白了許多，見她第一眼既沒有哭也沒有笑，先問路上冷不冷。麗華頓時想起春潮後房裡那些夜裡準備的熱茶，原來人替別人倒茶，有時是在模仿很久以前有人怎樣愛過自己。"},{"type":"p","text":"麗華終於啟程那天，車站人多得像一口裝滿聲音的鍋。她只帶兩件行李，一件裝衣裳，一件裝回去要分給親戚的小東西。阿綺送她到月臺，一路說了十幾句保重，麗華終於忍不住笑：「妳再說下去，我就以為自己要上戰場了。」阿綺撇嘴，說也差不多。她們兩人都知道，回故鄉不一定比離開故鄉容易。月琴來得晚，氣喘吁吁，手裡拿著一包點心。麗華接過，"}],"running":"第二十回｜麗華的還鄉路","section":"第四部｜紅燈兩面"},{"pdf":63,"blocks":[{"type":"p","text":"問她錢可有剩。月琴說別管，還說自己已把先前借的那筆還清，借據可以撕了。阿綺卻說還清就收好，不必撕，日後有什麼好事也能拿出來作證。三個人笑著抱在一起，周圍旅客只當是尋常送別。火車響笛時，麗華忽然說：「往後若有人問我在這裡做過什麼，妳們別只說我會唱歌。」阿綺點頭，眼眶卻紅了。車子走後，阿綺一個人回春潮。經過市場，她買了兩條小魚，攤販問怎麼今日買得這麼少。她說少一個人吃飯。魚販不知緣故，隨口說人來人往總是如此。阿綺竟有些生氣，又不知氣從何來。她原來以為在酒店裡相識的人，總有一天要散，既知道便不該難過。可難過原不遵守人的道理；它只認得空出來的那張椅子。不久有信寄到店裡，信上寫麗華已找到新的差事，日子還不穩，叫她們放心。彩雲看見信封，先問是否要替她收好。阿綺搖頭，說這回信要貼在裡頭讓大家看見。居萬聽說麗華平安，便大聲講起她從前如何替店裡招徠客人，彷彿故事都是他成全的。彩雲把信取下來給他看，指著末尾一行說：「她說謝謝的是姐妹，不是春潮招牌。」居萬讀了片刻，沒再爭辯。"},{"type":"p","text":"晚飯時有人避開她的工作，有人則問得太直。麗華都沒有生氣。她最怕的是人人說得很客氣，卻在心裡替她安上一個再也拿不掉的稱呼。到了深夜，母親進來收碗，說：「你這些年養活自己，不容易吧。」她本想答還好，卻忽然把臉轉向窗外。最叫人難受的不是被責備，而是有人終於不問是非，只承認那些年確實難過。"}],"running":"第二十回｜麗華的還鄉路","section":"第四部｜紅燈兩面"},{"pdf":64,"blocks":[{"type":"part","text":"第五部｜兩種價錢"},{"type":"chapter","text":"第二十一回｜衣裳與人"},{"type":"p","text":"麗華有一件墨綠色的旗袍，領口洗得發白，穿在身上卻仍然端正。客人看她時，說她有氣派；阿綺看她時，知道那氣派有一半是縫出來的。"},{"type":"p","text":"她常在後房做針線。手裡拿的是針，眼睛看的卻是帳。誰家欠了多少酒錢，哪一桌的菜少上一道，哪個姑娘把腳磨破了皮，她一清二楚。居萬開店靠一張嘴，她替這張嘴收拾後頭的事情。旁人說她好命，遇見肯賞識人的老闆；她聽見了，只把線頭咬斷，從不替人解釋賞識和薪水原是兩回事。"},{"type":"p","text":"春潮有一位新來的姑娘，小說裡名叫月琴。她很年輕，來時拎一隻硬紙箱，箱子外頭的繩結打得結實，像是出門的人怕自己一不留神，連家都要在路上散掉。月琴不肯說以前做什麼，卻把每一枚銅板看得極重。客人給小費，她先藏好，才肯笑。"},{"type":"p","text":"阿綺看不慣她。她覺得月琴的笑太快了，像一扇門任誰來敲都肯開。麗華聽完，只說：「妳當年進門，也有人這樣看妳。」"},{"type":"p","text":"「我哪有？」"},{"type":"p","text":"「人的難看模樣，往往只有別人記得。」"},{"type":"p","text":"後來，阿綺在化妝桌底下拾到一只拆了線的荷包，裡頭夾著一張藥房的收據。她拿去還月琴，看見那姑娘手背上凍出細紋，忽然不知該說什"}],"running":"第二十一回｜衣裳與人","section":"第五部｜兩種價錢"},{"pdf":65,"blocks":[{"type":"p","text":"麼。兩人坐在鏡前，各自補粉，鏡子裡像坐了兩對女人。阿綺先把自己的暖水瓶推過去，說：「先喝一口，別等客人來了才喘氣。」"},{"type":"p","text":"同一個晚上，居萬為了招待一位有頭有臉的客人，臨時加了酒，又答應給對方折扣。麗華將單子攤在他面前：「這筆不是做生意，是做面子。」"},{"type":"p","text":"「做面子也是做生意。」"},{"type":"p","text":"「那讓面子來付工錢？」"},{"type":"p","text":"居萬正欲反駁，月琴端著空盤走過，說客人問能不能再添一碟花生。麗華取了盤，居萬則立刻換上笑臉，迎了出去。"},{"type":"p","text":"衣裳的顏色會過時，人的口味也會變，麗華留在春潮的墨綠旗袍卻久未有人敢穿。衣服收在櫃裡，領口的線細細裂開，像某種不肯痊癒的舊傷。阿綺有回翻出來，拿著對光看，說料子還好，補一補能再穿。月琴卻說那是麗華的，誰穿都不對。兩人爭了一陣，最後問彩雲。彩雲說衣服本來便是給人穿的，留著不是不可以，但別讓一件衣服替人守一輩子的空位。她將旗袍帶回家，小心拆開領口，重新接了一段布。縫的時候，曉芬坐在旁邊看，問這是給誰的。彩雲說給一位曾在店裡做事的阿姨。孩子又問她為什麼不自己縫，母親停了針，過一會才說：「她要往別的地方去了，手忙著替自己做另一件事。」曉芬似懂非懂，只替母親把線頭剪短。旗袍送回店裡時，有位年輕姑娘試穿，裙身稍長，腰又寬了一點。月琴看著她在鏡前轉身，終於說不如讓她穿，料子好，糟蹋了可惜。姑娘聽出衣服有故事，忙問是不是誰留下的寶貝。阿綺說原是位老朋友的，但並非寶貝，只是她曾穿著做過很多辛苦的事。姑娘便不再對著鏡子扭轉，將衣服"}],"running":"第二十一回｜衣裳與人","section":"第五部｜兩種價錢"},{"pdf":66,"blocks":[{"type":"p","text":"抱在懷裡，低聲說自己會惜物。那一刻阿綺明白，紀念人有時也可以是讓他們留下的東西再派上用場。居萬見了，稱讚彩雲手藝好，還說店裡離不開她。彩雲笑道：「你平日最愛說生意靠人情，到了要補衣裳的時候，卻沒見哪段人情自己會拿針。」居萬不服，說改日定替她買件新衣。她應了一聲，心裡卻想：能親手把舊衣縫好的人，不一定盼著新衣；有時只盼有人記得，線也是她一針一針穿過去的。"},{"type":"p","text":"他對一屋子人都好，並不是假話。只是他的好有時太寬，寬得連自己家裡的人也得替他填那個空。人說王老闆慷慨，女人們聽了，沒有一個反對，卻也沒有一個先鼓掌。"},{"type":"chapter","text":"第二十二回｜一桌不肯散的酒"},{"type":"p","text":"周老闆帶人來春潮那晚，故意叫了最貴的一桌菜。來的是他的車隊夥計、另一家行號的介紹人，還有一名住在港邊的搬運工阿水。阿水坐在門邊，凳子只沾了半個屁股。"},{"type":"p","text":"「今天誰也不准早走。」周老闆嚷著，「談妥了，阿萬跟著我做，少說再開兩間店。」"},{"type":"p","text":"居萬被叫得心癢，連忙替他倒酒。他回頭看見彩雲在帳房，招手叫她來。彩雲拿著鉛筆走到桌邊，問要合作的是車、倉庫，還是單做運輸的抽成。周老闆把酒杯推過去：「嫂子先喝一口再談。」"},{"type":"p","text":"「我不喝。」"},{"type":"p","text":"「女人家的，算得這樣清做什麼。」"}],"running":"第二十二回｜一桌不肯散的酒","section":"第五部｜兩種價錢"},{"pdf":67,"blocks":[{"type":"p","text":"居萬說：「她平日就這樣。」說完自己先笑，旁人跟著笑。彩雲把鉛筆放在桌上，正想走，周老闆忽然掏出一份寫好的紙，說只差一個名字就成。"},{"type":"p","text":"「你看，條件我替你爭到最好。」"},{"type":"p","text":"居萬拿起來，字密密麻麻的。他看得慢，旁人等得不耐煩。周老闆索性把紙翻到最後一頁，用手指點著空白處：「你信我還不信？」"},{"type":"p","text":"彩雲伸手要紙，居萬卻把手壓住。「先讓我看。」"},{"type":"p","text":"「你看得懂嗎？」她問。"},{"type":"p","text":"這話一出口，她就知道太狠。周圍忽然靜了。居萬的臉脹紅，立即拿過筆，刷刷寫下名字。"},{"type":"p","text":"周老闆一拍掌，滿桌人舉杯。彩雲把紙慢慢對折，沒有罵，也沒有喊。她問周老闆：「押的是哪一間？」"},{"type":"p","text":"「押什麼？」"},{"type":"p","text":"「這裡寫得清楚。借款人違約，保證人以名下店產負連帶責任。你要押哪一間？」"},{"type":"p","text":"周老闆伸手要拿回紙，她把紙推給他，按住一角。他笑著說小條款，日後再修。"},{"type":"p","text":"「名字已經簽了。」彩雲說。"},{"type":"p","text":"居萬聽見，才知道自己方才做了什麼。"}],"running":"第二十二回｜一桌不肯散的酒","section":"第五部｜兩種價錢"},{"pdf":68,"blocks":[{"type":"p","text":"她回頭問丈夫：「還要喝嗎？」"},{"type":"p","text":"居萬抓起杯子，酒剛入口便嗆了。他想瞪她，瞪到一半又轉頭去看周老闆。對方正在低聲吩咐介紹人收拾文件，方才拍得最響的手，此刻一直縮在桌布底下。"},{"type":"p","text":"阿水忽然站起，挨近周老闆：「老闆，搬貨那兩個月——」"},{"type":"p","text":"「現在談生意！」周老闆喝他。"},{"type":"p","text":"「就是生意。」阿水說，「我做了，你沒給。」"},{"type":"p","text":"周老闆猛地把椅子往後一推，說阿水故意來鬧場。居萬為了挽回桌上僵局，竟去拉阿水的手臂：「外頭再講，好不好？」"},{"type":"p","text":"阿水掙開他，指著那桌酒菜：「這桌你肯先付，工錢要我等。王老闆，你做保證人，也替我保證一回？」"},{"type":"p","text":"居萬臉都白了。彩雲沒有替他接話。阿水跨出店門時，撞上送冰的少年，整桶冰塊倒在門邊。周老闆低聲罵人不長眼。麗華拿掃帚來，掃了半天，冰塊越碎越多。"},{"type":"p","text":"客人終於走了。居萬坐在原位，聽彩雲說明天去找懂法律的人看紙。他卻說：「妳方才何必當眾這樣拆我？」"},{"type":"p","text":"彩雲把杯子一個個收起。收完最後一只，她問：「你問的是我，還是周老闆？」"},{"type":"p","text":"居萬摔了杯子，酒濺到襯衫上。「我問妳！」"}],"running":"第二十二回｜一桌不肯散的酒","section":"第五部｜兩種價錢"},{"pdf":69,"blocks":[{"type":"p","text":"麗華在門口停了停，拿著掃帚又退回後房。彩雲繼續收拾碎片，一片割破手指。居萬見了，急著伸手，她猛地甩開；血落在桌布上，他一下站住了。"},{"type":"p","text":"隔日去請教人，才知道那份紙確實不能隨便簽。文件雖有改議餘地，字已留下，麻煩遠未完。居萬回家，見彩雲正坐在餐桌邊替小孩縫書包。他想說自己已經找人處理，喉嚨卻乾得厲害，最後只問：「妳傷口還疼不疼？」"},{"type":"p","text":"彩雲咬斷線頭：「你昨天不是只怕我讓你沒面子？」"},{"type":"p","text":"他把手裡的藥膏放在桌上，坐了片刻。隔壁電台正播一首老歌，唱到副歌，卡了一下，又從頭唱起。彩雲把收音機關掉了。"},{"type":"chapter","text":"第二十三回｜一席酒的價錢"},{"type":"p","text":"春潮最熱鬧的那夜，店裡辦一場壽酒。壽星是個做買賣的男人，人長得不起眼，身邊卻跟了好幾個想替他倒酒的人。到半夜，他說要聽一首舊歌，樂聲一起，竟伏在桌上哭了。"},{"type":"p","text":"居萬一向見不得別人在自己店裡難堪，忙拉椅子坐下，替他說笑。那男人指著杯子道：「王先生，你說做人到底圖什麼？」"},{"type":"p","text":"「圖個痛快。」"},{"type":"p","text":"「痛快完了呢？」"},{"type":"p","text":"「明早還得起來。」"}],"running":"第二十三回｜一席酒的價錢","section":"第五部｜兩種價錢"},{"pdf":70,"blocks":[{"type":"p","text":"席間大笑。壽星也笑，可笑完以後，他仍把臉埋在手掌裡。居萬這才明白，有些人求熱鬧，不過是為了叫屋裡的聲音大過心裡的聲音。"},{"type":"p","text":"散席時，壽星將一只金色打火機擱在櫃臺，說明日差人來付帳。居萬瞥一眼便收下，連欠條也沒有寫。麗華見了，不肯替他入帳。"},{"type":"p","text":"「這東西值錢。」居萬說。"},{"type":"p","text":"「值多少錢是他的話。欠多少錢是我們的帳。」"},{"type":"p","text":"「妳怎麼連人情都不信？」"},{"type":"p","text":"「我信，所以才叫你寫清楚。人情最怕沒有記性。」"},{"type":"p","text":"居萬被她說得不耐煩，擺手要她歇息。過幾日，壽星沒來，差人也沒來；有人傳那人週轉不靈，已先一步躲債去了。打火機倒是好看，送到當鋪一問，值不了幾個錢。"},{"type":"p","text":"彩雲得知以後，將飯盛在他面前，問：「你當晚是不是很神氣？」"},{"type":"p","text":"「做生意總有風險。」"},{"type":"p","text":"「那人為什麼哭？」"},{"type":"p","text":"「我怎麼知道？」"},{"type":"p","text":"「你不是最會懂人？」"},{"type":"p","text":"這一句問得他筷子停在半空。彩雲沒有追問，只抱起睡醒的孩子，替孩子把背後的衣襟拉平。居萬望見她肩頭的一小片濕痕，才想起自己昨夜說了許多安慰別人的話，回家卻忘了問孩子是不是又發燒。"}],"running":"第二十三回｜一席酒的價錢","section":"第五部｜兩種價錢"},{"pdf":71,"blocks":[{"type":"p","text":"他本想道歉，話到嘴邊卻改成：「今晚早點回。」"},{"type":"p","text":"彩雲說：「你不必替我報時。我看鐘比你準。」"},{"type":"p","text":"那場壽酒最熱的時候，周先生也在座。有人捧著蛋糕進門，幾個男人大聲唱歌，桌上杯盤相撞，竟不覺比海浪還吵。壽星一時高興，當眾說要請全場再喝一輪。居萬正要答應，彩雲從旁提醒，包廂的酒原已算足，再加便得另結。周先生笑她小氣，說這樣的日子誰還算錢。彩雲答：「正因日子難得，才不能讓好事變成欠款。」壽星聽了不快，說這家店做生意不夠爽快。居萬臉上掛不住，忙說今日的酒由自己招待。彩雲沒有反對，只在帳本上明明白白寫下「王先生自請」，請居萬簽名。他看了一眼，覺得妻子在眾人前刻意叫他難看，卻仍寫了。旁邊的阿綺趕忙添酒，免得場面冷掉。隔著紅色燈罩，她看見兩個掌櫃各有各的難堪，心裡忽而覺得，夜裡做生意最大的花費，也許不是酒，而是每個人都想維持的好看。散宴後有人醉倒在門口，家人來接時皺眉抱怨，問怎麼讓他喝到這樣。居萬連聲道歉，還替那人攔車。等車子走了，他才把外套往肩上一甩，說今晚真是忙得值。彩雲問值在哪裡，他一怔，過了一會兒說人家過得高興。她問：「那你高興嗎？」他竟答不出。店裡還有桌椅等著搬，杯子等著洗，姑娘們站了一晚，腳都腫了。居萬望見那一地狼藉，第一次感到自己一心維持的熱鬧，原來是把疲累分給了許多人。那夜他留下來同夥計一起刷地，手很笨拙，一桶水翻了半桶。月琴忍著笑教他怎樣擰抹布，說掌櫃今日要當學徒。居萬也笑，說原來最難的是這門功夫。彩雲從廚房端來熱茶，沒說他早該如此。她明白一個人偶爾做好事，固然值得看見，卻不必因此就忘了他前頭做錯的事。旁人總想替他們夫妻選邊，她卻只想明日仍能好好過日子。"}],"running":"第二十三回｜一席酒的價錢","section":"第五部｜兩種價錢"},{"pdf":72,"blocks":[{"type":"p","text":"屋裡安靜下來。有人以為夫妻吵架都要摔東西；他們最不和的一段時候，反倒連飯碗也不肯碰響。隔壁人家聽見的，常是王先生在外頭的笑聲，誰也想不到他一回家，便有那麼多話說不出來。"},{"type":"chapter","text":"第二十四回｜孩子也會替大人撒謊"},{"type":"p","text":"有一回老師問曉芬，父親做什麼。班上孩子爭著答，有人說父親開車，有人說賣魚，有人說在外地當兵。曉芬想了想，只說父親做生意。這話是真的，卻又像留了一半在口袋裡。她第一次明白，同一句實話也能用來避開別人的問題。"},{"type":"p","text":"放學回家，她問母親為什麼有人笑酒店。彩雲手上正剝一條魚，停了片刻，答：「因為有些人沒有去過，也愛替別人的地方取名字。」曉芬又問，那些笑的人是不是壞人。彩雲說未必，嘴巴快的人不一定心壞，心壞的人也未必多話。"},{"type":"p","text":"俊明不理這些。他喜歡跟在父親後面，看他把客人哄得眉開眼笑；美玲則更留意母親晚上幾點關燈。三個孩子在同一間屋子長大，記住的卻像三座不同的島。大人以為孩子不懂，孩子常常懂得比大人希望的更多，只是還找不到字說出來。"},{"type":"p","text":"有日居萬答應帶他們出門，臨時被人請去談事。曉芬說沒關係，像模仿大人的口吻；俊明生氣，將鞋踢到門邊；美玲拿著髮夾，站在鏡前不動。彩雲看著他們，一時竟不知道先勸哪個。最後她自己帶孩子去買點心。回程時，三人都不說話，路上只剩紙袋摩擦的聲音。"}],"running":"第二十四回｜孩子也會替大人撒謊","section":"第五部｜兩種價錢"},{"pdf":73,"blocks":[{"type":"p","text":"居萬夜裡歸來，將幾枚糖果放在桌上，笑問孩子們高不高興。沒人回答。彩雲便將糖果收好，說明日再吃。居萬心裡不解：從前一包糖能讓孩子笑，怎麼忽然不靈？他不知道孩子長大，是從某一天開始學會：被人失約的難過，不一定能拿另一樣東西換回來。"},{"type":"p","text":"孩子第一次替大人撒謊，通常不知道那叫撒謊。曉芬有一回被鄰居問父親是不是又在店裡過夜，她想起母親早晨沒有睡好的臉色，忽然說：「沒有，他昨日早回來了。」話出口才發現，原來一句不真實的話也可以說得這麼自然。鄰居笑笑，沒追問，她的耳根卻熱了半日。"},{"type":"p","text":"回家後她試探著問母親，怎麼有些事情不能讓別人知道。彩雲在淘米，米水一遍遍變白，說：「也不是不能知道。是有人知道了，便要拿去當他自己的故事講。」曉芬低頭想了想，又問：「那我要怎麼知道誰該聽？」彩雲沒有立刻答，將水倒盡才說：「妳長大了，會慢慢看。只不要因為怕別人講，就把自己也騙了。」"},{"type":"p","text":"俊明恰好聽見，笑姊姊愛想東想西。他說若有人問自己，乾脆大聲說不關你的事。彩雲說那也未必好，有些事硬碰硬，只會引來更多人。俊明不服，問究竟該怎樣。母親說：「你看清是誰，再決定怎麼說。」這答案對孩子太不痛快；他們喜歡世界像遊戲，有一條人人適用的規矩。彩雲偏知道世間多的是不公平的棋局，有人連落子的地方都不能自己選。"},{"type":"p","text":"曉芬第一次替大人撒謊，是因為老師問得太認真。老師並沒有惡意，只是想知道學生的家庭，方便日後照顧。她卻隱約覺得，有些事情在家裡講得很熱鬧，到了學校便不一定該講。她選了一個最不容易引人追問的答案，老師點點頭，筆尖從名冊移到下一行。曉芬鬆一口氣，回家卻悶悶不"}],"running":"第二十四回｜孩子也會替大人撒謊","section":"第五部｜兩種價錢"},{"pdf":74,"blocks":[{"type":"p","text":"樂。她原來以為說謊要先想出一大段故事，哪知只需少講半句，旁人便能自動替你把剩下的補齊。那天晚飯她吃得慢，俊明搶走最後一塊肉，她竟沒跟他吵。彩雲看出了不對，問她在學校是否受了委屈。曉芬先搖頭，過一會兒才把老師問話的事說了。母親聽完，沒有責備，只問：「妳為何覺得不能直說？」她說怕別人笑，怕同學回家又講給大人聽。彩雲替她添飯，想了很久才說：「妳不用替大人的事負責。但有些事不想講，也可以說我不想講，不必替我們編好聽的。」俊明聽見，插嘴說若是他，誰問就大聲講給誰聽，叫人不敢笑。美玲說那會惹更多人看。三個孩子互不相讓，父親卻在門外聽得清清楚楚。他進屋後故意講了個笑話，說自己生意做得那麼好，老師該請他去教數學。孩子們笑了，彩雲沒笑。待孩子睡後，她問居萬究竟知不知道女兒為什麼難堪。他說知道，是別人嘴碎。她答：「也有我們自己沒有講清楚的事。」居萬沉默許久，竟也沒有再說自己全無錯處。隔日他去接曉芬放學，沿路不再向每個熟人打招呼，只把她的書包提在手裡。女兒覺得奇怪，問他為何不說話。他答今日想聽妳講。曉芬一開始沒話，後來從學校的粉筆講到一位同學的鉛筆盒，講得口乾舌燥。父親聽得很專心，彷彿這些小事比酒店任何一桌熱鬧都難得。她那晚才發現，原來最會講話的父親，也有肯當聽眾的時候。"},{"type":"p","text":"晚飯居萬講起外頭趣聞，三個孩子仍笑得高興。曉芬忽然覺得父親的熱鬧很好，也很難。讓人高興的是他的本事，叫人替他圓謊的有時也是那份本事。她悄悄把這兩件事放在同一個心裡，沒有替父親挑一邊。往後輪到她自己做決定時，這種猶豫既會保護她，也可能叫她錯失機會。"}],"running":"第二十四回｜孩子也會替大人撒謊","section":"第五部｜兩種價錢"},{"pdf":75,"blocks":[{"type":"p","text":"校門口出了事的那天下午，曉芬比平常早了半個時辰回家。她把書包扔進椅子，說肚子痛。彩雲摸她額頭，不熱，又問是不是午餐吃壞了。她搖頭。問到第三遍，她忽然哭起來，哭聲大得俊明從屋外跑進來。"},{"type":"p","text":"班上有個男生把一張紙條貼在她背後，紙上寫「她爸爸專門請女人喝酒」。她走過半條走廊，幾個孩子跟在後面笑；老師進教室時還問她為什麼不坐好。她把紙條撕了，卻沒捨得丟，捏成一團帶回來。"},{"type":"p","text":"居萬那日正巧在家。看見紙條，臉先漲紅，接著拍桌說明天就去學校找老師。曉芬喊不要。他說哪有人給人欺負還不敢出聲，說著拿了外套就要出門。"},{"type":"p","text":"「你現在去，就是讓大家都知道！」曉芬攔在門口。"},{"type":"p","text":"「知道就知道，妳爸又不是做見不得人的事。」"},{"type":"p","text":"曉芬張著嘴，像挨了一下。她原想說酒店裡本來就有許多姐姐，她們也沒什麼不好。可父親講得那樣理直氣壯，她心裡那點羞恥竟連解釋的地方都沒有了。"},{"type":"p","text":"彩雲把居萬拉住。居萬甩開她，說這事不能不管。她火起，說要管就先管自家的孩子，把孩子哭成這樣的不是哪一家老師。居萬反問她是不是也嫌自己的生意丟臉。她愣住，說我又不是這個意思。他大笑兩聲，將外套摔回床上。"},{"type":"p","text":"第二天曉芬到校，發現那男生挨老師罵了。原來昨晚居萬到底還是託熟人去學校說情。孩子們這下更熱鬧，說她家有本事，動不動就找大人。"}],"running":"第二十四回｜孩子也會替大人撒謊","section":"第五部｜兩種價錢"},{"pdf":76,"blocks":[{"type":"p","text":"曉芬一整天不講話，回家後將父親送她的一枚髮夾從抽屜取出，偷偷塞進俊明的玩具箱。"},{"type":"p","text":"過了兩星期，居萬問她髮夾怎麼不戴。她說弄丟了。他哼了一聲，說小孩子就是不惜物。俊明在旁聽見，想說那髮夾分明在自己的玩具裡，曉芬狠狠踩了他一腳。他大叫起來，氣得要告狀；她也知道自己做得難看，偏就不肯先認。"},{"type":"chapter","text":"第二十五回｜三個孩子的屋子"},{"type":"p","text":"曉芬小的時候，最先學會分辨的是腳步。父親回家，走到門口總要先清一清喉嚨，彷彿進自己家也得先通報；母親從廚房走出來，腳步卻沒有什麼聲音，只看鍋蓋還冒不冒氣。"},{"type":"p","text":"孩子們並不知道大人的世界分成幾間屋。白日裡，父親是笑著遞糖果的人；夜裡，他有時很晚才歸，有時又忽然心血來潮，將一大包零食擱在桌上，說要帶大家出門。俊明最愛這樣的父親，一見有熱鬧便先去找鞋。美玲卻更常站在母親身邊，伸長脖子看桌上的袋子，等人招呼才肯伸手。"},{"type":"p","text":"有一次，三個孩子為了一顆玻璃珠爭吵。曉芬說那是自己的，俊明說昨日明明借過他，美玲年紀小，索性握在掌心，誰也不給。居萬剛從外頭回來，聽得頭痛，說一人買十顆不就好了。"},{"type":"p","text":"彩雲正替衣裳補扣子，頭也不抬：「買得到珠子，買不到公道。」"},{"type":"p","text":"居萬笑她把小事說得像判案，乾脆當場請三個孩子站成一排，挨個問話。俊明搶先說，曉芬不急不徐，美玲見兩個人都說得有理，終於哭起"}],"running":"第二十五回｜三個孩子的屋子","section":"第五部｜兩種價錢"},{"pdf":77,"blocks":[{"type":"p","text":"來。居萬手足無措，先哄小的，再責備大的，片刻功夫便將三種判決都講過一遍。"},{"type":"p","text":"彩雲將針插回針線包，伸手替美玲抹淚，又將玻璃珠放在窗邊：「今晚誰都不玩。明早想清楚再說。」"},{"type":"p","text":"俊明不服，問這樣算誰贏。彩雲說：「沒有人贏。你們一家人吵成這樣，還想有人贏？」"},{"type":"p","text":"居萬站在門邊笑，說她比軍中長官還嚴。他說這話並無惡意，彩雲卻瞥他一眼：「軍中長官下了令，至少知道誰負責。」"},{"type":"p","text":"孩子們當時聽不懂。多年以後，曉芬回想父母，才明白父親與母親並不是一個講理、一個不講理。他們只是把愛放在不同地方：父親以為給得多便是好，母親知道分得清才能長久。兩種好意在同一張桌上相遇，偶爾反倒成了彼此的敵人。"},{"type":"p","text":"同一個家裡，三個孩子對父親的記憶並不一樣。曉芬記得父親偶爾忽然回家，送來一袋點心，又匆匆走掉；俊明記得他在街上被人叫住，人人都說王先生講義氣；美玲卻記得父親有一回答應替她修玩具，三天都沒動手，第四日竟買了更貴的一個來賠。她喜歡新玩具，也氣他沒有記住舊的。孩子的情緒最不肯講道理，拿著禮物笑的那隻手，未必肯立刻放開心裡的委屈。有一年颱風來，窗邊進水，三個孩子把臉盆排成一道牆。俊明自封司令，叫曉芬守左邊、美玲守右邊。美玲偏把盆搬去護自己的紙娃娃，兩人吵得大聲。彩雲一邊拿布塞窗縫，一邊斥他們別鬧。忽然一陣風把門板撞得砰一聲響，三個人都嚇住。曉芬第一個跑去擋，俊明第二個跟上，美玲卻折回去抱起母親擱在椅上的包，裡頭裝著一家人的錢與證件。"}],"running":"第二十五回｜三個孩子的屋子","section":"第五部｜兩種價錢"},{"pdf":78,"blocks":[{"type":"p","text":"事後彩雲誇他們都有用，孩子卻各自認定自己做得最多。多年後一場更大的風波進屋，三個人也照樣各做各的。曉芬先顧弟妹，俊明急著出去找人幫忙，美玲記得一個被大人忘在桌上的小物。旁人要他們把往事講得一致，卻不懂一個孩子當時站在哪裡，決定了他看見的是門、是窗，還是大人突然變掉的臉色。那年颱風過後，居萬回家看見滿地的水，忙稱讚孩子勇敢，又買來好幾包糖。彩雲問他怎麼不先幫著把棉被曬起來，他說不是有人都處理好了嗎。這話叫她一時沒忍住，當著孩子發了脾氣。居萬也發作，說自己在外頭辛苦，回家還要受責。三個孩子站在廊下，聽見父母吵得那麼真，忽然都不敢再去拿糖。大人後來和好了，孩子卻未必知道從哪一刻算起那場爭執已經結束。"},{"type":"p","text":"屋外的風拍著窗，玻璃珠留在窗邊，一整夜沒有滾動。第二天一早，美玲先醒，把珠子放回姊姊的書包，沒有告訴任何人。這件小事過了許多年，也沒有人知道她究竟是認錯，還是終於覺得一顆珠子不值得三個人傷心。"}],"running":"第二十五回｜三個孩子的屋子","section":"第五部｜兩種價錢"},{"pdf":79,"blocks":[{"type":"part","text":"第六部｜門裡生變"},{"type":"chapter","text":"第二十六回｜一雙小鞋三種脾氣"},{"type":"p","text":"家裡有一雙鞋，先是曉芬穿，尺寸小了便收進櫃子，再拿出來時原想給俊明，卻被他嫌顏色不好。他說男孩子怎能穿姐姐穿過的鞋，彩雲說鞋穿在腳上，哪裡認得男女。兩人爭了半日，美玲坐在旁邊，忽然說她願意穿。那鞋其實也不合她腳，卻因她開了口，家裡竟暫且安靜。"},{"type":"p","text":"彩雲後來想起這事，最掛心的不是鞋，是三個孩子的心思。曉芬凡事先替人想，所以有時也把自己的委屈收得太好；俊明不肯吃虧，吵起來最像父親；美玲擅長看大人臉色，知道何時說一句話能使一家人免於繼續生氣。這些本領若放對地方，可以叫人走得遠；若放錯地方，也可以叫人受一輩子的累。"},{"type":"p","text":"居萬聽她說起，笑道小孩子哪有這麼多道理。彩雲說不信便罷，總有一日你會看見。居萬不喜歡被人預言自己會後悔，當下笑著把話岔開，帶孩子出門買新鞋。俊明高興得忘了先前的爭執，曉芬仍把舊鞋擦淨，美玲則悄悄看母親的臉，想知道這次算不算事情已經過去。"},{"type":"p","text":"巷口鞋攤的老闆娘說，鞋要留一點空間，腳才長得舒服。彩雲一聽，心裡竟有些酸。大人替孩子安排路，常以為安排得越細越好；卻不想孩子的腳要長，鞋便不能永遠同樣大。"},{"type":"p","text":"幾十年後，這三個人各自走上不同的路。回頭追尋起點時，誰也不會先想到一雙舊鞋。然而小說可以替他們記住：各自的本性不是某一天憑空長成的，它很早便藏在家中一件無人重視的小事裡。"}],"running":"第二十六回｜一雙小鞋三種脾氣","section":"第六部｜門裡生變"},{"pdf":80,"blocks":[{"type":"p","text":"三個孩子有一回同穿過一雙不大合腳的鞋。並不是家裡只買得起那一雙，而是有人從親戚處帶來一雙漂亮的皮鞋，說誰試了合適便送誰。曉芬先讓弟妹試，俊明嫌扣子麻煩，美玲卻喜歡鞋面上那一點細亮的花紋，明明鞋跟鬆，仍說很合腳。彩雲叫她走兩步，鞋子一晃，差點跌倒。小姑娘氣得眼眶發紅，說自己已經長大了。"},{"type":"p","text":"居萬在旁笑：「喜歡就留著，長大總有一天穿得上。」彩雲道：「鞋子放久了未必還好，腳也不會照鞋樣長。」丈夫說她連一雙鞋都要講道理，她不理，蹲下替美玲把鞋脫下來。她看見孩子用力攥著鞋帶，忽然有點不忍。人生有些願望並不是荒唐，只是眼下不合腳；若勉強穿出去，疼的也不是勸說的人。"},{"type":"p","text":"幾天後俊明偷把鞋拿去外頭炫耀，回來時鞋面蹭掉一點光。他怕被罵，躲在門外半晌。曉芬見了便拿布替他擦，一面責備他不守規矩，一面又叫他別太慌張。美玲看見後喊說這雙本來是自己的，三人於是又吵。居萬想拿錢買三雙新的了事，被彩雲一句話擋住：「鞋有價錢，答應過的事也有。」"},{"type":"p","text":"一雙舊鞋輪到俊明，他寧可赤腳也不肯穿。居萬氣得說從前兵營裡哪有這許多講究，鞋能走路便是好鞋。俊明不答，扭頭往外跑。彩雲將鞋收起，沒有追。他回來時腳底被石頭磨破，紅著眼說自己也不會穿那雙。母親坐在小凳上替他清理，問究竟嫌什麼。他過了好一會兒才說，同學會笑他穿姊姊的鞋。她停下手，明白孩子不過想要一件能稱作自己的東西。翌日她帶三個孩子到市場，說今日人人只能挑一樣，不得超過手中那點錢。曉芬看了許久，挑了本空白簿；俊明買了一雙簡單的布鞋；美玲卻握著錢不花，回程說要留到真的喜歡什麼時再買。彩雲沒勉強。她原以為三個孩"}],"running":"第二十六回｜一雙小鞋三種脾氣","section":"第六部｜門裡生變"},{"pdf":81,"blocks":[{"type":"p","text":"子同屋長大，所求的東西不至於相差太遠，那天才明白，每個人對「夠」字都有自己的解法。居萬見俊明得了新鞋，故意問舊鞋哪裡去了，說丟掉太可惜。孩子一聽急了，以為父親又要他穿。居萬卻拿舊鞋去找修鞋師傅，將磨破的底補好，說放著備用也好。俊明望著父親，第一次沒有反駁。他原先認定父親只會講大道理，沒想到有時也會替一雙不受歡迎的鞋費心。父子難得並肩走一段路，兩人都不知道怎樣說好聽話，只談街上哪裡積水。多年後一位叫樹林的親族熟人從事鞋業，曉芬偶爾想起那雙布鞋，覺得奇妙：有人把鞋當作孩子的面子，有人當作腳下的保障，有人竟能把它做成一門生意。家族裡每一個被認為無關緊要的小物，說不定都藏著另一個人一輩子的起點。"},{"type":"p","text":"最後他們沒有分出誰真正擁有那雙鞋。曉芬把鞋收到高處，俊明覺得受了冤枉，美玲過幾日也不再吵。少年人的委屈看似微不足道，長大後卻可能變成對親密關係最初的理解：有人習慣讓，有人習慣爭，有人總以為只要把錢拿出來，事情就能重新算過。"},{"type":"chapter","text":"第二十七回｜門裡門外"},{"type":"p","text":"海島上的人家很少真正關得住門。街坊拿著一碗湯走進來，借錢的人有事沒事來坐一會兒，隔壁嬸婆瞧見誰家燈亮到半夜，第二天便知道昨晚主人沒睡。這樣的地方，傳聞走得比腳快，真相卻常常連鞋也沒穿好。"},{"type":"p","text":"春潮的買賣有起有落，居萬外頭的應酬始終沒有少。他喜歡被人恭維，喜歡女人向他討教難題，也喜歡把一樁原本平淡的談話說成全屋人都有趣的事。彩雲不怕他會說，她怕的是他說過以後，常常忘記自己說過什麼。"}],"running":"第二十七回｜門裡門外","section":"第六部｜門裡生變"},{"pdf":82,"blocks":[{"type":"p","text":"有人來告訴彩雲，王先生近來常與一位女子往來。那人話說一半，眼睛便停在彩雲臉上，等著看她變色。彩雲正在削一顆梨，皮削得長長一條，沒有斷。"},{"type":"p","text":"「你親眼看見？」她問。"},{"type":"p","text":"那人咳一聲：「大家都這樣講。」"},{"type":"p","text":"「大家是哪一家？」"},{"type":"p","text":"對方答不上來，只得打個哈哈離去。彩雲把梨切好，自己吃了一片，才把刀洗淨。她並非不在乎，只是多年下來明白了一件事：旁人來報信，有時為她好，有時為自己好。她若隨每一句話起舞，跳到後來連自己站在哪裡都不知道。"},{"type":"p","text":"當夜，居萬回來得遲。彩雲問過孩子的功課，替美玲蓋好被子，才從桌上拿起那半顆梨。"},{"type":"p","text":"「你有沒有事情忘了跟我說？」"},{"type":"p","text":"「店裡的帳？」"},{"type":"p","text":"「不是帳。」"},{"type":"p","text":"居萬看她，想起午後有人在街上對自己多笑了兩聲，又想起幾句其實不必講的話。他本可以坦白一點，可越想把事情說輕，話越顯得含混。"},{"type":"p","text":"「人家不過來坐坐。」"},{"type":"p","text":"「哪一家？」"}],"running":"第二十七回｜門裡門外","section":"第六部｜門裡生變"},{"pdf":83,"blocks":[{"type":"p","text":"「妳又聽誰講？」"},{"type":"p","text":"彩雲把梨放下，聲音仍平平的：「我問你的事，你卻先問誰告訴我。你若真沒什麼，就不要怕我知道。」"},{"type":"p","text":"他不肯承認，這世上最容易說出口的謊話，往往是被問起時那一句"},{"type":"p","text":"「又聽誰講」。"},{"type":"p","text":"和平島這一帶，隔壁家的事很難真正隔壁。清早誰家鍋裡燉肉，午後誰家孩子挨罵，夜裡哪戶燈亮得太久，街坊都能從半扇窗猜出八九分。彩雲平日最怕有人故作關心，端來一鍋湯，先問孩子好不好，再慢慢把話引到居萬身上。她並不把這些人一概看成惡意。有些婦人自己一輩子沒人認真聽過她說話，便把探聽別人的生活當作與世界往來的法子。但知道歸知道，她仍不願把家裡的鑰匙交給任何一張熱心的嘴。某日下午，隔壁嬸婆帶著一包米粉來，說近日見居萬忙，怕彩雲顧不來。彩雲道謝，正要送客，嬸婆忽然低聲問：「聽說最近有個女人常在店裡等？」彩雲看著她，先問誰說的。嬸婆連連擺手，說只是為她好。彩雲把米粉推回去一半，笑道：「妳若真為我好，今日就先同我談米粉怎麼炒。」嬸婆臉紅，走時還說一句這人脾氣真硬。待門關上，彩雲才把手上的茶杯放穩，發現指尖竟有些發抖。傍晚曉芬放學，見母親把那包米粉拆了又綁，便問是不是不好吃。彩雲說還沒煮，哪知道。女兒說那明日煮給我們吃。她點頭，暗自苦笑：女人白日裡需要應付半條街的試探，夜裡卻還得回答孩子晚餐想吃什麼。若把這叫作堅強，實在說得太好聽。她不過是沒有餘裕，讓自己在每一個傳言面前都倒下。當晚居萬回家，說最近有人故意在外頭講壞話，不要理會。彩雲問他，那些話有哪一句是不必理的，哪一句是你應當說清楚的。他一時答不出，只說別為了旁人吵架。彩雲望著他，忽然覺得兩人像"}],"running":"第二十七回｜門裡門外","section":"第六部｜門裡生變"},{"pdf":84,"blocks":[{"type":"p","text":"站在一扇門的兩面：他急著關門，想叫世界停在外頭；她卻知道已經有人走進屋裡，再大的門栓也攔不住。"},{"type":"p","text":"居萬久久沒有接話。窗外有人騎腳踏車經過，鈴聲短短一響。他忽然想起年輕時彩雲說他那張嘴不夠分。當年以為是挑逗，隔了多年才發現那原來是一句預言。"},{"type":"chapter","text":"第二十八回｜門口的陌生鞋"},{"type":"p","text":"紙袋在春潮後門放了三天。"},{"type":"p","text":"第一天，居萬說是客人落下的；第二天，說會有人來取；到第三天彩雲拆開一看，只有一條深色圍巾和兩張戲票。票根已撕，戲散了不知多久。居萬見她拿著袋子，臉色立刻不好。"},{"type":"p","text":"「妳翻人東西做什麼？」"},{"type":"p","text":"彩雲把圍巾塞回去。「擺在家裡的東西，我還不能碰？」"},{"type":"p","text":"「這是店。」"},{"type":"p","text":"「好，是你的店。」"},{"type":"p","text":"她將袋子擱在櫃上，力氣大了些，裡頭的戲票滑出來。居萬彎腰去撿，彩雲看著他的後頸，突然很想把那包東西整個丟進水溝。念頭才起，她自己先吃了一驚。"},{"type":"p","text":"那夜居萬沒有回家吃飯。曉芬睡前問：「爸爸去哪裡？」彩雲說店裡忙。孩子說父親昨天也忙，前天也忙。她扯平床單，說睡覺。"}],"running":"第二十八回｜門口的陌生鞋","section":"第六部｜門裡生變"},{"pdf":85,"blocks":[{"type":"p","text":"隔日下午，一陣急促的敲門聲把她從灶前叫出來。"},{"type":"p","text":"門外站著個年輕女人，裙擺濺了泥，腳邊有一雙濕鞋印。她不說姓名，只問王先生在不在。彩雲說不在。女人仰頭看了看門牌，像要確定自己沒有走錯。"},{"type":"p","text":"「我知道妳是誰。」女人說。"},{"type":"p","text":"彩雲握著門栓，忽然覺得好笑。「那妳也該知道，這是我家。」"},{"type":"p","text":"屋內曉芬叫母親，說飯快焦了。彩雲回了一聲，眼睛沒有離開那女人。對方衣袖裡露出一截淋濕的圍巾，顏色同紙袋裡那條一模一樣。"},{"type":"p","text":"「我不找他。」女人往前一步，聲音發顫，「我來找妳。」"},{"type":"p","text":"彩雲不知道這算一聲請求還是一句威脅。她最先想到的竟是灶上的鍋。她想關火，又怕轉過身來時那人已經進屋；想把門關上，那女人卻靠著牆，像已沒有力氣站住。"},{"type":"p","text":"她側身讓出半條路。"},{"type":"p","text":"女人走進來，鞋底的水在地上印出兩道痕跡。曉芬蹲下去看，伸手要摸，彩雲說：「不要碰。」孩子嚇得坐回腳跟。"},{"type":"p","text":"桌邊只有兩張椅子。彩雲看了看，一時竟想不起第三張平日放在哪裡。"}],"running":"第二十八回｜門口的陌生鞋","section":"第六部｜門裡生變"},{"pdf":86,"blocks":[{"type":"chapter","text":"第二十九回｜有客上門"},{"type":"p","text":"女人坐下，卻一直沒脫外套。彩雲端水來時，她兩隻手伸出去接，杯底碰著碟子，響得尖。彩雲把水放穩，正要坐，女人問：「他是不是說過要搬走？」"},{"type":"p","text":"「誰？」"},{"type":"p","text":"「妳知道我說誰。」"},{"type":"p","text":"彩雲望著她濕透的袖口。「妳先把話講清楚。」"},{"type":"p","text":"女人說她等過多少個晚上，居萬答應過什麼，又怎樣一次次沒去。話說到半途，忽然跳到一樁毫不相干的事：有一回她病了，打電話去店裡，接的人叫她晚點再打。她記得那人的口氣，模仿給彩雲聽，模仿得太像，竟自己笑起來。笑了兩聲，又哭。"},{"type":"p","text":"彩雲本來準備了一肚子的質問；到了這時，只覺得口乾。她想問那些承諾是真是假，卻不願在這個女人面前承認，自己竟也想知道丈夫對別人能說出什麼好聽話。"},{"type":"p","text":"「他沒同我說這些。」她答。"},{"type":"p","text":"「他當然不說。」女人把杯子推遠，水灑出來，「妳有三個孩子。妳什麼都有。」"},{"type":"p","text":"彩雲猛地站起。「妳以為有三個孩子就什麼都有？」"},{"type":"p","text":"曉芬在走廊裡停住。俊明抱著一盒紙牌，正想探頭。彩雲衝他們吼："},{"type":"p","text":"「進去！」"}],"running":"第二十九回｜有客上門","section":"第六部｜門裡生變"},{"pdf":87,"blocks":[{"type":"p","text":"三個孩子都縮回去。她隨即後悔，想叫曉芬過來幫她看弟妹，卻又開不了口。女人低低說了一句對不起，接著又說自己不想再等了。彩雲聽見那語氣變了，往前挪一步。"},{"type":"p","text":"事情忽然失了控制。"},{"type":"p","text":"她看見對方有傷害自己的舉動，便立刻上前阻止，一面朝走廊大喊找大人、叫救護車。桌子被撞歪，杯子落地。曉芬原先不敢動，直到母親再喊一次，才跌跌撞撞地跑向門外。她不記得自己如何叫住鄰居，只記得有個賣魚的叔叔連圍裙也沒解，丟下秤就跟她跑。"},{"type":"p","text":"鄰人趕來協助。有人聯絡救援，有人把院門讓出來，有人照顧孩子。彩雲跪在地上，聲音比她自己聽過的任何一次都急。救護人員抵達後接手，她才退到一旁，發現手腕一直抖，連衣袖也拉不平。"},{"type":"p","text":"救護車開走時，居萬還沒有回來。"},{"type":"p","text":"屋裡靜得出奇。曉芬坐在門檻邊，手裡攥著兩張皺掉的紙牌。彩雲走過來要她進屋。她問：「媽媽，那個阿姨會死嗎？」"},{"type":"p","text":"彩雲張了嘴，什麼也沒答。她聽見隔壁有人開始向路過的人解說剛才發生的事，解說得十分有條理，像他們全程都在場。"},{"type":"p","text":"她忽然衝出門，大聲說：「你們誰都不准再講！」"},{"type":"p","text":"巷口的人一齊回頭。那位賣魚的叔叔伸手想勸，她連他也罵。等吼完才想起剛才是他跑來幫忙，臉一下熱了。她沒有道歉，扭頭回屋，門一推，才發現門根本鎖不起來。"}],"running":"第二十九回｜有客上門","section":"第六部｜門裡生變"},{"pdf":88,"blocks":[{"type":"chapter","text":"第三十回｜誰記得那聲汽笛"},{"type":"p","text":"居萬回家時，飯鍋的焦味還留在廚房。"},{"type":"p","text":"他先看見倒在牆角的椅子，問誰摔了東西。彩雲站在桌邊，半日才說：「人送醫院了。」"},{"type":"p","text":"「哪個人？」"},{"type":"p","text":"她沒有答。居萬走到椅子旁，看見地上那條深色圍巾，伸手便撿。彩雲的眼睛跟著他那隻手。那一刻她甚至忘了怕那女人會不會平安，只想知道：他怎麼一眼就認得？"},{"type":"p","text":"「你拿來做什麼？」她問。"},{"type":"p","text":"「這東西不能放這裡。」"},{"type":"p","text":"「那放哪裡？帶回店裡？還是還給她？」"},{"type":"p","text":"居萬說先別在孩子面前鬧。彩雲笑了一聲，笑得自己都覺得怪。「你現在知道孩子在看了。」"},{"type":"p","text":"曉芬聽見父母的聲音，拉著俊明、美玲躲回房間。俊明說爸爸害的。曉芬說你不要亂講。俊明又說那媽媽為什麼哭？曉芬往門外望。母親沒哭，她只聽見母親像在打碎什麼看不見的東西。"},{"type":"p","text":"「我不知道會這樣。」居萬說。"},{"type":"p","text":"彩雲拿起桌上的戲票，塞到他胸前。「你知道什麼？這張票？那個名字？還是你今天要去哪一家喝酒？」"}],"running":"第三十回｜誰記得那聲汽笛","section":"第六部｜門裡生變"},{"pdf":89,"blocks":[{"type":"p","text":"他去抓票，紙被扯成兩半。居萬怔了怔，忽然發火：「妳就非得把事情弄到大家面前？」"},{"type":"p","text":"彩雲轉身拿起一只瓷碗，往地上摔。聲音響得連隔壁都聽見。她自己先驚住了。那是曉芬常用的飯碗，白邊畫一朵小紅花，昨晚還放著半塊魚。"},{"type":"p","text":"「是我弄的？」她叫起來，「人在我家裡出事，是我弄的？」"},{"type":"p","text":"居萬沒吭聲。他從地上拾起一塊瓷片，沒留神，手指被劃了一道。他看著手上的紅痕，居然想說她摔得也太狠；話到嘴邊又吞下去。"},{"type":"p","text":"彩雲突然說：「你去醫院。」"},{"type":"p","text":"「妳呢？」"},{"type":"p","text":"「我在家。」"},{"type":"p","text":"「妳不跟我去？」"},{"type":"p","text":"她把椅子扶正，朝門口指了指。她怕再多聽一句，就會說出更難聽的話。"},{"type":"p","text":"居萬走到門外，忽然折回來找車鑰匙。曉芬看見父親找了三遍，鑰匙就在鞋櫃上，她偏不提醒。平日她最愛替父親找東西，此時只想他再找久一點。等他終於走了，她卻又盼他早些回來。"},{"type":"p","text":"彩雲蹲下去收拾破碗，曉芬跑出來伸手想幫。母親吼了一聲別碰，孩子停住。過了一陣，她們並排坐在地上，誰也不看誰。"}],"running":"第三十回｜誰記得那聲汽笛","section":"第六部｜門裡生變"},{"pdf":90,"blocks":[{"type":"p","text":"巷口一輛機車開過，排氣聲很響。曉芬抖了一下，問：「是不是救護車又來？」"},{"type":"p","text":"彩雲這才發現，她也還在聽那聲音。"}],"running":"第三十回｜誰記得那聲汽笛","section":"第六部｜門裡生變"},{"pdf":91,"blocks":[{"type":"part","text":"第七部｜燈熄之後"},{"type":"chapter","text":"第三十一回｜救護車走後"},{"type":"p","text":"隔天曉芬帶著沒寫完的作業去學校。她在紙上填了兩行字，又塗掉。老師問誰可以借橡皮擦給後排同學，她把自己的丟過去，丟得太用力，撞上黑板。全班笑了，她也跟著笑，笑到胸口發疼。"},{"type":"p","text":"放學時有個孩子說聽母親講王家昨天很熱鬧。曉芬叫他閉嘴。對方又問真的假的，她上前推了一把。那孩子摔在地上，先發愣，然後哭，老師把兩個人叫回教室。"},{"type":"p","text":"「妳平常很懂事，今天是怎麼回事？」"},{"type":"p","text":"曉芬盯著鞋尖。她本來可以把事情講清楚，也可以說只是吵嘴，偏偏不想給老師看見自己那副可憐模樣，便說：「他自己跌的。」"},{"type":"p","text":"老師看著她，請她明天帶家長來。"},{"type":"p","text":"彩雲去學校時衣袖還沾著昨夜洗不掉的一點污漬。老師講了經過，彩雲先道歉，回頭卻一把抓住曉芬的手腕，抓得孩子皺眉。回家路上她一句話也沒說。走到賣冰的店前，曉芬忽然掙開她。"},{"type":"p","text":"「你昨天叫我不要問，今天老師問我又不能說。那我要怎樣？」"},{"type":"p","text":"彩雲站在街邊，幾輛腳踏車從身旁擦過。她說：「先回家。」"},{"type":"p","text":"「妳也只會說先回家！」"}],"running":"第三十一回｜救護車走後","section":"第七部｜燈熄之後"},{"pdf":92,"blocks":[{"type":"p","text":"孩子說完就跑。彩雲追了兩步，膝蓋一軟，扶著牆才站穩。她恨女兒當街頂嘴，也恨自己昨日叫女兒求援、今日又要她把事情藏起來。她想起早上有鄰居來送粥，自己還將門關在對方面前。那些真正幫過忙的人，她一個也沒好好道謝。"},{"type":"p","text":"居萬夜裡從醫院回來，說已有人照顧那位女子，情況仍需觀察。他想替自己講幾句，又想向彩雲問孩子的事。彩雲說：「她今天在學校打人。」"},{"type":"p","text":"居萬一愣。「曉芬？」"},{"type":"p","text":"「老師要我去。」"},{"type":"p","text":"他半晌才說：「一定是有人笑她。」"},{"type":"p","text":"「有人笑，就能打嗎？」"},{"type":"p","text":"他正想說不能，忽而想起自己在酒店裡為一點面子同客人拍桌，也沒比女兒強多少。他說：「我明天去學校一趟。」"},{"type":"p","text":"「不用。她已道歉了。」"},{"type":"p","text":"「那我要做什麼？」"},{"type":"p","text":"彩雲看他一眼。她原本想叫他出去，越遠越好；這時又怕他當真走了。她把桌上那個少了一只碗的碗架搬到他面前。"},{"type":"p","text":"「把那個補上。」"}],"running":"第三十一回｜救護車走後","section":"第七部｜燈熄之後"},{"pdf":93,"blocks":[{"type":"p","text":"他去找碗，找回一只花樣不同的。曉芬吃飯時盯著看了許久，忽然把它推給父親，說自己不要。居萬硬說一樣好用，她把碗推得更遠，飯灑了一桌。"},{"type":"p","text":"那晚三個人吵到菜冷。俊明躲在門後偷笑，笑著笑著卻哭了；美玲不說話，只趁眾人不留神，把那只新碗洗乾淨，放到自己的位置。"},{"type":"chapter","text":"第三十二回｜一口飯也沒有停"},{"type":"p","text":"自那場危機以後，街坊對王家的招呼分成兩種。熟識的更熱心，彷彿多替他們提一袋菜，便能讓流言消散些；原本不熟的反而格外客氣，說起話來眼睛總多停留一瞬。真正刺人的不是誰當面惡言，而是人們對一件事既好奇，又不願承認自己好奇。"},{"type":"p","text":"彩雲仍然早起。鍋裡有米要煮，孩子有衣要洗，屋裡有帳要算。有人說她真能忍，她卻不願認這個字。忍耐彷彿是一種天賦，好像日常繼續轉動就證明她沒有傷心。她只是知道，若自己今日不煮飯，孩子明日不會因此懂得父母之間究竟出了什麼問題。"},{"type":"p","text":"居萬好幾次想談，見她忙便說改天。彩雲知道「改天」是一個很靈巧的詞，可以讓最嚴重的事同昨日的剩飯一起放進櫃裡。她終於在某夜將桌上東西收好，問他：「你有什麼話，今晚說。」"},{"type":"p","text":"他先說自己並非全然有意，再說事情複雜，最後說最對不起的是孩子。彩雲一一聽完，卻只問：「那你對不起的人，怎麼總要等到事情出了，才輪得到你想起？」"}],"running":"第三十二回｜一口飯也沒有停","section":"第七部｜燈熄之後"},{"pdf":94,"blocks":[{"type":"p","text":"居萬坐了很久。他想反駁，想說自己這些年也為家付出許多，想說開店的人在人情裡難免難做。那些話不見得全錯，卻沒有一句能直接回答她。於是他頭一次老老實實說：「我不知道怎樣答。」"},{"type":"p","text":"彩雲聽了反而把燈調暗。她不因此原諒，也沒有忽然決定離開。她只覺得兩人終於站在一塊沒有藉口的地方，可以開始看清眼前的路有多難。婚姻有時並非重新相愛，而是某一天起終於不再靠話術維持。"},{"type":"p","text":"日子沒有因那場事故自動慢下來。隔日上午有客人要來結帳，米缸要添米，孩子要上課，鄰居家老人病了還得託人帶話。彩雲照常做事，旁人都誇她能忍；可只有她自己知道，忙碌有時不是勇敢，而是不敢一旦停下來，便不曉得要從哪裡重新開始。"},{"type":"p","text":"有位親戚私下叫她另作打算，說女人總得替自己留後路。她沒有反駁，也沒有感動得立刻去做。她問對方：「後路在哪裡？」對方說有娘家、有親友。彩雲點頭，心裡卻很清楚，有路不等於能走，能走不等於走了便沒有新的難題。三個孩子都還小，家裡的帳本與人情又處處纏著，她不願讓別人以為一句離開或留下，便能替她解決全部人生。"},{"type":"p","text":"居萬漸漸有了些改變。他有幾晚提早回家，先去查看孩子睡了沒有，甚至學著替小的修書包扣子。俊明覺得新奇，問父親是不是外頭生意不好。這一句天真話叫居萬既想笑又難過，原來自己多年不在場，孩子竟把回家當成生意受挫的徵兆。他忍住自嘲，說：「我想陪你們。」俊明不曉得怎樣答，只把書包遞給他。父子兩人一時找不到更多話，便一同研究那顆壞掉的扣子。"}],"running":"第三十二回｜一口飯也沒有停","section":"第七部｜燈熄之後"},{"pdf":95,"blocks":[{"type":"p","text":"危機過後，家裡恢復了每天吃飯、洗衣、上學的節奏。旁人見他們照常過日子，便以為事情也就這樣算了。彩雲卻知道，一家人有時不是因為心裡平靜才按時吃飯，而是若不先把飯端上桌，連難過也要餓著肚子。她發現自己最難忍受的是夜裡收完碗，屋中忽然安靜的那一刻。所有該做的事做完，人才有空想起未曾解決的事。俊明開始變得好鬥，誰在學校拿父親的事打趣，他便衝上前去理論。曉芬被老師叫去問發生什麼，她不願說弟弟無理，也不願把家事攤開，只答同學開了不恰當的玩笑。老師勸她要讓弟弟控制脾氣。她點頭，心裡卻第一次想問：為何孩子要負責把大人的故事講得體面，連替自己生氣也像不懂事？美玲的改變最安靜。她開始把玩具一件件放得整整齊齊，飯後搶著擦桌，怕只要有一處不乾淨，屋裡便又會有人爭吵。彩雲看見，故意把一只杯子留在桌上，叫她先去睡。孩子不肯，說明天早上會有人看見。彩雲握住她的手，說杯子明早還在，今晚不用妳管。美玲像聽不懂，一會兒才慢慢放開抹布。某個星期日，居萬帶孩子們去海邊走。海風大，三個人跑來跑去，唯獨曉芬站在防波堤旁問父親，人是不是會因為做錯事就變成壞人。居萬想了很久，竟答說他不知道。曉芬瞪大眼，以為父親無所不知。他又說：「人可以做錯很多事。知道錯在哪裡，還得看往後怎麼做。」這話不算高明，卻比他先前任何急著辯解的句子都沉。曉芬後來回想起來，發現自己最早理解人的矛盾，並不是讀哪一本書，而是從父親第一次坦白說不知道開始。"},{"type":"p","text":"彩雲站在門旁看著，並沒有因而認定丈夫從此改好了。她年輕時愛過那個會說話的男人，婚後又見過他許多沉默與軟弱；若一夜可把一個人完全改變，世上便沒有那麼多過不完的日子。她只願意把眼前肯做的事先記下來，不替未來預付讚賞。這是她懂得愛，也懂得保護自己的方式。"}],"running":"第三十二回｜一口飯也沒有停","section":"第七部｜燈熄之後"},{"pdf":96,"blocks":[{"type":"chapter","text":"第三十三回｜春潮落時"},{"type":"p","text":"酒店關門不是在一夜之間。沒有雷聲，也沒有誰拿著公文站在門口，宣布一個人的風流日子就此結束。只是客人逐漸換了面孔，帳本的數字慢慢失了準頭，最早來的那幾個女人也開始有別的打算。"},{"type":"p","text":"阿綺說她想離開。居萬起初不信，說外頭哪有這樣好賺的工錢。阿綺答：「好不好賺，我出去才知道。至少人家問我做什麼，我不用先想怎樣回答。」"},{"type":"p","text":"麗華替她收拾箱子，將那只磨損的暖水瓶塞到衣裳底下。阿綺看見，鼻子一酸，偏要笑著說：「帶著這個，倒像我以後再也買不起新的。」"},{"type":"p","text":"「留著吧，天冷總要喝水。」"},{"type":"p","text":"她們抱了一下，不太久，因為店裡還有人等著結帳。"},{"type":"p","text":"居萬在門後看著，心裡生出一股說不清的失落。他原以為自己是這間店的主人，每一個進來的人都沾了自己的光；如今有人要走，他卻連一句像樣的祝福都說不出來。他最終塞給阿綺一個紅封，囑她往後別輕信男人。"},{"type":"p","text":"阿綺收下，回頭道：「王老闆，這句話你若早些學會，可能省下不少事。」"},{"type":"p","text":"她說完便走了。居萬沒生氣，竟還笑了笑。他知道那姑娘把他看得太清楚，清楚得不肯再替他留面子。"}],"running":"第三十三回｜春潮落時","section":"第七部｜燈熄之後"},{"pdf":97,"blocks":[{"type":"p","text":"春潮的生意轉淡以後，最先抱怨的不是居萬，而是原先坐在店裡談笑最響的一群人。他們來得少了，卻還愛隔幾天跑來問怎麼沒有從前熱鬧，彷彿店裡的燈和女人、酒與音樂，全得等他們一句話才有存在的價值。居萬表面照樣客氣，回頭卻常望著幾排空椅，猜自己究竟從哪一晚起失了吸引人的本領。月琴有一回算完工錢，說打算轉做白天的工作。居萬留她，說老客人都喜歡她唱歌。月琴答老客人喜歡的，未必能養她一輩子。這句話說得平常，居萬卻聽出一份不肯再等他安排的決心。他問若外頭不好，還回不回來。月琴笑了一聲，說人總得先出去才知道。她向彩雲道別時，彩雲沒有挽留，只把該結的帳一筆筆算清，另外塞了一包路上吃的糕點。某晚一位相識多年的客人來，只點了一壺茶，坐在空蕩的包廂，說昔日聚會的人如今各有去處。居萬問何不再約，對方說有些人搬家，有些人病了，也有人從前有錢，現在不願出門見舊友。兩個男人隔桌坐著，難得沒有吹噓，忽覺紅燈照在臉上，比自然的天光更顯老。客人起身前說：「你這裡我還是會來。只是別再替我留那麼大的桌了。」居萬送他出門，望見滿街新舊招牌，竟想不起自己究竟守著什麼。彩雲提出關掉幾間少用的包廂，把人手調整好，免得虧欠員工。居萬聽見「關」字便覺刺耳，說春潮只要再撐一陣，風向總會回來。她沒有當即反對，只給他看連續三個月的帳。紙上沒有一句難聽話，數字卻比誰都不留情。他一張張翻過去，終於問：「若真的關了，我還算什麼人？」彩雲望著他，答：「你先做一個肯回家的人。別的，慢慢再算。」"},{"type":"p","text":"春潮最後一夜，麗華親自收完帳。她將兩本帳冊疊好，說一冊是人家欠的，一冊是該給人家的。居萬伸手要拿，她卻把第二冊按住：「先算這本。」"}],"running":"第三十三回｜春潮落時","section":"第七部｜燈熄之後"},{"pdf":98,"blocks":[{"type":"p","text":"有人來收桌，有人把燈一盞盞熄下去。門外的街沒有因此變得寂寞，隔壁仍有人做生意，遠處仍有招牌亮著。居萬忽然明白，夜的熱鬧並不是他創造的；他只不過在某一段時間裡，借了城市的一些光。"},{"type":"p","text":"居萬拎著兩本帳走回家，發現彩雲尚未睡。她瞧他手裡的東西，沒有說終於，也沒有問虧了多少。"},{"type":"p","text":"「吃飯了嗎？」"},{"type":"p","text":"他搖頭。"},{"type":"p","text":"她轉身把灶火點起來。那一刻他才知道，家裡的一盞小燈，比一整排紅色燈泡更難守住。"},{"type":"chapter","text":"第三十四回｜最後一次點燈"},{"type":"p","text":"店要關時，沒有人願意先說「關」字。居萬說只是歇一陣子，麗華說她正好有別的安排，月琴說在外頭找到了新工作，阿綺卻比大家乾脆，將自己的衣裳一件一件收進皮箱，連掛在椅背上晾的手帕也帶走。"},{"type":"p","text":"她最後一晚照常來，沒有盛裝，也不再用過去那個特意取的笑臉。居萬說等將來生意好轉，隨時歡迎她回來。阿綺笑著謝了，卻不作答。她知道老闆不是惡意，只是習慣將任何離別說得還留有餘地，好像只要門沒親手關上，人便可以永遠來去。"},{"type":"p","text":"麗華在帳簿裡發現一筆長年懸著的應收款，問要不要追。居萬看了名字，沉默片刻，說算了。麗華沒有照做，仍在旁邊寫下一行字：未收。她說：「算了是一回事，記得有過是另一回事。」居萬望著她，忽然想起彩"}],"running":"第三十四回｜最後一次點燈","section":"第七部｜燈熄之後"},{"pdf":99,"blocks":[{"type":"p","text":"雲也常說相似的話。這兩個女人彼此不同，卻都不肯讓一筆事因男人嫌麻煩便自動不見。"},{"type":"p","text":"阿綺臨走前，月琴帶她去海邊看夜景。遠處船燈明明滅滅，城市像一張尚未結清的帳。月琴問她將來最想要什麼，她想了半日，說想有一間房，門上的牌子寫自己的本名。月琴笑她志氣太小。她答：「小才好，太大的志氣，別人總想替你分一杯。」"},{"type":"p","text":"最後一盞燈熄滅時，彩雲正在旁邊整理一把鑰匙。居萬忽然覺得那燈很可惜，像一場熱鬧被人倉促叫停。彩雲看了他一眼：「熱鬧是給客人看的，日子還得自己過。」"},{"type":"p","text":"多年後，街坊談起春潮，總只記得最華麗的幾夜。可對那群靠它生活過的人來說，真正要緊的日子，恰恰是大家各自帶著自己的名字從店門走出去的那一晚。"},{"type":"p","text":"最後一次點燈的那晚，阿綺先到，將桌椅擦好，然後站在休息間，不知該做什麼。往常她一進門便忙著化妝、整理衣襟，今日卻覺得臉上多上一點粉都是多餘。麗華早已去了別處，月琴也有了新的工作，剩下的人三三兩兩進門，先問今日還要不要照舊站位，接著又自己笑了：哪裡還有什麼站位。居萬本想辦一場熱鬧的告別酒，叫舊客人回來看看。他寫了好幾張邀請，寫到一半忽然不想寄。彩雲問他怎麼了，他說怕人來了也只是說些好聽話，走後便忘。彩雲道：「你以前不就是靠那些好聽話，將人留到深夜？」他苦笑，將紙一張張摺起來，放回抽屜。這回他沒有爭辯，像終於知道一場生意最難收拾的不是桌椅，而是自己當初對它懷過的盼望。阿綺收拾好帳簿，把自己的名字寫在最後一頁，請彩雲替她看一遍。彩雲看"}],"running":"第三十四回｜最後一次點燈","section":"第七部｜燈熄之後"},{"pdf":100,"blocks":[{"type":"p","text":"完說數字都對，問她往後去哪裡。她答先到另一個城市學手藝，將來若有機會，想開一間白天亮燈的小店。彩雲笑著祝她如願，居萬在旁邊也說若需要介紹客人，只管來找他。阿綺愣住，接著誠懇地道謝；這一回她知道王先生是真心的，也知道若真要把日子過好，不能只靠他一句介紹。燈一盞盞熄掉，最後留下的是收銀桌上的小燈。居萬走過每間房，見牆上釘痕、地上酒漬、櫃裡遺忘的扇子，忽覺每樣東西都像還有話要說。彩雲在門口等得久了，進來問可好了沒有。他點頭，卻站著不動。她把手伸給他，並不說不要難過。他握住，兩人一道將最後的門關上。街上仍有人買宵夜，汽車照樣駛過。對世界而言，一間店的結束原來不必有半點儀式。"},{"type":"p","text":"回家路上他提著一只沒用完的燈罩，步子比往常慢。街上仍亮，並沒因春潮關門而少一分光。他忽然有些羞愧：過去總以為自己替這條街添了許多熱鬧，到頭來竟是自己借了這條街的熱鬧，才能把青春吹得那麼響。彩雲替他開門，見他捧著燈罩，什麼也沒問。那夜兩人沒有談虧盈，只把廚房最後一盞燈點起來，坐著吃了碗剩飯。"},{"type":"chapter","text":"第三十五回｜和平店早晨"},{"type":"p","text":"和平店開張第一個早晨，居萬把招牌擦了三遍。"},{"type":"p","text":"油漆還沒乾透，牌子上那個「和」字沾了他一截袖口。他罵油漆匠偷工，隨即又想起如今沒人替他處理這些瑣事，只好到後院洗袖子。街對面的魚販看見，隔著路喊：「王老闆又換一行啦？」"},{"type":"p","text":"「換行才有出息。」他答得極快。"}],"running":"第三十五回｜和平店早晨","section":"第七部｜燈熄之後"},{"pdf":101,"blocks":[{"type":"p","text":"十點以前只賣出兩包檳榔。第一個客人付了大鈔，他找不開，還得跑去隔壁借零錢。第二個是舊識，嚷著先賒半包，等發薪再給。居萬本想說好，彩雲在櫃台後咳了一聲，他便裝聽不見。"},{"type":"p","text":"近午時，門口站著個女人，穿素淨的短袖，頭髮紮得利落。居萬一眼認出麗華，手裡的夾子停住了。她提著購物袋，像真的只是路過。"},{"type":"p","text":"「有賣菸嗎？」她問。"},{"type":"p","text":"居萬指了指架子，拿下一包。"},{"type":"p","text":"「這個我以前不抽。」她說。"},{"type":"p","text":"「誰記得妳抽哪一種。」"},{"type":"p","text":"麗華笑了一聲，把錢放下。彩雲正在屋裡洗米，聽見聲音走來，見了麗華，只說：「坐一下？」"},{"type":"p","text":"「不了。」麗華說，「車還在等。」"},{"type":"p","text":"她拿走菸，卻把找零推回。「當年欠我的那一晚工錢，算這裡頭。」"},{"type":"p","text":"居萬臉上立刻有了不快。「妳說什麼？我哪時欠過妳！」"},{"type":"p","text":"「那你就當是我記錯。」"},{"type":"p","text":"她說得很輕，已經走遠。居萬追出一步，隔壁魚販正好問以前怎麼不見過這位小姐，他便把腳收了回來，笑著說是客人。"},{"type":"p","text":"彩雲把米篩放在桌上，問他：「真欠？」"},{"type":"p","text":"「她的帳早結清了。」"}],"running":"第三十五回｜和平店早晨","section":"第七部｜燈熄之後"},{"pdf":102,"blocks":[{"type":"p","text":"「帳本呢？」"},{"type":"p","text":"「酒店早收了，哪裡還有？」"},{"type":"p","text":"彩雲又問了一遍：「真欠？」"},{"type":"p","text":"居萬忽然爆了：「人走都走了，妳非叫我在街上丟臉才高興！」"},{"type":"p","text":"那個下午他不准再賒帳。來了個常在這裡買東西的工人，說錢包丟在家裡，明早拿來。居萬冷著臉說不賒。工人愣了，隔壁魚販湊過來打趣：「以前王先生請人喝一桌酒，現在一包檳榔也要講價。」"},{"type":"p","text":"居萬猛地合上錢箱，說價目清清楚楚，誰也沒有例外。工人不買了。等他走遠，彩雲拿出自己零錢買下一包，叫女兒去送給他。"},{"type":"p","text":"晚上盤帳，居萬發現櫃台裡多出一張五十元。他拿起來問誰放的。彩雲說是麗華。他本來想把錢塞回抽屜，忽然又怕日後看見，於是捏著紙鈔走到門口，想找人換開。街已黑了，魚販在收攤，他仍站在招牌底下。"},{"type":"p","text":"屋裡曉芬在背書，背到一半探頭問父親：「王先生的『王』是哪個王？」"},{"type":"p","text":"居萬說：「三橫一豎的王。」"},{"type":"p","text":"「老師說寫名字要端正。」"},{"type":"p","text":"他望著袖口上那一點擦不掉的油漆，半晌才說：「去睡。明天再背。」"}],"running":"第三十五回｜和平店早晨","section":"第七部｜燈熄之後"},{"pdf":103,"blocks":[{"type":"part","text":"第八部｜鞋與人情"},{"type":"chapter","text":"第三十六回｜和平店的賒帳簿"},{"type":"p","text":"換成檳榔店以後，居萬發現客人與客人之間的距離忽然縮短了。酒店裡，人們為一桌酒留上幾個時辰，彼此說得像交心；檳榔店前，有人停車買一包東西，只用三句話便將家裡出了一場大事說了個明白。前一種熱鬧費錢，後一種熱鬧費心。"},{"type":"p","text":"彩雲看著他又開始替客人賒帳，忍不住說：「你若要全島人都欠你情，先看看櫃裡剩多少。」居萬反問她，碰見真有難處的人，難道一包東西也不肯通融？她說可以通融，可你不能連誰真有難處也懶得辨。"},{"type":"p","text":"有位老客每回買完總坐著不走，愛講早年的軍旅，又愛嘲笑年輕人不肯吃苦。居萬聽得來勁，兩人一搭一唱，從上午說到飯點。那老客走後，來了一個腳踏車後座綁著紙箱的中年女人，買東西時連零錢都數了兩遍。居萬想送她，彩雲從後頭出聲，說先請她喝口水。女人推說不必，卻終究坐下。"},{"type":"p","text":"她喝完水，低聲說男人失了工作，家裡正在找活。居萬一聽，立刻提議去問幾個熟人。彩雲沒有阻止，卻在他把話說滿以前，先問女人需要的是什麼差事、能做哪些事。居萬怔住，終於知道熱心若沒有細問，也可能把人推去更難走的路。"},{"type":"p","text":"那天收店時，他將賒帳簿拿出來，一頁頁翻。許多名字早不知去了哪裡，有幾筆錢從來沒收回，也有一些欠過他的人在別處幫過他的忙。他說這帳算不清。彩雲說：「所以才要記。」"}],"running":"第三十六回｜和平店的賒帳簿","section":"第八部｜鞋與人情"},{"pdf":104,"blocks":[{"type":"p","text":"店門外海風吹來，掀動帳頁。居萬伸手壓住，忽然覺得自己一生最喜歡的其實不是賒帳，而是有人肯來找他。至於被需要是否等於被尊敬，被尊敬是否等於被愛，他從年輕想到老，也仍說不分明。"},{"type":"p","text":"檳榔店的賒帳簿比酒店薄得多，記下來的人卻未必比從前少。隔壁工人先欠兩次，說月底發薪便付；一位老先生每回掏錢總慢半拍，居萬乾脆假裝沒看見；有個年輕人買完東西說下星期要去南部找工，走前特地把積欠的幾十元清了。居萬收下錢，還多送了他一包小零嘴，說路上別餓著。"},{"type":"p","text":"彩雲見他又送東西，說這生意還要不要做。他答：「人家肯還已經不錯。」彩雲說她不是不知人情，只是每個人都這樣讓一點，攤上便沒有多少東西能賣。話說到一半，她忽然發現丈夫將那個年輕人的名字在簿上劃去了。墨水一道，短短的，像替一段鄰里關係畫上暫時的句點。她又有些不忍責備他。"},{"type":"p","text":"多年後那年輕人果真從外地回來，穿著新鞋，一進店便喊王先生。他說自己在外頭受了不少委屈，有次餓得狠，想起當年出門時那包零嘴，竟在路邊哭了一下。居萬忙拿話逗他，說這有什麼好哭，男子漢應該笑。對方笑了，忽然又說：「我那時也不知道，原來有人記得我。」"},{"type":"p","text":"和平店開了一陣，居萬把賒帳的名字寫得愈來愈多。他看重街坊信用，覺得人來買東西總有周轉不靈的時候，能幫一把便幫一把。彩雲不反對，但要求記上日期。居萬嫌麻煩，說老朋友還要日期？她答：「老朋友的日子，也照樣一天一天過。」一位做工的男人有段時日總是欠著，偶爾來店裡，也不敢朝櫃臺看。居萬原想當眾叫住他，問究竟何時還。彩雲將他拉回來，說不如等人少時再問。過了幾日，那男人帶著一袋自家種的菜"}],"running":"第三十六回｜和平店的賒帳簿","section":"第八部｜鞋與人情"},{"pdf":105,"blocks":[{"type":"p","text":"登門，說工錢被拖欠，暫時只能先還這些。居萬一看便說不用，欠的都算了。男人臉色忽然變得難看，說自己不是討施捨。彩雲忙把菜收下，替他在帳上記一筆，說等工錢到手再慢慢算。男人這才放鬆，低頭道謝。居萬事後不懂，自己明明更大方，為何反叫人難堪。彩雲問他若有人見你做生意失敗，當眾說欠的錢全不要了，你會怎樣？居萬想了想，臉色沉下來。他一直以為慷慨是把東西送出去，才發現對方肯不肯收，也是另一回事。那天晚上他把賒帳簿拿出來，看著密密麻麻的姓名，第一次想像那些字背後各有一個不願被輕看的人。又過不久，那工人果然來還了一部分，剩下的說下回再補。居萬接過錢，沒有再說不用，只說有空來坐。工人笑了，答等不忙時一定。彩雲站在後頭，心裡知道這段人情會不會繼續，未必取決於帳簿最後是不是歸零；而在有人困窘時，他仍能以一個完整的人身分來店裡買東西。"},{"type":"p","text":"那人走後，彩雲把帳簿翻到舊頁，看見一個早已劃掉的名字。她用指腹輕輕擦過墨痕，心想做人情的難處便在這裡：許多時候它確實值得，許多時候又偏偏叫人虧。她不能替每一筆都先算出答案，只能在同一個男人身上反覆看見他令人氣惱的優點，以及難以否認的缺點。"},{"type":"chapter","text":"第三十七回｜樹林與眾生"},{"type":"p","text":"和平島有個姓洪的老師傅，補網補得好，脾氣也硬。他同居萬下棋，棋走到一半常吵起來。居萬說下棋要講攻勢，洪師傅說做人只會攻，早晚守不住。兩人互不相讓，吵完又叫彩雲加一壺茶。"},{"type":"p","text":"另有一位綽號「海叔」的老人，年輕時在船上討生活，老來眼力不濟，見誰都愛講自己從前怎樣厲害。居萬最愛聽，因為兩人正好可以互相"}],"running":"第三十七回｜樹林與眾生","section":"第八部｜鞋與人情"},{"pdf":106,"blocks":[{"type":"p","text":"比賽吹噓。彩雲在屋裡聽見，常同孩子說：「你們阿公跟海叔，只要有一個人肯少講兩句，這條街就可以早點睡。」"},{"type":"p","text":"年輕時居萬最在意自己是不是眾人的中心；到了中年，他漸漸覺得只要屋前還有人坐，便算有些福氣。只是有福氣的人也會煩，老鄰居若連續三天來賒帳，他照樣板著臉，說要不就先還以前的。對方一走，他又問彩雲，那人家裡是不是出了什麼事。"},{"type":"p","text":"彩雲說：「你嘴上硬，心裡軟，偏偏軟的地方從不讓人看。」"},{"type":"p","text":"他笑道：「妳不是看見了？」"},{"type":"p","text":"「我看了幾十年，怎麼會看不見。」"},{"type":"p","text":"那時候另一條王姓人家的線，尚未好好記進故事裡。人們叫他樹林。若翻到較後來的記錄，又會看見王螢家三個字。兩個名字指著同一個人，可一張紙上改了名字，並不等於把此前的日子另過一遍。至於他與居萬究竟是哪一房、哪一輩，親屬們各有片段說法，還不能匆忙替他安上一個稱謂。與其先算親疏，不如先說他怎樣過日子。"},{"type":"p","text":"樹林同李心為談生意，有時像兩個人共守一座小小的城。一個以為城門該早些開，好叫人進來；一個卻先問倉裡的米夠不夠。樹林認得人快，話也接得快，聽到別人有新的點子，兩眼便亮起來。心為在旁邊記數字，不一定掃他的興，只把紙推過去，請他看看尚有哪些款項未收。"},{"type":"p","text":"「你每回都說這次不一樣。」她說。"},{"type":"p","text":"「這次確實不一樣。」"}],"running":"第三十七回｜樹林與眾生","section":"第八部｜鞋與人情"},{"pdf":107,"blocks":[{"type":"p","text":"「那你先告訴我，哪裡不一樣？」"},{"type":"p","text":"他本來有十句話可以回答，忽然被問得只剩下三句。樹林不怕別人反對，偏怕心為用這種平靜的口氣問他；她不是不同意，而是要他把一腔熱心換成誰都看得懂的數字。這比吵架還費工夫。"},{"type":"p","text":"有一日他替人打點一樁推廣的事，原先安排得熱熱鬧鬧，到了臨頭，印好的東西擺了一桌，真正願意留下來聽的人卻少。樹林起初說天氣不好，後來說地方選得不對，又怪旁人不懂變通。心為只問他一句：「那些沒有來的人，你有沒有問過為什麼？」"},{"type":"p","text":"樹林坐在桌前，良久才把袖子放下。他向來擅長替場面找理由，唯獨這回，一個理由也不能替桌上那疊紙付帳。第二天他便自己去問，先前不願聽的話，如今一條條聽回來。有人嫌說得太漂亮，有人只想把話講得簡單些；也有人原本想來，後來要接孩子，實在抽不出身。樹林回到家，第一件事不是辯解，而是拿筆把這些話都記下。"},{"type":"p","text":"心為看見，沒有稱讚，只替他挪開桌上的茶杯。他卻忽然笑了：「妳怎麼不說我這回終於學乖了？」"},{"type":"p","text":"「你學不學乖，且看下回。」"},{"type":"p","text":"這樣的夫妻，不是事事一致才走得下去。有的人靠同意彼此成全，有的人偏靠分歧，把對方從自己的執拗裡拖出來。樹林覺得自己最會做人情，卻未必總能把家人一句不動聲色的提醒聽進耳裡；心為懂得把事辦穩，卻也明白生意若只有穩，不一定走得到遠處。"}],"running":"第三十七回｜樹林與眾生","section":"第八部｜鞋與人情"},{"pdf":108,"blocks":[{"type":"p","text":"後來家裡有了李芸閑、李永彤。女孩子的世界自然不全裝得下父母的帳本：一個有自己的學習與興趣，一個也有自己的音樂與朋友。樹林有時說，孩子將來做什麼都好；說完見她們作了與自己不同的決定，又忍不住問得太細。心為在旁邊笑他：「你當初不是最不愛人家管？」他想了想，自己也笑。原來當年最討厭聽的一句「我是為你好」，人做了父親以後，竟最容易說出口。"},{"type":"p","text":"這些日子與和平島店前的閒談，並沒有事事碰得上；一個人在海邊靠街坊的人情過活，另一個人面對的可能是另一種帳本與另一種生意。可在家族的長路上，兩種人物恰好互相照見：居萬怕冷清，樹林怕錯過機會；居萬擅長說服人留下來，樹林擅長想人該怎麼走出去。兩人未必有過小說裡那樣完整的一場談話，性情的對照，卻能把同一個問題照得更清楚——人想讓別人相信自己，最難的有時是先肯承認自己會錯。"},{"type":"p","text":"店前的常客中，有個老人姓陳，手裡永遠拎一只布袋。他不肯說袋裡有什麼，每年三月卻總要到港邊站一會兒。旁人以為他在等船，後來才知道，他等的是一個沒有辦法再靠岸的人。"},{"type":"p","text":"有一年春天，他拿出一張久已折破的紙，上頭只剩幾行字。居萬想幫他看清，老人卻將紙收回去。不是不相信王先生，而是有些記憶太容易被旁人的好意改寫。居萬知趣，不再伸手，替他倒了一杯茶。"},{"type":"p","text":"「你天天那麼多人來，記得住嗎？」老人問。"},{"type":"p","text":"「有些記得，有些記不得。」"},{"type":"p","text":"「那就好。」"}],"running":"第三十七回｜樹林與眾生","section":"第八部｜鞋與人情"},{"pdf":109,"blocks":[{"type":"p","text":"居萬不解其意。老人又說：「人若什麼都記得，日子就沒辦法過。人若什麼都忘了，別人的日子又算什麼？」"},{"type":"p","text":"樹林第一次同居萬長談，是在一場人聲吵雜的聚會後。桌上還有沒收好的杯子，兩人留到最後，誰也不肯先說散。居萬談起自己年輕時做酒店，生意好時如何一天認識十個朋友；樹林聽著，忽問那些朋友如今可還常來。居萬一怔，笑說人各有忙。樹林不再問，只把杯子排好。這個比任何安慰都短的停頓，竟叫居萬想起春潮最後一夜的燈。樹林說自己近來看鞋，發現市面上樣式很多，真合腳的卻少。居萬立刻出主意，說不如做最漂亮、最能討年輕人歡心的。樹林卻答，年輕人買一次漂亮容易，要叫人穿過一年還肯再買，才算本事。居萬說這太慢，生意不趁勢怎能做大。樹林不服，說趁勢做大還得站得住腳，倒不如從一雙鞋開始。他說得認真，像不是談貨物，而是在談一個人應該怎樣活。李心為那時常替他整理進貨單，見他回來臉上帶氣，問又同誰爭。樹林說王先生認為自己膽子小。她把貨單遞給他，問明日第一批鞋若不合客人尺寸，是否也算膽子大。樹林讀著單子，突然笑了，說自己與居萬其實相像，都不喜歡有人看低。她說相像便相像，做買賣別學人家只顧面子。樹林點頭，半晌又說，居萬也並非沒有值得學的地方，至少他知道人願意為誰回頭。兩個男人後來仍會爭，爭哪個地段好，爭買賣要不要賒帳，也爭年輕人應不應該先闖一闖。晚輩見了以為他們不合，卻不知相處久了，有些真正的尊重原就不必表現成事事贊同。居萬欣賞樹林的穩，卻怕承認自己不夠穩；樹林佩服居萬的氣勢，卻擔心那氣勢會把自己帶去不願走的地方。兩個人在不同年歲裡互相看見一部分自己，也各自看見一部分自己不想成為的模樣。"}],"running":"第三十七回｜樹林與眾生","section":"第八部｜鞋與人情"},{"pdf":110,"blocks":[{"type":"p","text":"茶冷了，兩人誰也不再說話。這條街的人常是如此，上午為幾塊錢計較，下午又談起幾十年前的生死。從外頭看，都是坐在店門口閒聊，只有他們自己知道，閒話裡裝著怎樣沉重的東西。"},{"type":"chapter","text":"第三十八回｜樹林的第一雙鞋"},{"type":"p","text":"樹林一夜沒睡，還是把貨簽收了。"},{"type":"p","text":"鞋箱堆在牆邊，新的皮革味混著紙板味。送貨的人說這批賣得好，款式又新，他若不拿，隔壁街的人明天就會來搶。樹林不信，卻怕萬一是真的。他算過運費、貨款、店租，越算越像可以賺；李心為把那張紙翻過來，在背面寫了最壞的一個數字。"},{"type":"p","text":"「妳就是見不得我做大。」樹林說。"},{"type":"p","text":"心為沒有回嘴。她把計算紙塞進抽屜，第二天仍幫他點貨。"},{"type":"p","text":"開賣頭幾天，鞋果然好賣。樹林早上出門前都要多照一會兒鏡子，仿佛衣領整齊，店面便顯得又大了一點。有人叫他王老闆，他答得慢，等對方再叫第二次才回頭。"},{"type":"p","text":"第八天，一位婦人帶著孩子來退鞋。孩子的腳後跟磨破了。樹林接過鞋，發現兩隻鞋後緣縫線不齊。他知道這批貨剛來時自己看見過同樣的毛病，那時只挑走幾雙；其他的，他告訴自己未必每雙都有事。"},{"type":"p","text":"「穿過了不能退。」他說。"},{"type":"p","text":"婦人愣著：「小孩子不穿，怎麼知道不合腳？」"}],"running":"第三十八回｜樹林的第一雙鞋","section":"第八部｜鞋與人情"},{"pdf":111,"blocks":[{"type":"p","text":"店裡另有客人回頭看。樹林把鞋放到桌下，壓低聲音，說可以替孩子換一雙。婦人不肯，說家裡另有舊鞋可穿，只要退錢。兩人越說越響。後來樹林氣昏了頭，竟冒出一句：「誰曉得是不是你家孩子走路太粗？」"},{"type":"p","text":"婦人拉起孩子就走。孩子跌跌撞撞還回頭看那雙鞋，像怕它被丟在店裡。"},{"type":"p","text":"心為從後頭出來，問他方才說了什麼。樹林說沒有什麼。她朝門外看，見那婦人站在街角抹眼睛，便拿著錢追出去。他想攔，沒攔住。"},{"type":"p","text":"晚上心為把退貨放上桌，指著裡頭幾處做壞的地方。樹林竟先問：「今天是不是有人在店裡說我賣假貨？」"},{"type":"p","text":"「你不想知道孩子的腳怎樣？」"},{"type":"p","text":"「我有說不管嗎！」"},{"type":"p","text":"他把桌上的鞋掃到地上，鞋底碰地滾了一圈。心為站起來，兩人隔著桌子對看。屋裡還有幾十箱同樣的貨，紙箱貼著鮮紅的標籤，寫著新款上市。"},{"type":"p","text":"「明天不要再賣這批了。」心為說。"},{"type":"p","text":"「妳說停就停？貨款誰付？妳去付？」"},{"type":"p","text":"心為嘴唇抖了一下，拿起帳本便走。樹林伸手去抓她衣角，只扯下一小段線。他拿著那根線站在原地，越想越惱，後來倒了一杯酒。喝完再倒第二杯，總覺得自己遭人合夥欺負。"}],"running":"第三十八回｜樹林的第一雙鞋","section":"第八部｜鞋與人情"},{"pdf":112,"blocks":[{"type":"p","text":"第二天他仍開門，卻把那批鞋挪到最裡頭。有人指著問，他說缺碼。午時那婦人又經過門前，孩子換了一雙舊涼鞋。樹林看見，躲進倉裡，假裝在找貨。"},{"type":"p","text":"那天收店，心為沒有回來幫他算帳。樹林拉下鐵門，又拉開一截，往街口望了望。隔壁賣吃的婦人問他太太今晚不來了嗎，他說她娘家有事，說完才覺得自己講得太自然。他把店門重新拉好，回身發現玻璃櫃裡還擺著那雙被退回的鞋。他拿報紙蓋住，隔了一會兒又掀開，最後用鞋盒收進倉裡。晚飯時他坐在一排鞋箱中間，連便當都沒打開，聽見有人經過便趕緊站起，彷彿有人會來問他生意做得如何。收銀機還亮著，他按了幾個數字，螢幕跳出一筆不算差的總額。"},{"type":"chapter","text":"第三十九回｜蘇家的孩子"},{"type":"p","text":"林銀叔小時候姓蘇。再往前怎麼說、那一天究竟誰作了決定，後人各有各的版本。他自己活得長，卻不大肯提。"},{"type":"p","text":"有一回孩子問，從板橋到中和要走多久。銀叔正在磨一把鈍刀，答：「腳有力就快。」孩子追問那時候幾歲，他沒有答。刀在磨石上刷刷地響，像有人拿一把尺反覆劃同一個地方。"},{"type":"p","text":"那條路，後來家裡人講得愈來愈遠。有人說他一路哭，有人說他沒哭；有人說牽著他的手很緊，有人說走到半途便放開。故事裡那個做決定的大人常被講成壞人，這樣最容易講下去。至於當時有沒有欠債、田地是不是出了問題、屋裡究竟還有幾口飯，沒人能說清楚。"}],"running":"第三十九回｜蘇家的孩子","section":"第八部｜鞋與人情"},{"pdf":113,"blocks":[{"type":"p","text":"銀叔認得磨石的形狀，也認得礦坑裡潮濕的味道。他不認得那張被子上的刺繡出自誰手。童年的事像個破麻袋，抓起來，總漏一些。"},{"type":"p","text":"成家後，靜菊偶爾聽他半夜起身。她問要喝水嗎，他說沒有，便坐到屋外抽菸。一次天冷，她拿外套出去，他說不用。她沒走，把衣服搭在椅背上。"},{"type":"p","text":"「你以前家裡的人，後來有人找過你嗎？」她問。"},{"type":"p","text":"銀叔吸了一口菸，半晌才說：「找我做什麼？」"},{"type":"p","text":"靜菊原是替他難過，聽見這口氣，火卻上來：「我問一聲也不行？」"},{"type":"p","text":"他把菸捻熄：「要睡就去睡。」"},{"type":"p","text":"她一把抓回椅背上的外套，轉身進屋，門關得很響。兩人那夜分頭睡，第二天仍一道去買米。路過市場，有個賣布的女人認出靜菊，問她丈夫昨晚是不是又不高興。靜菊笑著說：「他哪天高興過？」"},{"type":"p","text":"銀叔在後頭聽見，竟也笑了。他自己笑得小聲，靜菊卻聽見了，氣得不肯理他。回家時他買了一塊花生糖放在桌上，孩子搶去吃，他一聲沒吭。"},{"type":"p","text":"後來銀叔去礦坑做事，衣褲帶回家的泥水黑得發亮。工友談起各人的老家，有人愛誇祖上，有人對自己從哪裡來連一句都說不清。銀叔只說中和。若有人再問，他便把話題轉到坑裡哪一層漏水、哪一班的工頭最難纏。"}],"running":"第三十九回｜蘇家的孩子","section":"第八部｜鞋與人情"},{"pdf":114,"blocks":[{"type":"p","text":"那年月底發薪，算下來少了一點。工友嚷著去找領班，他先說別惹事，等眾人走了，又一個人折回去問。領班問他方才怎麼不一起講，他說：「我怕你們人多，你聽不清。」工友知道了笑他狡猾，他也沒有否認。"},{"type":"p","text":"靜菊替他把工錢收進布袋，發現多出一枚十元硬幣，問他是不是拿錯。他搖頭，說工頭欠的。她不大相信，後來卻沒再問。孩子睡著後，兩人坐在燈下剝豆。她剝得快，他剝得慢，剝到最後，銀叔把自己的那小堆豆子推給她，像這樣便算替白天少說的幾句話賠禮。"},{"type":"p","text":"第二天孩子上學要填一張表，回來問父親祖籍那欄怎麼寫。銀叔拿筆寫了兩個字，才寫第一筆便停住。靜菊走過來，見他還沒寫好，沒催，只把旁邊的算術作業抽出來，叫孩子先做完。"},{"type":"p","text":"他終於把那欄填上。孩子看不懂，想問，銀叔已經拿表出去曬，說墨水還沒乾。風吹起紙邊，桌角壓著一塊磨刀石。"},{"type":"chapter","text":"第四十回｜兩條路上的孩子"},{"type":"p","text":"林銀叔童年走過的路，後人說起總覺得遙遠。從板橋走到中和，在地圖上不過一段距離，放在一個年幼、不得不離開原生家庭的孩子身上，便長得像一輩子。他後來極少細說經過，偶爾有人問，便笑著岔開，說那時的人走路多，腳力好。"},{"type":"p","text":"孩子最初是不懂「賣」字的。他知道有人叫自己去另一處，知道行李不能帶太多，知道路上大人走得比自己快。他也許怨，也許怕，或許只覺得餓；小說不能替一個沒有留下完整自述的人決定所有內心。可以想像的"}],"running":"第四十回｜兩條路上的孩子","section":"第八部｜鞋與人情"},{"pdf":115,"blocks":[{"type":"p","text":"是，當一個孩子被迫把昨日熟悉的門留在身後，他往後很長一段日子都會小心辨認，誰說的「回家」究竟指哪裡。"},{"type":"p","text":"到了礦區，他學會另一種辨認。看天色、看人臉色、看哪一道聲響意味著要快些退開。井下的黑不是夜裡那一種；夜裡人知天會亮，井下則要有人帶著燈，才知道前面有路。他將日子做成一段段班次，休息時把手洗得很久，指縫仍留灰。"},{"type":"p","text":"有次同伴問他日後想替孩子留什麼。他說留一雙好鞋。眾人笑，說好鞋能做什麼？他說腳底若不痛，孩子便敢走遠一點。這句話說完他自己也笑，像不好意思把願望講得太真。"},{"type":"p","text":"同一時期，海邊有人把酒館的燈裝得越來越亮，城市另有人在街市上叫賣。兩家人彼此還不認識，卻都在替下一代積攢一點能走得比自己更遠的可能。有人靠人情，有人靠辛勞，有人靠每回買賣省下一枚銅板。家族的相遇不是天定的戲劇，而是許多普通人的日子，終於在某個轉角撞在一起。"},{"type":"p","text":"兩條路上的孩子，走起來腳底下的聲音不同。海島上的孩子聽慣船笛，曉得雨來時水泥地會先發出一股潮氣；中和的孩子則熟悉市場開攤的鐵架碰撞，熟悉父親工衣上那一層洗不淨的黑。兩種聲音多年不曾相遇，直到後來兩個年輕人在一張飯桌上交換彼此的故事，才發覺原來「家」這個字，竟有那麼多種解釋。"},{"type":"p","text":"林銀叔從不鼓勵孩子把自己說得可憐。他有回見年輕人嫌鞋破得快，便把鞋底翻給他看，說自己小時候有雙鞋穿了不知多少路。年輕人問那雙鞋後來去哪裡，銀叔頓了一下，說早沒了。其實他想起的是自己被帶離原"}],"running":"第四十回｜兩條路上的孩子","section":"第八部｜鞋與人情"},{"pdf":116,"blocks":[{"type":"p","text":"來家門的那一天，鞋裡塞了粗布，走久了磨得腳跟生痛。許多年後他能用平常口氣講起這件事，並不意味當年不疼。"},{"type":"p","text":"另一邊，居萬看孩子們搶一雙新鞋，笑說將來人人都要穿好的。彩雲卻要他們先學會收好自己的東西。兩家父母的說法看似一個豪氣、一個節儉，骨子裡卻都在怕同一件事：怕孩子長大以後吃自己吃過的虧。只是每一代人都不願相信，父母的教訓究竟能保住多少日子。"},{"type":"p","text":"中和那些年的街道，晴天有塵，雨天有泥，鞋底沾了便不容易乾。銀叔成年後做礦工，每日早出晚歸，回家時衣服帶著一股洗不透的味道。鄰居有孩子見了會躲，有人笑他像從地底爬出來。銀叔不生氣，反問那孩子可知道地底也有路。孩子搖頭，他便彎腰用手指在地上畫出彎彎曲曲的線，說有些路沒有太陽照著，人還是得走。一回同工的男子受了輕傷，休養數日便擔心沒工錢。銀叔去探望，帶了點米和菜，坐在床邊說些不好笑的笑話。男子聽得不耐煩，說你若真有心，替我把工做了好不好。銀叔先愣住，隨後點頭，說能做的我做。兩人沉默片刻，竟同時笑了。那男子過後對人說銀叔嘴笨，做事卻不錯；銀叔聽聞，只說人家是給面子。他不懂自己這種不愛邀功的脾氣，日後也會叫兒子困惑：明明做了那麼多事，為何從不肯把功勞講大一點。一天傍晚，他的手因長年勞動疼得拿不穩筷子，卻見家裡孩子正吵著要多一塊肉，便把自己碗裡那塊夾過去。孩子當時並不知情，還覺得父親偏心。靜菊望見，沒有多說，只替他把飯拌鬆些。兩人日後也有爭執，算不上什麼永遠相敬如賓的夫妻；但在那些不易說出口的時候，他們有一套不用講好聽話也能互相接住的辦法。與王家的人相較，銀叔一生沒有多少可在席間高聲談論的往事。可若真把日子攤開，他的每一雙工作鞋、每一次夜裡咳嗽、每回從市場帶回來的小菜，都"}],"running":"第四十回｜兩條路上的孩子","section":"第八部｜鞋與人情"},{"pdf":117,"blocks":[{"type":"p","text":"自成一段別人不一定懂得的年月。家族小說若只為熱鬧而寫，這些人便永遠只能站在背景裡；可若少了他們，後頭那些人又哪裡來的路可走。"},{"type":"p","text":"後來曉芬與衞國初識，各自談起童年，談到一半便互相笑了。她說父親出門總有一群人認識，他說父親回家卻常不願說話。她問這樣不寂寞嗎，衞國問那樣不累嗎。兩人望著彼此，忽然覺得對方都說得有理。愛情尚未真正開始，他們已先認識一種陌生的生活。命運最不講理的地方，也許正是它常讓你在另一個人的缺點裡，看見自己家的影子。"}],"running":"第四十回｜兩條路上的孩子","section":"第八部｜鞋與人情"},{"pdf":118,"blocks":[{"type":"part","text":"第九部｜市場的路"},{"type":"chapter","text":"第四十一回｜靜菊的布"},{"type":"p","text":"林王靜菊在市場裡賣衣服。衣料的好壞，手一摸便知道；客人有沒有打算買，眼睛一瞧也大致有數。她不像居萬那樣喜歡把每個來客留住。碰上真要買的，她細細解釋；碰上只想壓價取樂的，她收起笑，叫人再去別處看看。"},{"type":"p","text":"清晨還沒開市，靜菊先將布疊好。紅的壓在深色上頭，淺的放最外側，讓經過的人一眼便看見。有人說她脾氣硬，銀叔卻知道她的硬有地方用。家裡若沒有人管錢，賺多少都會漏掉。"},{"type":"p","text":"某日雨急，市場入口積了水。有人急忙收攤，靜菊偏守著一位猶豫許久的婦人，替她把小孩的衣服挑到合身。那婦人錢不夠，想下週再買。靜菊沒講什麼漂亮話，只把衣服包起來，說等下次經過補上便是。"},{"type":"p","text":"銀叔聽了不高興：「妳不是常說不能賒？」"},{"type":"p","text":"「她真要穿。」"},{"type":"p","text":"「來買衣服的誰不說要穿？」"},{"type":"p","text":"靜菊看他一眼：「你以為我看不出來？」"},{"type":"p","text":"銀叔噤聲。他能分得清煤層和石頭，分不清婦人說話時那一點難堪；靜菊則相反。夫妻二人各守一門本事，吵起來像兩個小商販，活起日子卻又像一條繩上的結，拉緊了便分不開。"}],"running":"第四十一回｜靜菊的布","section":"第九部｜市場的路"},{"pdf":119,"blocks":[{"type":"p","text":"入夜，銀叔坐在屋前揉腳，靜菊替他放一盆熱水。銀叔說：「妳今天又替誰做了好人？」"},{"type":"p","text":"靜菊回：「你今天又在坑裡替誰扛了活？」"},{"type":"p","text":"兩人望了一眼，忽然都笑。人最會指責的，有時正是自己身上也有的毛病。"},{"type":"p","text":"靜菊攤上有件淺藍上衣掛了很久，價錢不高，卻始終賣不出去。客人嫌顏色淡，說穿了顯得沒精神，她不急著折價，反將衣服收在最乾燥的地方。隔月來了一位中年婦人，替女兒找面試的衣裳，摸著布料好久，問能不能便宜些。靜菊見她指尖粗糙，明白是肯做事的人，便把那件上衣取出給她試，說這布料挺，洗後也好整理。婦人說女兒長得瘦，怕穿起來不合。靜菊拿針線替她收了一點腰，動作極快，彷彿原本便在等這件衣服找到合適的人。她收的錢比掛牌略少，還叮囑衣服倒過來洗，不容易褪色。婦人走後，旁邊攤販笑她做生意不會賺。她答：「賺錢要緊，叫人穿得出去也要緊。」這話若讓居萬聽見，他大概也會喝采，只是喝采過後未必肯自己拿針。下午忽然下雨，菜攤的老闆娘替靜菊把衣架往裡推，兩人站在塑膠棚下，談的是米價與孩子考試。有人提起銀叔近日身體疲累，問她怎麼不叫丈夫換工作。靜菊把一件濕了的衣裳抖開，沒有回答。她不曉得如何用幾個字交代一家人的收入、學費與欠下的人情。她只說改日看情形。雨點落在棚上，說話得抬高嗓門，她忽然覺得這樣也好，誰都不容易追問。晚上收攤，她把剩下的衣服排好，交代孩子明早不要忘了帶書。銀叔問那件藍上衣賣了沒，她說賣了。他笑說妳真捨不得降價。她回道：「不降價的時候，別人說我太硬；真替人便宜了，又說我傻。生意做起來，倒像日日給人考試。」銀叔聽完大笑，咳了兩聲，又把笑壓下去。靜菊看著"}],"running":"第四十一回｜靜菊的布","section":"第九部｜市場的路"},{"pdf":120,"blocks":[{"type":"p","text":"他，忽然不想同任何人解釋自己這門小生意值多少錢。它至少讓一家人夜裡還有燈可點。"},{"type":"p","text":"她們那一代的女人，多半沒有機會將一生寫成書。市場裡一把尺、一疊布、一只找零錢的鐵盒，便是她們的年表。靜菊沒有想過後來的子孫會問祖母做過什麼，她只知道第二天開攤，衣服必須一件件掛好。"},{"type":"chapter","text":"第四十二回｜市場收攤以後"},{"type":"p","text":"靜菊把衣裳一件件摺回去時，市場裡已沒剩多少人。白天那些趕著還價、急著試穿的聲音散盡，只餘下掃地的沙沙響。她最喜歡這時候，因為錢算得清，布摺得平，誰今日占了便宜，誰明日還要再來，都不妨慢慢想。"},{"type":"p","text":"一次一位年輕婦人抱著孩子來，想替丈夫買件過年穿的襯衫，價錢卻始終談不攏。靜菊看她手裡紙鈔攥得皺，便問要不要換一件別的。婦人搖頭，說丈夫難得有件像樣衣裳，她想買好的。靜菊沒有再壓價，卻把自己原先另外收著的一件拿出來，說版型略不同，穿起來不差。這回兩人都不吃虧，婦人卻一再道謝。"},{"type":"p","text":"旁邊攤販說她心軟，做生意不該讓人看見底牌。靜菊只笑，說衣服是穿在身上的，不是供人贏嘴仗。回家銀叔聽了，問今日賺得可好。她說普通，隨即又把下午那位婦人的事講給他聽。銀叔點點頭，隔了片刻才說："},{"type":"p","text":"「妳也像在井下做工。」"},{"type":"p","text":"她不懂這比方。他說，井下要懂得看哪裡能撐，哪裡不能硬碰；她在市場裡，也一樣替一家人的日子找路。靜菊笑他終於會講幾句好話，卻在"}],"running":"第四十二回｜市場收攤以後","section":"第九部｜市場的路"},{"pdf":121,"blocks":[{"type":"p","text":"洗碗時忍不住想，這男人並非全然不懂她。他只是把溫柔藏得太深，非得繞個笨拙的比方才肯說出口。"},{"type":"p","text":"夜裡她替兒子整理校服，發現袖口短了半寸。孩子長大原來沒有聲音，等大人察覺時，布便先不夠了。她伸手量了量，盤算著下回進貨要順便找塊合適的布，心裡卻為那半寸莫名高興。"},{"type":"p","text":"市場收攤後的街，與白天像兩個人。白日裡人人聲音大，價錢砍得比刀快，晚間只剩鐵架碰著地的聲音，空菜籃一疊疊往外搬。靜菊把衣裳折起，最末才收尺。她這把尺用久了，頭一寸的刻度磨得發亮，像有人把一生最常從頭量起的地方都磨薄了。"},{"type":"p","text":"有位常來看衣服的婦人，連續幾個月都只問不買。同行攤販嫌她耽誤生意，叫靜菊別理。靜菊沒有聽。有一天那婦人終於選了一件深藍外衣，付錢時手指發抖，說是要去參加兒子的婚禮。她原先想穿舊的，怕被親家瞧不起；挑了這麼久，也怕自己穿上新衣不像自己。靜菊替她把袖口理平，說：「衣服是妳穿，不是衣服穿妳。」婦人聽了笑，竟又有點想哭。做衣裳生意的人有時賣出的不是布，是一個人願意站出去讓別人看見的勇氣。"},{"type":"p","text":"銀叔來接她收攤，肩膀上仍帶著礦坑裡的倦意。他看著她替婦人送到巷口，說妳這樣待客，明天還做不做生意。靜菊把空箱交他提，說若有一天沒人肯回頭找自己買衣服，那才叫做不成。銀叔原想回嘴，箱子一上肩，覺得並不重，便換了個話題，問今晚有什麼好吃。她說昨天剩下的菜。他說也好，剩菜熱一熱，比在坑裡吃冷飯強。"}],"running":"第四十二回｜市場收攤以後","section":"第九部｜市場的路"},{"pdf":122,"blocks":[{"type":"p","text":"市場最晚走的往往不是大攤販，而是那些生意剛夠養家的人。靜菊收好衣服，經過轉角賣菜的攤子，見老闆正數著零錢，便停下替他把塑膠袋捆緊。老闆說明日進貨又要漲了，生意難做。靜菊答哪一日好做過。兩人相視一笑，笑完各走各的路。市井人最要緊的情誼，很多時候只有這樣半句話，既不宣誓，也不久留。一晚衞國替母親搬貨，嫌衣服箱子沉，問為什麼不乾脆找人批發，自己坐在店裡收錢。靜菊說想得倒好，誰替你找客人？衞國說可以跑外面談，會說話就有生意。銀叔在旁笑他，說你嘴倒跟港邊的王先生一樣會講，還沒做便先講贏了。衞國不服，說總不能一輩子扛箱子。父親聽完沒有責備，反而沉默了。他想起自己年幼那趟長路，忽然覺得兒子若真能靠另一種本事吃飯，也許不是忘本，而是把一條路往前走了一段。隔天衞國主動替母親整理進貨單，發現幾種款式賣得快，幾種擱了整季。他拿鉛筆在旁註明，又提議把不同尺寸分開，讓客人找得容易。靜菊嘴上說你還懂賣衣服，手卻照著他的方式擺了。當日下午果然少翻了幾次箱，收攤時她多買了一樣菜。衞國得意，說看吧，做生意還是要用腦。母親答：「用腦是好，先別忘了明早來搬。」兩人笑著把門鎖好。這些年月並無驚天動地的場面，連家族相簿都少見有人特地替它們照相。可日後當有人把衞國的事業寫成一條筆直向上的線，靜菊若能讀到，或許會搖頭：哪裡是直的，先前摺了那麼多次衣裳，跑了那麼多條市場小路，才換來一個孩子有本事去試另一種生活。"},{"type":"p","text":"兩人一路走，隔著市街聽見別家孩子念書的聲音。靜菊忽然說，要讓衞國將來有本事自己選路。銀叔說讀書要錢，學手藝也要錢，天下哪有不花錢的路。她答：「那我們多做些。」銀叔想起兒時走過的那條長路，曾"}],"running":"第四十二回｜市場收攤以後","section":"第九部｜市場的路"},{"pdf":123,"blocks":[{"type":"p","text":"有人替他作決定，卻沒有問他願不願意。他看著妻子，終於說：「好。」那個字短得很，裡面卻裝著他一輩子不善說出的願望。"},{"type":"chapter","text":"第四十三回｜衛國少年"},{"type":"p","text":"林衞國少年時讀書、學做事，走過興南國小、中和國中與四海工專。他日後做業務，說話有分寸，遇人懂得看臉色。這些本領不是讀一冊書便學會的；有些來自學校，有些來自市場裡聽母親還價，也有些來自父親晚歸時沉默的背影。"},{"type":"p","text":"一個年輕人去拜訪客戶，總以為只要把話講得周全，事情就會照自己的意思走。衛國第一次受挫，回家吃飯時悶悶不樂。靜菊問他是不是沒賣出去，銀叔卻說：「沒賣出去就再去，不必在飯桌上討公道。」"},{"type":"p","text":"衛國當時不服。他覺得父親太不懂外頭的生意，人不只靠力氣，也要靠機會。等日後自己成了眾人眼中能幹的業務，他卻常想起父親那句粗直的話。因為客戶會改變心意，市場會改變方向，唯獨隔天起床還要再去，誰也代替不了。"},{"type":"p","text":"銀叔未必懂兒子的抱負。兩人有時為了一件家具該買好的還是省著用爭得很兇。衛國說賺錢就是要過好日子，銀叔說好日子不在買得起多少東西。靜菊聽久了，只將菜端上桌，叫兩個人先吃，別讓湯冷了。"},{"type":"p","text":"後來衛國與曉芬相識，兩家人的路才逐漸交會。那一年一場家族聚會，王居萬的聲音最響，林銀叔坐得最安靜；兩個長輩誰也瞧不上對方的生活法子，偏有兩個年輕人看見了彼此的心意。"},{"type":"p","text":"「你家怎麼人人都會說話？」衛國問曉芬。"}],"running":"第四十三回｜衛國少年","section":"第九部｜市場的路"},{"pdf":124,"blocks":[{"type":"p","text":"曉芬笑：「你家怎麼人人都把話藏著？」"},{"type":"p","text":"衞國在學校最怕一種題目：老師叫學生說長大以後想做什麼。有人說要當醫師，有人說要當官，也有人說要開大公司；他每次都想說得響亮些，筆到紙上卻又改成實在的答案。他怕別人以為自己不敢想，也怕父母看見他想得太遠，心裡難受。後來他學會先說「我要做得比現在好」，既留了雄心，也不必立刻交代如何辦到。一回班上要合作完成報告，原本分工好的同學臨時不來，剩下的工作全落在他身上。衞國氣得想直接告訴老師，卻又怕同學往後不理他。他想了一夜，第二天先把完成的部分交上，再請老師在全班面前說明合作的責任。老師誇他成熟，缺席的同學卻說他愛表現。衞國一時委屈，回家同母親講，靜菊聽完只問報告有沒有做完。他說做完了。母親點頭：「那便好。別人的嘴不是你能管的。」銀叔則問他，若下回仍分到同一組，還要不要做。衞國答當然不願。父親說可若事情一定要做，你也不能因為有人不可靠，便把自己交出去的承諾丟掉。這話不算好聽，衞國當下也沒有領情。過了幾年他做業務，遇見客戶臨時變卦，才想起父親那種笨拙的道理：你可以看清別人不可靠，卻不必因此把自己也變得不可靠。夜裡他坐在桌前填表，寫上自己的名字與學歷，忽然想到父親幼時曾換過姓氏。名字對他而言像一張通往外頭的車票，寫在紙上，便有機會讓不認識的人願意見他。父親卻曾經連自己叫什麼都未必做得了主。同一個家庭裡，兩代人對名字的重量竟相差這樣遠。他想問父親，話到嘴邊又停；有些故事不是不能問，而是要等問的人先學會怎樣聽。"},{"type":"p","text":"兩人互望一眼，各覺得對方說得不算錯。人生有時便這樣，一個人在自己家裡覺得理所當然的事，到了別人家卻變成稀奇。兩家日後的姻緣，"}],"running":"第四十三回｜衛國少年","section":"第九部｜市場的路"},{"pdf":125,"blocks":[{"type":"p","text":"不是誰救了誰，而是各自將一套不容易的生活，帶到同一張桌上重新擺放。"},{"type":"chapter","text":"第四十四回｜衛國第一次出遠門"},{"type":"p","text":"衞國出門前，靜菊偷偷在公事包裡塞了兩顆茶葉蛋。他在車上摸到，一時覺得丟臉，怕旁邊穿西裝的人聞出味道，便拿報紙包緊，塞到最底層。"},{"type":"p","text":"那個老闆聽完介紹，問的第一句就是：「你們這個價，憑什麼？」"},{"type":"p","text":"衞國準備了三天，心裡有十種答案。可對方不等他開口，便把競爭對手的報價往桌上一推：「有人比你少兩成。」"},{"type":"p","text":"衞國說品質不一樣。老闆問哪裡不一樣。他講了一項又一項，那人打起呵欠，轉頭跟助理聊起球賽。衞國臉燙得厲害，覺得旁邊幾個人都在笑他。"},{"type":"p","text":"「你要不要下次再來？」助理說。"},{"type":"p","text":"他本可起身離開，卻忽然不肯。把資料重新攤開，硬要把最後一頁講完。老闆的臉沉下來，按了桌上的鈴，叫人送客。"},{"type":"p","text":"衞國走出去時把門帶得太重，整條走廊都聽見。他在樓下站了半個鐘頭，想再回去，最後只買了一包菸。他其實不太會抽，點著後嗆得流淚，越咳越恨自己。"}],"running":"第四十四回｜衛國第一次出遠門","section":"第九部｜市場的路"},{"pdf":126,"blocks":[{"type":"p","text":"回家路上，他在車站吃了母親的茶葉蛋。蛋黃噎在喉嚨裡，水也沒買，只能站著慢慢吞。旁邊一個小學生看他吃得難受，問要不要借他水壺，他氣急敗壞地說不用。"},{"type":"p","text":"銀叔在門口等著。見他回來，先問：「有簽嗎？」"},{"type":"p","text":"「有啊。」衞國答得太快。"},{"type":"p","text":"父親停住。「真的？」"},{"type":"p","text":"「不相信你去問人。」"},{"type":"p","text":"銀叔便不問了。靜菊煮了菜，端給他時說蛋若吃不慣往後不塞。他立刻頂回去：「講多少次了，公事包不是便當袋。」"},{"type":"p","text":"靜菊愣了一下，笑著把盤子挪遠。衞國自己也嚇了一跳，可那句對不起偏偏卡在嘴裡，他只好埋頭吃飯。"},{"type":"p","text":"隔日公司主管打電話，問他為何把人得罪到連第二次約談都不肯給。衞國還想辯，對方已掛了。他走到屋外，見銀叔正蹲在小板凳上補一個塑膠桶，便坐在旁邊。"},{"type":"p","text":"「昨天沒簽。」他說。"},{"type":"p","text":"銀叔手上沒停。「我知道。」"},{"type":"p","text":"「你怎麼知道？」"},{"type":"p","text":"「你一進門，就先講成了。」"}],"running":"第四十四回｜衛國第一次出遠門","section":"第九部｜市場的路"},{"pdf":127,"blocks":[{"type":"p","text":"衞國的臉紅到脖子。他等父親罵他。銀叔將補好的桶翻過來，看了看底，說這樣應該撐不了多久，又繼續弄另一片塑膠。"},{"type":"p","text":"「你有沒有覺得我沒用？」衞國問。"},{"type":"p","text":"銀叔忽然瞪他：「你問我這種話做什麼？吃飽沒事做？」"},{"type":"p","text":"衞國便起身走了。他很想讓父親留住自己，父親卻像沒看見。他走到巷口，才發現口袋裡的名片夾不見了，回頭去找，又覺得不甘心。他在兩個路口中間站了許久，最後搭車回公司。"},{"type":"p","text":"那一天他沒有談成任何生意，甚至沒向母親道歉。"},{"type":"chapter","text":"第四十五回｜兩個男人，一張桌子"},{"type":"p","text":"王居萬第一次留意林衞國，覺得這年輕人客氣得有些過頭。叫他坐，他坐；叫他喝茶，他道謝；問他想做什麼生意，他說還在學。居萬自詡看人很準，心裡想：這樣規矩的人，做買賣怕吃虧。"},{"type":"p","text":"衛國卻覺得居萬是個熱心過剩的長輩。席間他三度提起自己在馬祖的經歷，兩度同旁人爭論做生意要膽大，末了又問年輕人喝不喝酒。衛國敬重他，卻不免想：若將來當老闆，事情不能只靠一張嘴。"},{"type":"p","text":"兩個人各有自己的道理，偏偏都不願先承認另一個人也有可取之處。"},{"type":"p","text":"彩雲端菜出來，見桌上已快吵到店面要開在哪條街，便說：「你們兩個還沒做成一家生意，倒先替天下的人都想好了怎麼賺錢。」"},{"type":"p","text":"王居萬大笑，說女人就是怕男人談大事。曉芬在旁聽見，放下筷子：「爸，事情要有人去做才算大，光講不算。」"}],"running":"第四十五回｜兩個男人，一張桌子","section":"第九部｜市場的路"},{"pdf":128,"blocks":[{"type":"p","text":"這句話像一顆小石頭，突然落進飯桌中央。居萬張口欲辯，彩雲先笑了。她並不是高興女兒頂撞丈夫，而是看見自己多年沒說盡的話，原來在下一代嘴裡也能講得那麼乾淨。"},{"type":"p","text":"飯後，衛國替居萬收拾桌上的杯子。居萬望著他，忽然說：「做生意啊，不能太老實。」"},{"type":"p","text":"衛國答：「也不能讓人覺得不老實。」"},{"type":"p","text":"居萬停了一下，點頭：「你這句倒講得好。」"},{"type":"p","text":"一生愛逞強的人，肯給晚輩這樣一句讚賞，已算讓出半步。"},{"type":"p","text":"王居萬見衞國，起初只當多了一個來家裡喝茶的年輕人。後來見他說話做事井井有條，便故意問些刁鑽的問題，譬如做生意要義氣還是要契約，婚後若妻子管帳是不是就不算男人。衞國聽完沒有急著討好，先想過才答：「義氣若真可靠，寫下來也不會變少。夫妻的錢若能算清，男人也不至於少一分體面。」居萬臉上不動聲色，心裡卻有些高興。彩雲端茶進來，聽見最後一句，便問衞國父母做什麼。青年說父親從事勞動工作，母親在市場賣衣服，講得自然，沒有把艱辛說成勳章，也沒有藏著怕人輕看。彩雲望著他，想起自己年輕時也曾拿一句話試過居萬：敢不敢聽真話。眼前這青年說的話並不漂亮，卻像真的想過要怎樣過日子。居萬送他出門時，忽然說女兒脾氣像母親，不是那麼容易哄。衞國答自己也不擅長哄人。居萬大笑，說那可難了。衞國卻說不擅長哄，總可以好好講。兩人一時都笑了，居萬心底卻想，自己這一生最不肯做的事情，怎麼在這年輕人嘴裡說得這樣簡單。等人走遠，彩雲說那青年還算踏實。居萬故意問她是不是因為人家講了幾句好聽話。她說：「你聽了只記得人家的話好不好"}],"running":"第四十五回｜兩個男人，一張桌子","section":"第九部｜市場的路"},{"pdf":129,"blocks":[{"type":"p","text":"聽，我聽的是他會不會把人當人看。」居萬不服，說自己難道不把人當人看。她望著他，沒有立刻回答。兩人相處了這麼多年，有些問題早已沒有簡單的標準答案；可那天屋裡的安靜，竟比一場爭辯更讓居萬記得。"},{"type":"p","text":"兩家之間並沒有天生和諧的配方。王家有海風、街坊與交際，林家有煤灰、市場與節省；一邊怕冷清，一邊怕不安穩。可是後來兩個年輕人決定共同生活，這些從前只屬於各家長輩的差別，便一點一點進到他們自己的日常裡。"}],"running":"第四十五回｜兩個男人，一張桌子","section":"第九部｜市場的路"},{"pdf":130,"blocks":[{"type":"part","text":"第十部｜海風與後人"},{"type":"chapter","text":"第四十六回｜彩雲見過的年輕人"},{"type":"p","text":"衞國去王家拜訪那天，帶的東西不貴重，卻包得整齊。居萬接過去，嘴上說人來就好，眼睛卻已把對方從鞋面看到眉眼。彩雲在一旁倒茶，見這年輕人說話從容，偶爾又有一點不願麻煩人的拘謹，心裡不由想起自己初識居萬時，他也是在一屋人前裝得極有把握。"},{"type":"p","text":"居萬很喜歡問男人做什麼、能做多少，說話越講越像在挑同行。他談馬祖，談酒店，談一條街上哪家店肯賒帳；衞國仔細聽，不時應答，並不急著表示自己有多大本事。居萬原先覺得他太安靜，後來又擔心太安靜的人心思深，一頓飯間替人換了好幾種評價。"},{"type":"p","text":"彩雲不與丈夫爭，她注意的是另一件事。曉芬進門時，衞國立刻替她把一把椅子讓出來，動作自然，像是不必等旁人稱讚也會做的事。彩雲心裡微微一動，又不肯因此便說他是好人。一個男人在外面有禮，不等於在家裡永遠有耐性；她比誰都知道這道理。"},{"type":"p","text":"散席後，居萬說這年輕人還不夠闖。彩雲說穩一點也沒什麼不好。居萬笑：「妳現在倒喜歡話少的。」她看他一眼：「我不是喜歡話少，我是喜歡做得到的。」居萬立刻要辯，忽然又笑了。他們夫妻老了，最擅長的仍是互相戳穿，只是有時戳穿以後，終於肯把話停在那裡。"},{"type":"p","text":"那晚曉芬站在窗邊，看遠處幾盞漁火。母親問她覺得如何，她沒答，只把窗扣好。彩雲也沒追問。愛情這事，年輕人最怕長輩替她說得太明"}],"running":"第四十六回｜彩雲見過的年輕人","section":"第十部｜海風與後人"},{"pdf":131,"blocks":[{"type":"p","text":"白；而做過女兒、做過妻子的女人知道，有些心事問得過早，便像把尚未長成的果子剝開，除了酸澀，也不會得到答案。"},{"type":"p","text":"彩雲看年輕人，有時比居萬準。居萬先聽對方怎樣稱呼長輩、會不會說好話；彩雲先看對方吃完飯是否將椅子推回原位，拿了別人的東西會不會順手道謝。她不認為小事便能決定一個人的品格，但一個人若連小事都覺得無須顧及，往後的大事多半也要旁人替他收拾。"},{"type":"p","text":"有回衞國來作客，曉芬恰好外出，他便陪居萬在店前坐。兩個男人很快從天氣談到買賣，從買賣談到軍中往事。居萬越說越響，衞國則一句句接著，偶爾提出疑問。彩雲端茶時見他並沒有為討好長輩就把每句話都附和，心裡反而安定一些。等居萬去招呼客人，她問衞國：「我家那個最會說。你有沒有什麼不敢跟他講？」衞國愣住，隨後笑說：「怕講太多，他嫌我年輕人不懂事。」彩雲答：「那總比什麼都不講好。」"},{"type":"p","text":"曉芬回來時，帶著一件自己的小煩惱。她在外頭替人辦事，明明照約定做了，對方卻臨時改口。她原想立刻回去理論，走到門口又覺得不值得。衞國聽完，問她最在意的是錢，還是對方把答應過的事當成沒發生。曉芬想了片刻，說後者。他說若如此，下一回便該在一開始說清楚。她笑他講得像開會，他說做事的人難免這樣。兩人忽然在同一句話裡聽見彼此的脾氣，一人怕被辜負，一人怕沒有證據，竟生出一種奇怪的親近。"},{"type":"p","text":"彩雲見過太多年輕人來往，有的穿得漂亮，話卻說得空；有的沉默寡言，做起事倒有幾分分寸。她不敢替女兒挑一個毫無缺點的人，因為這種人若真存在，大概也輪不到任何人來選。她只盼下一代遇見的人，至少肯承認自己會錯，且不把所有錯都變成別人不體諒的證據。有一夜曉芬問母"}],"running":"第四十六回｜彩雲見過的年輕人","section":"第十部｜海風與後人"},{"pdf":132,"blocks":[{"type":"p","text":"親，當年怎麼會願意嫁給爸爸。彩雲原本在摺衣裳，聞言停了一下，笑說那時不懂事。曉芬不信，說阿公阿嬤都講媽媽最有主意。彩雲便說，正因自以為有主意，才會想挑一個最難管的來試試。母女笑了許久，笑完她卻補一句：「人有時喜歡的，恰是最叫自己難受的那一部分。明知道，還是會喜歡。」曉芬聽不太懂，卻把這句話藏在心裡。後來衞國來訪，帶著一份替家中長輩挑選的禮物，包裝並不花哨。彩雲見他把鞋子擺在門邊，鞋尖朝同一方向，忽覺這青年與居萬年輕時大不相同。居萬最懂得如何讓人注意他，衞國卻像先想好不給旁人添麻煩。她一度以為後者便能使人幸福，旋即提醒自己：人的性格不像一雙鞋，看得出尺寸，便知道穿久了合不合腳。年輕人仍須用許多歲月，才學得會彼此的難。曉芬在另一間屋裡整理東西，隱約聽見父母談起衞國。她有些不快，覺得自己的日子怎麼又被長輩在一張桌上評估。可等人散後，她又忍不住問母親覺得那青年怎樣。彩雲只說是妳要相處的人，不是我。曉芬嫌她不肯給意見，彩雲笑道：「給妳一個意見：若有一天真要跟誰在一起，不要只問他能給妳什麼，也要看你們能不能一起面對失去什麼。」那句話說得像閒談，往後卻要在女兒身上得到新的意思。"},{"type":"p","text":"夜裡彩雲替丈夫整理藥盒，居萬問她對年輕人的看法。彩雲說還得看。居萬不耐煩，說做人哪能凡事都等看清才信。彩雲低頭將藥盒蓋好：「我年輕時就信過一個很會說話的人。如今還不是照樣過了幾十年？」居萬笑著伸手去拉她的衣角，問她這是在誇自己還是在罵自己。她也笑，說：「你自己想。」"}],"running":"第四十六回｜彩雲見過的年輕人","section":"第十部｜海風與後人"},{"pdf":133,"blocks":[{"type":"chapter","text":"第四十七回｜長青席上"},{"type":"p","text":"和平島的老人們，到了某個年紀，忽然都擅長說「以前」。以前哪裡有橋，哪裡有船，誰家門口的石頭最大，哪間店的魚丸最好吃，一個人說起便停不住。居萬很喜歡這些話，也很怕聽不見這些話。"},{"type":"p","text":"晚年，居萬開始把長青協會的活動看得極重。那不只是名冊與行程，也是一種願望：讓原來各自坐在家裡的老人，有理由穿好衣服出門；讓年輕人以為只剩回憶的人，還能替自己排下一個行程。"},{"type":"p","text":"籌備一次出遊，居萬忙得比當年開店還起勁。他一會兒要核對名冊，一會兒要去問車，一會兒又嫌別人把人數報得不清。彩雲在旁替他把紙夾好，說：「你這麼愛熱鬧，去郊遊倒像去帶兵。」"},{"type":"p","text":"他說：「人多就是要有人管。」"},{"type":"p","text":"「那你會不會聽人家說？」"},{"type":"p","text":"「當然會。」"},{"type":"p","text":"彩雲笑笑，沒有往下講。她知道居萬一急起來，最聽不見的往往正是人家在說什麼。"},{"type":"p","text":"出遊前夜，洪師傅找上門，說腳痛不想去了。居萬不高興，名冊早排好，車錢也算了，怎能說不去就不去。洪師傅坐在門口，嘴硬說讓位給別人。彩雲在裡面聽見，拿一張椅子出來，問他痛了幾天，還問要不要明早有人陪著去看醫生。"}],"running":"第四十七回｜長青席上","section":"第十部｜海風與後人"},{"pdf":134,"blocks":[{"type":"p","text":"洪師傅說了半晌，聲音漸漸低下去，原來不是腳最疼，是怕自己的身體跟不上大家，拖累人。"},{"type":"p","text":"居萬聽見，臉上有些掛不住。他剛才還把人當成名冊上一個空格，如今才想起那是跟自己下了幾十年棋的人。他坐下來，故作輕鬆地說：「那你明日不去，我帶照片給你看。等腳好再一起。」"},{"type":"p","text":"洪師傅哼了一聲：「誰要看你拍的？你每張都把自己放中間。」"},{"type":"p","text":"三個老人笑起來。彩雲將水杯放好，心裡想：人到了這把年紀，脾氣不會自己變好，頂多是知道哪些脾氣不值得再爭。"},{"type":"p","text":"長青協會的聚會有時像一場小小的朝會。誰早到、誰遲到，誰說自己的腰好些了，誰又故意把年歲少報兩歲，都能變成半個早晨的話題。居萬喜歡主持，卻也常因講得太久，被一位老婦人打斷：「王先生，你再講下去，午飯都成晚飯了。」眾人笑成一團，他也笑，終於肯把麥克風遞出去。一次活動要安排長者出遊，有人說去遠些才有意思，有人說坐車太久會累。居萬起初贊成遠行，覺得活動辦得大才有氣派。彩雲卻提醒有幾位長輩腳不方便，行程若太趕，人會受不了。居萬說可以請年輕人幫忙，她答：「不是什麼事有人扶，就能當作不累。」後來協會裡一位平日少說話的老人站起來，說自己其實只想去海邊喝茶，大家能坐著聊天就很好。居萬想了想，終於將原先排得滿滿的行程劃去一半。出遊那日天氣晴朗，車上有人唱起老歌，唱到一半忘詞，便有旁人接下去。居萬坐在前頭，原想高聲指揮，卻在窗外看見一段熟悉的岸線。那裡曾有他少年時愛逗人的地方，有他經營酒店時跑得最勤的路，也有幼年藏井蓋的傳說。島嶼並沒有因人的年歲而縮小，是他走過太多地方以後，才發現每條路都有回到原點"}],"running":"第四十七回｜長青席上","section":"第十部｜海風與後人"},{"pdf":135,"blocks":[{"type":"p","text":"的一刻。回家彩雲問他今天是否玩得高興。居萬說很好，還有人誇他安排得周到。她笑說能讓人好好坐著，比叫人人稱讚你了不起更難。他聽完沒有反駁，只問下回若去更近的地方，她肯不肯一同出門。彩雲問為什麼。他答：「妳若不來，誰提醒我別把大家累壞？」她嘴上嫌他油嘴滑舌，卻已開始盤算那日家裡的事情如何安排。"},{"type":"p","text":"一次長青出遊，車子才離開基隆不久，便有老人發現自己的藥忘在家裡。車上立即吵成一團，有人說回頭會遲到，有人說可以到目的地再找，還有人連當事人究竟帶了什麼藥也沒問清，就急著替他出主意。居萬拿著名冊站起來，要大家先別說話，卻越喊越吵。彩雲伸手拉住他的衣袖，請他先坐，轉身問那位老人自己現在有沒有不舒服、平日怎樣服藥，再請隨車人員協助聯繫家屬與醫療專業人員確認。"},{"type":"p","text":"車子暫停下來等待處理，大家開始抱怨行程耽擱。居萬心裡急，一度想說老人出門該自己留心；話到嘴邊，看見那人攥著衣袋，不住道歉，忽然想起年輕時許士官的家書。他便改口說：「人沒事最要緊，風景又不會因今天少看半小時就跑掉。」"},{"type":"p","text":"到了目的地，竟有人笑他這回當團長不威風。他跟著笑，說自己老了，命令沒當年靈。彩雲在旁替人分水，沒有拆他的台，反而悄悄將名冊上那位老人需要留意的事項補進去，約好下回行前先確認。居萬見了，問她怎麼想到這麼細。她抬眼：「你要把人帶出門，總不能只把名字帶出門。」"},{"type":"p","text":"晚上回到家，居萬把名冊攤在桌上，停在每一個名字前想一想。從前他最在意的是一趟活動有多少人來，如今第一次覺得能好好把人送回家，"}],"running":"第四十七回｜長青席上","section":"第十部｜海風與後人"},{"pdf":136,"blocks":[{"type":"p","text":"比出發時有多少掌聲更重要。他正要把話說給彩雲聽，回頭卻發現她已在燈下打起瞌睡。居萬沒叫醒她，只把散在她腳邊的紙收好，輕輕關了半盞燈。"},{"type":"p","text":"到了那一天，車子出發，居萬仍不忘站在前頭點名。有人嫌他囉嗦，有人說有他在比較安心。兩種話他都聽見了，回來以後卻只記得後一句。彩雲懶得揭穿，任他在晚飯時講得眉飛色舞。她知道一個人若連晚年這點虛榮也不准有，活著未免太清苦；只要別再叫全家替它付太重的代價便好。"},{"type":"chapter","text":"第四十八回｜新年照相館"},{"type":"p","text":"長青協會一次聚會後，有人提議大家拍照。居萬興致最高，叫人把椅子排齊，又嫌光線不夠，說應該站到門外去。彩雲在旁看著，笑他八十歲還像要帶兵。居萬說帶過兵的人做事總有效率，眾人聽了便笑，笑聲裡已有幾分寬容。"},{"type":"p","text":"拍照以前，一位老人忽然找不見眼鏡。大家四處幫忙，翻包、看椅子底下，連攝影的人也放下相機。最後眼鏡就在那老人額頭上，大家笑得更厲害。他自己也笑，笑完卻說：「往年我們這一桌，可還有幾個人。」滿屋忽而靜了一息，像一陣風掠過燈罩。"},{"type":"p","text":"居萬忙把話接過去，講了個舊笑話。他最怕熱鬧突然停，因為停下來，人便容易想起缺了誰。彩雲看著他，知道他的話多並非全是虛榮，也有一份不願承認的恐懼。這男人年輕時愛客人滿座，年老時愛老人出門，原來怕的始終是同一件事：自己熟悉的世界逐漸空下來。"}],"running":"第四十八回｜新年照相館","section":"第十部｜海風與後人"},{"pdf":137,"blocks":[{"type":"p","text":"相片拍好，每個人都說下回還要再聚。下回二字說來容易，可老人家的約定要同身體、天氣和時日商量，不能像年輕時說走便走。居萬一一握手，將人送到門口，直等最後一個背影消失才肯轉身。"},{"type":"p","text":"回家彩雲替他收好照片，問這麼多張都留嗎。他說都留。她拿起一張，指著角落：「這個人明明閉著眼。」居萬道：「閉著眼也是來了。」彩雲沒再笑他。人生到這個年紀，聚得齊原就比拍得好更要緊。"},{"type":"p","text":"那夜曉芬把一張照片放進家裡抽屜，碰到裡面更舊的一張，年輕男人站在燈牌前，笑得張揚。兩張照片隔了幾十年，像一個人對自己的兩次答辯。她沒有拿出來對照，只把抽屜輕輕推回去。第二代的故事正要接上，上一代留下的東西卻還遠未整理完。"},{"type":"p","text":"有一年大家約好到照相館拍合照。攝影師把一排椅子擺正，請長輩坐前面、晚輩站後面。居萬理所當然坐中央，先嫌燈太亮，後嫌旁邊的人站得不齊。彩雲叫他別再指揮，攝影師都快被他搶了工作。眾人笑得一團亂，快門偏在笑聲尚未止住時按下，留下幾張眼睛半閉、頭也歪著的照片。"},{"type":"p","text":"等照片洗出來，大家先挑自己好不好看。有人嫌臉圓，有人說年紀一大便禁不起鏡頭，只有孩子們指著後排一只伸到別人肩上的手哈哈笑。彩雲從中挑了一張，沒有挑最體面那張，而是挑一張居萬剛轉頭要說話、嘴角尚未收好的。她說這張像他。居萬不服，說自己明明有更精神的。她回道：「精神的你有許多，這張才是你平常的樣子。」"},{"type":"p","text":"照片背面本該記年月，最後卻只寫了「大家都在」。當時人人覺得這四個字足夠。誰會在滿屋笑聲裡想到，後來有些人真的會不在？多年後整"}],"running":"第四十八回｜新年照相館","section":"第十部｜海風與後人"},{"pdf":138,"blocks":[{"type":"p","text":"理照片的晚輩先認不出後排一位姑娘，再問前方那位老人是誰。彩雲一遍遍說名字，有些名字說得清，有些又得想很久；她忽然意識到，家族不是人一多便自然有歷史，還得有人記得，照片裡每一張臉曾經怎樣生活。"},{"type":"p","text":"拍合照那天，有位老人遲遲不肯入鏡。他坐在角落，說自己衣服不夠體面，照片留給別人便好。居萬一聽，立刻招呼他坐到前排，說大家都老了，哪還有人看衣裳。那老人仍然推辭，彩雲便從旁拿來一件乾淨外套，問合不合身。他試穿後笑了，終於坐下。居萬高聲喊快拍，彩雲卻提醒照相師先等一等，讓那老人把領口拉平。快門之前，忽有人說少了一個人。眾人左右尋找，才發現負責倒茶的阿姨仍在廚房裡忙。居萬想叫她快出來，話到嘴邊又轉成自己走進去，把茶盤接過手來。阿姨說自己只是來幫忙，不必照。居萬答：「你若不在，誰知道今日的茶誰泡的？」阿姨笑著出來，坐在最邊上。相片拍成後，她竟是第一個來索取的人。數年後，有人拿著照片追問每個人的名字。居萬認得一半，另一半想了半天仍記不住。彩雲不急，取出一張舊名單，對著座位逐一核對。有些人已不再出席，有些人搬去同孩子住，也有些姓名再問已問不到。晚輩嫌照片背後的字寫得潦草，她卻說那年忙，能記下便不錯。曉芬看著一張張臉，忽然明白照片最殘酷的地方：它將每個人都留在同一秒，卻沒辦法讓他們繼續同樣地活下去。收起照片時，彩雲又翻出一張年輕時的舊照，居萬站在最中間，神色飛揚。曉芬問旁邊的女人是誰，母親說那是酒店舊友，名字需再查。居萬從背後走來，瞄一眼便說認得，卻突然把話止住。彩雲望著他，並未追問。那一瞬間，一家人都明白，照片裡的人再年輕，也未必沒有不能一笑帶過的故事。"}],"running":"第四十八回｜新年照相館","section":"第十部｜海風與後人"},{"pdf":139,"blocks":[{"type":"p","text":"她看見一張更早的舊照，邊角泛黃，後頭有人寫了酒店的名字。居萬剛要把它抽出來講當年，彩雲卻先說：「不要只說你自己。旁邊的人呢？」他愣住，望向相片一側一位模糊的女子，終於承認自己想不起名字。這一刻他們兩人都安靜下來。若一個人當年被旁人記住的，只剩與王先生站在同一張相片裡的那一刻，那對她多不公平。"},{"type":"chapter","text":"第四十九回｜海風有名"},{"type":"p","text":"八十歲壽宴辦在三月。王居萬嫌桌上的花太大，擋了他看門口來客，叫服務生搬遠些。服務生搬了兩次，他又嫌太空。彩雲在旁說別折騰人，居萬當作沒聽見，仍伸長脖子往門口看。"},{"type":"p","text":"第一批來的是長青協會的舊識。有人拎著水果，有人帶照片，還有人一進門便嚷「王先生今日要喝三杯」。居萬聽得高興，說年輕時三杯算什麼。彩雲拿起水杯換到他面前，說：「你先把這杯喝了。」"},{"type":"p","text":"「妳在大家面前也管？」"},{"type":"p","text":"「我還能等人散了再管？」"},{"type":"p","text":"桌上笑起來。居萬趁人不留意，把水杯往旁邊挪。坐隔壁的老友伸手又推回來，說王先生現在有人管，是福氣。他把那人的手拍開，笑得滿面紅光。"},{"type":"p","text":"攝影的晚輩端手機來，問能否錄一段往事。居萬立即把領口整好，說從當兵講起。馬祖的風、軍營的夜哨、回基隆後如何開春潮，講得一桌人忽然安靜，等他往下說。其實那幾句他講過不下百遍；可今日的他比往日"}],"running":"第四十九回｜海風有名","section":"第十部｜海風與後人"},{"pdf":140,"blocks":[{"type":"p","text":"多了一點喘，往往一句話才講到一半，便要停一下。眾人不敢催，反替他接詞。"},{"type":"p","text":"說到春潮，一位舊客人提起麗華，問那姑娘後來上哪兒去了。居萬笑說做這行的，來來去去，怎麼可能都記住。後排卻有個女人回了一句："},{"type":"p","text":"「記不得就別講。」"},{"type":"p","text":"聲音不大，只夠半桌人聽見。有人以為是玩笑，跟著笑。居萬回頭找說話的人，對方已低頭給孩子夾菜。他想再說些俏皮話，彩雲卻忽然伸手，把晚輩拍攝的手機鏡頭蓋住。"},{"type":"p","text":"「夠了，別拍。」"},{"type":"p","text":"「媽，阿公講得正精彩。」曉芬說。"},{"type":"p","text":"「我說別拍。」"},{"type":"p","text":"年輕人手忙腳亂按下停止，手機卻還亮著，畫面正停在彩雲的臉上。居萬覺得顏面掃地，紅著臉道：「大日子，妳何必。」"},{"type":"p","text":"彩雲說：「你當我想來？」"},{"type":"p","text":"這一句把桌上的笑全打斷了。服務生端著最後一盤魚站在門外，不知該不該進去。曉芬走過來，將母親扶到外頭，彩雲一下甩開，說自己會走。她走得急，手袋掛到椅背，拉扯得椅子砰地倒下。"},{"type":"p","text":"走廊冷氣很強。曉芬追出來，問她怎麼了。彩雲靠在牆邊，手一直扣著手袋。「那支影片，你們誰都不准放出去。」"},{"type":"p","text":"「好，我會叫他刪。」"}],"running":"第四十九回｜海風有名","section":"第十部｜海風與後人"},{"pdf":141,"blocks":[{"type":"p","text":"「刪乾淨。」"},{"type":"p","text":"「媽，妳想說什麼？」"},{"type":"p","text":"彩雲張了張口，忽然問：「妳上次說妳手機可以把老照片修清楚，是真的？」"},{"type":"p","text":"曉芬被問得怔了。彩雲把手袋打開，裡頭塞著一張摺起來的相紙，紙背露出一角手寫的日期。她拿了出來，沒交給女兒，只用拇指在紙角上輕輕抹了兩下。"},{"type":"p","text":"宴會廳裡有人唱起生日歌，拍子參差，唱到半截又有人帶頭重來。隔著門，居萬的聲音仍最響。曉芬往裡頭看，看見父親朝門外找人，手裡捏著餐巾紙，臉上笑意還沒收好。"},{"type":"p","text":"「妳要進去嗎？」曉芬問。"},{"type":"p","text":"「等一下。」彩雲說。"},{"type":"p","text":"她低頭看照片，又把紙摺了回去，摺得太急，角上裂了一道小口。曉芬伸手想幫，她把照片放回袋裡，說：「妳先去。」"},{"type":"p","text":"曉芬回到席間，父親一把拉住她，問妳媽呢。她說在外面。居萬想站起，腳下卻碰到凳子，膝蓋一痛，跌坐回去。他低聲罵了一句，怕旁人聽見，又立刻笑著說沒事。曉芬扶住他，手上感到那老人忽然很重。"},{"type":"p","text":"「爸，你別逞強。」"},{"type":"p","text":"「我去看看她。」"},{"type":"p","text":"「我去就好。」"}],"running":"第四十九回｜海風有名","section":"第十部｜海風與後人"},{"pdf":142,"blocks":[{"type":"p","text":"他執意站起，走了兩步，停在門口，忽然忘了要往哪邊轉。曉芬叫他，他仍看著走廊盡頭。彩雲就在不遠處，正背著他同服務生說話。居萬本可喊她，卻沒喊。"},{"type":"p","text":"回席時有人又提往年到和平島做客的事，居萬照樣笑，笑到一半突然問：「麗華那時候，是不是有個妹妹？」周圍的人面面相覷。原先講得最熱鬧的老友也說記不清。"},{"type":"p","text":"彩雲回來坐下，沒再開口。蛋糕推來時，大家叫二老一塊切，居萬握住刀柄，彩雲手擱在他手背上。快門一閃，兩個老人看上去十分和氣。"},{"type":"p","text":"照片洗出來後，曉芬最先注意到的，是彩雲手袋口露出的那一小片泛黃紙角。"},{"type":"chapter","text":"第五十回｜下一個名字"},{"type":"p","text":"宴席過了三日，彩雲把兩只紙箱推到飯桌邊，叫曉芬有空就拿走。"},{"type":"p","text":"「舊帳，照片。再不整理，哪天被人當廢紙賣掉。」"},{"type":"p","text":"曉芬蹲下去翻。最上頭是幾張長青協會的合照，一個個老人都戴著帽子，笑得很用力；下面有春潮的舊名片、磨花的鏡子、少了蓋子的粉盒。母親明明說不要，見她拿起鏡子，卻伸手來搶。"},{"type":"p","text":"「這個壞了。」"},{"type":"p","text":"「壞了為什麼不丟？」"},{"type":"p","text":"「誰叫妳問那麼多。」"}],"running":"第五十回｜下一個名字","section":"第十部｜海風與後人"},{"pdf":143,"blocks":[{"type":"p","text":"兩人拉扯，鏡子啪地撞在桌角，裂痕又長了一點。曉芬先鬆手，彩雲反倒更生氣，把鏡子往箱底一塞，說她做事總是急。"},{"type":"p","text":"曉芬把帳簿拿出來。封面用線縫過，第一頁還寫著春潮的舊地址。翻到中間，她看見一個名字被藍筆圈住，旁邊有一筆錢。數字底下另有小字：「代收，勿告。」字跡很像母親，卻又稍微歪斜。"},{"type":"p","text":"「妳還替誰收過錢？」"},{"type":"p","text":"彩雲停了手上的動作。「很久的事。」"},{"type":"p","text":"「這個名字我認識？」"},{"type":"p","text":"「妳不要碰那頁。」"},{"type":"p","text":"曉芬沒翻過去。母親伸手來抽，帳頁被兩人扯破一道口子。彩雲臉色一變，罵了一句粗話，連自己都嚇著了。她坐在椅子上，過了好一會兒才說：「我怎麼生了妳這個脾氣。」"},{"type":"p","text":"「妳教的。」曉芬說。"},{"type":"p","text":"母女互望片刻，竟都差一點笑了。笑意還沒出來，電話就響。"},{"type":"p","text":"曉芬接起，聽見一個陌生男人叫她的名字，停了半天，才想起這聲音從前在哪裡聽過。對方說只是問候，問她母親是不是還好。她說有事直接講。對方低聲道：「帳本妳看到了？」"},{"type":"p","text":"「你是誰？」"}],"running":"第五十回｜下一個名字","section":"第十部｜海風與後人"},{"pdf":144,"blocks":[{"type":"p","text":"那人沒答，只說下週有人會帶一份文件來，叫她別先拿去問王居萬。曉芬立刻問憑什麼；對方把電話掛了。她站著沒動，手機螢幕逐漸暗下去。"},{"type":"p","text":"彩雲坐在桌邊，竟一句都沒問。"},{"type":"p","text":"窗外一輛小貨車倒車，警示聲斷斷續續。曉芬把帳簿合起，說她要拿去影印。彩雲搶先站起：「不准！」"},{"type":"p","text":"「妳不讓看，為什麼又叫我收？」"},{"type":"p","text":"「我叫妳收，沒叫妳翻。」"},{"type":"p","text":"曉芬猛地把箱子推回去，蓋子散了一地，春潮的老名片滑到冰箱底下。母親弓著腰去撿，她站在旁邊，既想幫又不肯彎身。最後彩雲扶著椅腳慢慢站直，把名片塞進衣袋，沒有看她。"},{"type":"p","text":"晚上曉芬回家，把帳簿放在桌上。她想起很久以前也有人拿著一份算得極漂亮的資料向她保證，錢很快會回來；當年她答應之前，誰也沒告訴。現在這張舊帳偏偏由母親親手交給她，竟仍留著空白。"},{"type":"p","text":"她找出一個資料夾，把帳頁逐張拍照。翻到最後，看見一只舊鞋盒的發票，抬頭寫的是樹林早年做買賣用的商號。她正要轉給樹林，手機跳出一則訊息，是俊明：「妳明天有空嗎？有件事先別跟爸媽說。」"},{"type":"p","text":"未讀訊息上頭，還有美玲昨天留的一句：「姊，我想搬出去。不要先問原因。」"}],"running":"第五十回｜下一個名字","section":"第十部｜海風與後人"},{"pdf":145,"blocks":[{"type":"p","text":"曉芬盯著兩行字。這時門鈴響了，她以為是鄰居。門外沒人，地上放著一個沒有寄件人的牛皮紙袋。袋口沒封緊，露出半張法院信封的影子。"},{"type":"p","text":"她沒有立刻撿。"},{"type":"p","text":"樓梯間有腳步聲往下走，她伸頭出去，只看見一個人拐過轉角。她喊了一聲，對方沒停。回屋後她才拿起紙袋，抽出裡面的第一張紙。那不是寫給她的，收件人是另一個她認得的人。"},{"type":"p","text":"這一夜，王家的三個孩子都沒有睡好。"},{"type":"heading","text":"史料與創作說明"},{"type":"p","text":"• 二二八事件紀念基金會相關基隆社寮島史料：https://www.228.org.tw/ 。二二八大背景為歷史事實，小說角色之對話與細節為虛構。"},{"type":"p","text":"• 國家文化記憶庫、國立臺灣歷史博物館之基隆酒家文化及北臺灣礦業勞動資料，供時代環境參考，不代表曾經發生於王家。"},{"type":"p","text":"• 家族口述整理（截至2026 年10 月）尚有年份、原始照片、醫療記錄、學籍及在場見證人待核對。特別是家中自傷危機、酒家經營、林銀叔童年離散及王樹林鞋業發展的具體事件，仍須進一步訪談與確認。"},{"type":"p","text":"作品屬以家族資料改編之文學虛構，非家族史實的唯一版本。"}],"running":"第五十回｜下一個名字","section":"第十部｜海風與後人"},{"pdf":146,"blocks":[{"type":"heading","text":"編輯版本與進度"},{"type":"p","text":"〔第一輪舊紀錄〕第一輪五十回試改稿曾深度重寫九回，另有五回增加場景，當時全文逾七萬漢字（含卷首與附錄）。第二輪為避免反覆說理而刪減約四千餘漢字，目前約六萬五千漢字（含編輯附錄）；仍須以真正的新情節補寫，不能冒稱七萬字文學定稿。"},{"type":"p","text":"私人家族文學創作稿；人物相關未經核實的私生活與婚姻情節不得對外宣稱為史實。第二輪修訂記錄｜2026 年10 月10 日"},{"type":"p","text":"本次作實質整回重寫：第6、8、16、22、35、39、49、50 回。集中處理人物語氣、行動先於評論、場景因果、晚年鏡頭與下一代交棒。第一輪已重寫之第13、18、28—31、38、44 回及部分新增場景繼續保留，未經第二輪全面重寫之回目仍可能具有顯著重複論述，不能將整稿視為最終文學定稿。"},{"type":"p","text":"小說中居萬當兵的信件事故、酒店搜包、合股簽署、舊人來店等為虛構敘事，不屬家族事實陳述。第二輯涉及愛情金錢糾葛或婚姻爭議的線索均應避免使讀者推認為特定在世親屬之既定真實行為。"},{"type":"heading","text":"編輯者備考｜第一輪"},{"type":"p","text":"事重寫紀錄"},{"type":"p","text":"敘"},{"type":"p","text":"修訂說明"}],"running":"第五十回｜下一個名字","section":"第十部｜海風與後人"},{"pdf":147,"blocks":[{"type":"p","text":"本版是 敘事風格的第一輪實際試改，並非五十回全部重寫。針對重複說理、人物過度理性與關鍵事件缺少戲劇後果，已重新撰寫第十三、十八、二十八、二十九、三十、三十一、三十八、四十四、五十回九個回目；另於第十五、二十二、二十四、三十九、四十九回增加關鍵場景；其中第二十八至三十一回已統一時間線，避免同一場危機重啟。其他章回仍延續此前七萬字擴寫稿，還需要同樣標準的逐回校改。"},{"type":"p","text":"全書採家族史料衍生之 虛構小說；新增對話、人物言行及金錢糾紛不應被解讀為真實家人的經歷。"},{"type":"heading","text":"前版卷首識（移至備考，避免代替小說開場）"},{"type":"p","text":"要寫一個人，最容易的是先替他定性。說他仁厚，便把失足說成誤會；說他風流，便把恩義說成作態。可那些與他共同過了一輩子的人知道，世上偏沒有如此省事的好人壞人。"},{"type":"p","text":"王居萬擅長與人人談笑，並不表示他能在家中說清自己；彩雲能冷靜地算帳，並不表示她不渴望愛情；春潮酒店的女子在紅燈底下工作，並不表示她們甘願被人當成故事裡的一抹顏色；林銀叔與靜菊被生活壓著走，也不代表他們的生命只剩苦難。這部小說拒絕把誰寫成全然的善或惡，它所追索的是：人有時清楚自己應當成為什麼模樣，卻偏偏不能一直做得到。"},{"type":"p","text":"小說取材於和平島／社寮島地方歷史與家族口述，部分關於王居萬的軍旅背景、酒店經營、和平島生意、長青協會及夫妻家庭的線索，尚待向當事人和原始文件求證。二二八事件中「年幼王居萬在井蓋下躲避」為尚未查明時間、地點、見證人的家族記憶。依其八十歲壽宴推估，1947 年他"}],"running":"第五十回｜下一個名字","section":"第十部｜海風與後人"},{"pdf":148,"blocks":[{"type":"p","text":"約一至兩歲，因此小說採由成人保護幼兒的設定。阿泉、素珍、麗華、阿綺、月琴、春潮及其他若干人物、對話與場景均屬虛構或合成。"},{"type":"p","text":"涉及家族情感危機的情節，本稿從救助、後果和人物感受寫起，不描摹自傷技術細節，也不擅自推測個人動機；第二代未來涉及金錢損失、婚姻背離、離婚訴訟的構想，現階段只做文學伏筆，不把相關負面行為認定為在世人物的史實。若向外公開，應另以化名、合成人物與情節去辨識化。"},{"type":"p","text":"這是第一輯第一代的五十回小說正文，並非整套二十五冊完成版。情節依家族口述與時代背景作小說化重構，某些人物及衝突純屬虛構。"}],"running":"第五十回｜下一個名字","section":"第十部｜海風與後人"}]};